C     GENERATED by tools/extract_shaw.py; see vendor/shaw303/PROVENANCE.json.
C     USDA-ARS SHAW 3.0.3: GOSHAW
      SUBROUTINE SHP_GOSHAW (JULIAN, HOUR, YEAR, NHRPDT, WWDT, DTIME, INITAL, NC, NSP, NR, NS, TOLER, LEVEL, MZCINP,
     >NRCHANG, INPH2O, MWATRXT, LVLOUT, IVLCBC, ITMPBC, TSAVG, NPLANT, PLTHGT, PLTWGT, PLTLAI, ROOTDP, DCHAR, TCCRIT,
     >RSTOM0, RSTEXP, PLEAF0, RLEAF0, RROOT0, PCANDT, CANALB, CANMA, CANMB, WCMAX, PINTRCP, XANGLE, CLUMPNG, ITYPE,
     >ISTOMATE, STOMATE, ZC, TCDT, TLCDT, VAPCDT, WCANDT, ZSP, DZSP, RHOSP, TSPDT, DLWDT, ICESPT, WLAG, STORE, SNOWEX,
     >ISNOTMP, SNOTMP, ZR, RHOR, TRDT, VAPRDT, GMCDT, GMCMAX, ZRTHIK, RLOAD, COVER, ALBRES, RESCOF, RESTKB, DIRRES, ZS,
     >TSDT, VLCDT, VICDT, MATDT, CONCDT, ICESDT, SALTDT, ALBDRY, ALBEXP, DGRADE, SLTDIF, ASALT, DISPER, ZMSRF, ZHSRF,
     >ZERSRF, ZMSP, ZHSP, HEIGHT, POND, PONDMX, ALATUD, SLOPE, ASPECT, HRNOON, CLOUDS, DECLIN, HAFDAY, SUNHOR, TMPDAY,
     >WINDAY, HUMDAY, PRECIP, SNODEN, SOITMP, VLCDAY, SOILXT)
      COMMON /SHP_RESULT/ SHP_RESULT_VALUES(320)
      REAL SHP_RESULT_VALUES
      REAL SHP_CANOPY_EXCHANGE, SHP_CANOPY_BEFORE, SHP_CANOPY_AIR_WATER
      EXTERNAL SHP_CANOPY_AIR_WATER
      INTEGER SHP_FORCED_REFINEMENT
      COMMON /SHP_OPTIONS/ SHP_CANOPY_WATER_TOL, SHP_CANOPY_JACOBIAN
      REAL SHP_CANOPY_WATER_TOL
      INTEGER SHP_CANOPY_JACOBIAN
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      COMMON /SHP_MATRIX/ A1(350), B1(350), C1(350), D1(350), A2(350), B2(350), C2(350), D2(350)
      COMMON /SHP_WINDV/ ZH, ZM, ZERO, USTAR, STABLE, CONRH, CONRV, ZHLOG, ZMSUB, ZHSUB, ZERSUB, WINDC(11), WINDR(10)
      REAL LF, LV, LS, MELT
      REAL SOILXT(99)
      REAL DCHAR(8), CANALB(8), PINTRCP(8), XANGLE(8), CLUMPNG(8), TCCRIT(8), RSTOM0(8), RSTEXP(8), PLEAF0(8),
     >RLEAF0(8), RROOT0(8), STOMATE(8, 10), ZC(11)
      REAL DGRADE(10), SLTDIF(10), ASALT(99), DISPER(99)
      REAL LWCAN(9, 10), LWSNOW, LWRES(10), LWSOIL, LWDOWN(11), LWUP(11), SWCAN(9, 10), SWSNOW(200), SWRES(10),
     >SWDOWN(11), SWUP(11)
      REAL ZS(99), TS(99), TSDT(99), MAT(99), MATDT(99), CONC(10, 99), CONCDT(10, 99), VLC(99), VLCDT(99), VIC(99),
     >VICDT(99), QSL(99), QSV(99), XTRACT(99), FLOLAT(99), US(99), SS(99), TK(99), CS(99), SALT(10, 99), SALTDT(10, 99),
     >SINK(10, 99), ROOTXT(99), TOTFLO(99), TOTSINK(99), TOTLAT(99)
      REAL BTS(99), BMAT(99), BCONC(10, 99), BVLC(99), BVIC(99), BSALT(10, 99)
      REAL RHOR(10), ZR(10)
      REAL TR(10), TRDT(10), VAPR(10), VAPRDT(10), GMC(10), GMCDT(10), UR(10), SR(10), QVR(10)
      REAL BTR(10), BVAPR(10), BGMC(10)
      REAL TC(11), TCDT(11), TLC(8, 10), TLCDT(8, 10), VAPC(11), VAPCDT(11), WCAN(10), WCANDT(10), PCAN(8), PCANDT(8),
     >TRNSP(9), UC(10), SC(10), PLTHGT(8), PLTWGT(8), PLTLAI(8), ROOTDP(8), QVC(10)
      REAL BTC(11), BTLC(8, 10), BVAPC(11), BWCAN(10), BPCAN(8)
      REAL ZSP(200), DZSP(200), RHOSP(200)
      REAL TSP(200), TSPDT(200), DLW(200), DLWDT(200), USP(200), SSP(200), QVSP(200), TQVSP(200), WLAG(11)
      REAL BTSP(200), BDLW(200)
      REAL DELTA(350), DELNRG(350), DELWTR(350)
      INTEGER HOUR, HRSTRT, YEAR
      INTEGER LEVEL(6), LVLOUT(20)
      INTEGER ITYPE(8), HTORDR(8)
      INTEGER IBICES(99), ICES(99), ICESDT(99), ICESP(200), ICESPT(200)
      CHARACTER*1 BCKSPACE
      COMMON /SHP_SV_GOSHAW/ NPRINT, MAXSTP, MINSTP
C     Mutable SAVE initialization moved to SHP_SAVE_INITIAL_VALUES.
      SHP_CANOPY_EXCHANGE=0.
      BCKSPACE = CHAR(8)
      IF (INITAL .EQ. 0) THEN
      DO 10 I=1, NS
      IF (INPH2O.NE.1) THEN
      IF (VLCDT(I) .LE. SOILWRC(I, 4)) THEN
      WRITE (6, *) ' *** Input initial soil water content is less ***' ,
     >' *** than or equal to residual water content. ***'
      WRITE (6, *) ' *** Input initial soil water content is less ***' ,
     >' *** than or equal to residual water content. ***'
      WRITE (6, *)
      WRITE (6, *) ' ===> Simulation aborted; Press Enter to end'
      CONTINUE
      STOP 71
      END IF
      CALL SHP_MATVL1 (I, MATDT(I), VLCDT(I), DUMMY)
      ELSE
      CALL SHP_MATVL2 (I, MATDT(I), VLCDT(I), DUMMY)
      VICDT(I)=0.0
      ICESDT(I)=0
      END IF
      IF (TSDT(I) .LE. 0.0) CALL SHP_FROZEN (I, VLCDT, VICDT, MATDT, CONCDT, TSDT, SALTDT, ICESDT)
   10 CONTINUE
      POND=0.0
      STORE=0.0
      SNOWEX=0.0
      DO 15 I=1, 11
      WLAG(I)=0.0
   15 CONTINUE
      IF (ZRTHIK .GT. 0.0) THEN
      CALL SHP_RESIDUE (NR, NRCHANG, INITAL, ZR, RHOR, TRDT, VAPRDT, GMCDT, RLOAD, ZRTHIK, COVER, DIRRES, TMPDAY,
     >HUMDAY, NSALT, TSDT, MATDT, CONCDT)
      ELSE
      NR = 0
      END IF
      IF (NPLANT.NE.0) THEN
      SHP_CANOPY_BEFORE=SHP_CANOPY_AIR_WATER(NC, ZC, VAPCDT)
      CALL SHP_CANOPY (NPLANT, NC, NCMAX, NSP, 0, MZCINP, ITYPE, HTORDR, INITAL, PLTHGT, PLTWGT, PLTLAI, RLEAF0, ZSP,
     >ZC, TC, TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN, WCANDT, WCMAX, PCANDT, CANMA, CANMB, TMPDAY, HUMDAY)
      SHP_CANOPY_EXCHANGE=SHP_CANOPY_EXCHANGE+(SHP_CANOPY_AIR_WATER(NC, ZC, VAPCDT)-SHP_CANOPY_BEFORE)
      IF (MZCINP.LE.0 .AND. NC.GT.0) CALL SHP_RTDIST (NPLANT, ITYPE, NS, ZS, ROOTDP, RROOT0)
      ELSE
      SHP_CANOPY_BEFORE=SHP_CANOPY_AIR_WATER(NC, ZC, VAPCDT)
      NC=0
      SHP_CANOPY_EXCHANGE=SHP_CANOPY_EXCHANGE+(SHP_CANOPY_AIR_WATER(NC, ZC, VAPCDT)-SHP_CANOPY_BEFORE)
      NCMAX=0
      END IF
      HRSTRT=HOUR-NHRPDT
      CONTINUE
      CONTINUE
      CONTINUE
      CONTINUE
      ELSE
      IF (NPLANT .GT. 0) THEN
      SHP_CANOPY_BEFORE=SHP_CANOPY_AIR_WATER(NC, ZC, VAPCDT)
      CALL SHP_CANOPY (NPLANT, NC, NCMAX, NSP, 0, MZCINP, ITYPE, HTORDR, 1, PLTHGT, PLTWGT, PLTLAI, RLEAF0, ZSP, ZC, TC,
     >TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN, WCANDT, WCMAX, PCANDT, CANMA, CANMB, TMPDAY, HUMDAY)
      SHP_CANOPY_EXCHANGE=SHP_CANOPY_EXCHANGE+(SHP_CANOPY_AIR_WATER(NC, ZC, VAPCDT)-SHP_CANOPY_BEFORE)
      IF (MZCINP.LE.0 .AND. NC.GT.0) CALL SHP_RTDIST (NPLANT, ITYPE, NS, ZS, ROOTDP, RROOT0)
      ELSE
      SHP_CANOPY_BEFORE=SHP_CANOPY_AIR_WATER(NC, ZC, VAPCDT)
      NC=0
      SHP_CANOPY_EXCHANGE=SHP_CANOPY_EXCHANGE+(SHP_CANOPY_AIR_WATER(NC, ZC, VAPCDT)-SHP_CANOPY_BEFORE)
      NCMAX=0
      END IF
      IF (NRCHANG .GT. 0) THEN
      IF (ZRTHIK .GT. 0.0) THEN
      CALL SHP_RESIDUE (NR, NRCHANG, INITAL, ZR, RHOR, TRDT, VAPRDT, GMCDT, RLOAD, ZRTHIK, COVER, DIRRES, TMPDAY,
     >HUMDAY, NSALT, TSDT, MATDT, CONCDT)
      ELSE
      NR = 0
      END IF
      END IF
      IF (LEVEL(1) .GE. 1) THEN
      CONTINUE
      END IF
      END IF
      WDT=WWDT
      WT=1.-WDT
      DT=DTIME
      NTIMES=1
      NDT=1
      MAXNDT=NHRPDT*80
      MAXDBL=MAXNDT
      TA = TMPDAY
      TADT=TMPDAY
      HUM = HUMDAY
      HUMDT=HUMDAY
      WIND=WINDAY
      CALL SHP_VSLOPE (DUMMY, SATV, TMPDAY)
      VAPA=HUM*SATV
      VAPADT=VAPA
      IF (ITMPBC .LE. 0) THEN
      TSDT(NS)=SOITMP
      ELSEIF (ITMPBC .EQ. 1) THEN
      CALL SHP_SOILTK (NS, TK, VLCDT, VICDT)
      CALL SHP_SOILHT (NS, CS, VLCDT, VICDT, TSDT, MATDT, CONCDT)
      IF (TSDT(NS).LE.0.0) THEN
      TSNS = TSDT(NS)
      VLCNS = VLCDT(NS)
      IF (TSDT(NS-1) .GT. TSDT(NS)) THEN
      TSDT(NS) = TSDT(NS) + 1.0
      ELSE
      TSDT(NS) = TSDT(NS) - 1.0
      END IF
      CALL SHP_FROZEN (NS, VLCDT, VICDT, MATDT, CONCDT, TSDT, SALTDT, ICESDT)
      CS(NS) = CS(NS) + ABS(RHOL*LF*(VLCNS-VLCDT(NS)))
      TSDT(NS) = TSNS
      CALL SHP_FROZEN (NS, VLCDT, VICDT, MATDT, CONCDT, TSDT, SALTDT, ICESDT)
      END IF
      DAMPNG=SQRT(2.*TK(NS)/CS(NS)/1.99238E-07)
      DZS = ZS(NS)-ZS(NS-1)
      C1DDT = (1. + 2.*DZS/DAMPNG)/DT
      TSDT(NS) = TSDT(NS) + (-2.*TK(NS)/CS(NS)/DAMPNG/DZS/C1DDT) *(TSDT(NS)-TSDT(NS-1)) - 1.99238E-07*(TSDT(NS) -
     >TSAVG)/C1DDT
      ELSE
      TSDT(NS)=TSDT(NS-1)
      END IF
      IF (IVLCBC .GT. 0) THEN
      IF(VICDT(NS-1).LE.0. .OR. VICDT(NS).GT.0.)MATDT(NS)=MATDT(NS-1)
      VLC1=VLCDT(NS)+VICDT(NS)*RHOI/RHOL
      VICDT(NS)=0.0
      CALL SHP_MATVL2 (NS, MATDT(NS), VLCDT(NS), DUMMY)
      IF (TSDT(NS) .LT. 0.0) VICDT(NS)=(VLC1-VLCDT(NS))*RHOL/RHOI
      IF (VICDT(NS) .LT. 0.0) VICDT(NS)=0.0
      ELSE
      IF (INPH2O.NE.1) THEN
      VLCDT(NS)=VLCDAY
      IF (VLCDT(NS) .LE. SOILWRC(NS, 4)) THEN
      WRITE (6, *) ' *** Input soil water content at lower boundary   ***' ,
     >' *** less than or equal to residual water content.***'
      WRITE (6, *) ' *** Input soil water content at lower boundary   ***' ,
     >' *** less than or equal to residual water content.***'
      WRITE (6, *)
      WRITE (6, *) ' ===> Simulation aborted; Press Enter to end'
      CONTINUE
      STOP 71
      END IF
      CALL SHP_MATVL1 (NS, MATDT(NS), VLCDT(NS), DUMMY)
      ELSE
      MATDT(NS)=VLCDAY
      CALL SHP_MATVL2 (NS, MATDT(NS), VLCDT(NS), DUMMY)
      END IF
      VICDT(NS)=0.0
      END IF
      ICESDT(NS)=0
      DO 105 J=1, NSALT
      CONCDT(J, NS)=SALTDT(J, NS)/(SALTKQ(J, NS)+VLCDT(NS)*RHOL/RHOB(NS))
  105 CONTINUE
      IF (TSDT(NS) .LE. 0.0) CALL SHP_FROZEN (NS, VLCDT, VICDT, MATDT, CONCDT, TSDT, SALTDT, ICESDT)
      IF (MWATRXT.EQ.1) THEN
      AVAILA=VLCDT(1)*(ZS(2)-ZS(1))/2
      IF (SOILXT(1)*DT.GT.AVAILA) SOILXT(1)=0.0
      AVAILA=VLCDT(NS)*(ZS(NS)-ZS(NS-1))/2
      IF (SOILXT(NS)*DT.GT.AVAILA) SOILXT(NS)=0.0
      DO 1105 I=2, NS-1
      AVAILA=VLCDT(I)*(ZS(I+1)-ZS(I-1))/2
      IF (SOILXT(I)*DT.GT.AVAILA) SOILXT(I)=0.0
 1105 CONTINUE
      ELSE
      DO 1106 I=1, NS
      SOILXT(I)=0.0
 1106 CONTINUE
      END IF
      CALL SHP_SYSTM (NC, NPLANT, NSP, HTORDR, ZC, ZSP, ZMSRF, ZHSRF, ZERSRF, ZMSP, ZHSP, HEIGHT, SUNHOR, TMPDAY,
     >TCCRIT)
      CALL SHP_SWRBAL (NPLANT, NC, NSP, NR, XANGLE, CLUMPNG, SWCAN, SWSNOW, SWRES, SWSOIL, SWDOWN, SWUP, SUNHOR, CANALB,
     >ZSP, DZSP, RHOSP, ZR, RHOR, ALBRES, DIRRES, ALBDRY, ALBEXP, VLCDT(1), ALATUD, SLOPE, ASPECT, HRNOON, HAFDAY,
     >DECLIN, HOUR, NHRPDT)
      CALL SHP_UPDATE (NS, NR, NSP, NC, NPLANT, NSALT, IBICES, ICESDT, BTS, TSDT, BMAT, MATDT, BCONC, CONCDT, BVLC,
     >VLCDT, BVIC, VICDT, BSALT, SALTDT, BTR, TRDT, BVAPR, VAPRDT, BGMC, GMCDT, BTC, TCDT, BTLC, TLCDT, BVAPC, VAPCDT,
     >BWCAN, WCANDT, BPCAN, PCANDT, BTSP, TSPDT, BDLW, DLWDT, ICESP, ICESPT)
  110 CALL SHP_UPDATE (NS, NR, NSP, NC, NPLANT, NSALT, ICES, ICESDT, TS, TSDT, MAT, MATDT, CONC, CONCDT, VLC, VLCDT,
     >VIC, VICDT, SALT, SALTDT, TR, TRDT, VAPR, VAPRDT, GMC, GMCDT, TC, TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN, WCANDT,
     >PCAN, PCANDT, TSP, TSPDT, DLW, DLWDT, ICESP, ICESPT)
  120 ITER = 0
      SHP_FORCED_REFINEMENT=0
      ITRSLT = 0
  200 ITER = ITER + 1
      IF (WDT.LE.1.0) THEN
      DO 100 I=NS-1, 1, -1
      IF (MATDT(I).GT.SOILWRC(I, 1).OR. VLCDT(I)-SOILWRC(I, 4).LT.0.001) THEN
      WDT=1.0
      WT=0.0
      GO TO 101
      END IF
  100 CONTINUE
  101 CONTINUE
      END IF
      CALL SHP_LWRBAL (NC, NSP, NR, NPLANT, TA, TADT, TLC, TLCDT, TSP, TSPDT, TR, TRDT, TS, TSDT, VAPA, VAPADT, CLOUDS,
     >LWCAN, LWSNOW, LWRES, LWSOIL, LWDOWN, LWUP)
      CALL SHP_LWRMAT (NC, NSP, NR, TC, TSP, TR, TS, ICESPT)
      CALL SHP_SOURCE (NC, NSP, NR, NS, NSALT, NPLANT, UC, SC, USP, SSP, UR, SR, US, SS, SINK, SWCAN, SWSNOW, SWRES,
     >SWSOIL, LWCAN, LWSNOW, LWRES, LWSOIL, SOILXT)
      N = 1
      MATERL=2
      IF (NC .GT. 0) THEN
      CALL SHP_ATSTAB(NPLANT, NC, NSP, NR, TA, TADT, TCDT(1), TCDT(1), VAPA, VAPADT, VAPCDT(1), VAPCDT(1), WIND, HEIGHT,
     >HFLUX, VFLUX, ZC, ZR, RHOR, 0, ITER)
      GO TO 205
      END IF
      IF (NSP .GT. 0) THEN
      CALL SHP_VSLOPE (DUMMY, SATV, TSP(1))
      CALL SHP_VSLOPE (DUMMY, SATVDT, TSPDT(1))
      TMP = TSP(1) + 273.16
      TMPDT = TSPDT(1) + 273.16
      VAP = SATV*EXP(0.018/(UGAS*TMP)*LF*TSP(1)/TMP)
      VAPDT = SATVDT*EXP(0.018/(UGAS*TMPDT)*LF*TSPDT(1)/TMPDT)
      CALL SHP_ATSTAB(NPLANT, NC, NSP, NR, TA, TADT, TSP(1), TSPDT(1), VAPA, VAPADT, VAP, VAPDT, WIND, HEIGHT, HFLUX,
     >VFLUX, ZC, ZR, RHOR, ICESPT(1), ITER)
      GO TO 205
      END IF
      IF (NR .GT. 0) THEN
      CALL SHP_ATSTAB(NPLANT, NC, NSP, NR, TA, TADT, TR(1), TRDT(1), VAPA, VAPADT, VAPR(1), VAPRDT(1), WIND, HEIGHT,
     >HFLUX, VFLUX, ZC, ZR, RHOR, 0, ITER)
      END IF
  205 TLCONC=0.0
      TLCNDT=0.0
      DO 210 J=1, NSALT
      TLCONC=TLCONC+CONC(J, 1)
      TLCNDT=TLCNDT+CONCDT(J, 1)
  210 CONTINUE
      TOTPOT=MAT(1)-TLCONC*UGAS*(TS(1)+273.16)/G
      TOTPDT=MATDT(1)-TLCNDT*UGAS*(TSDT(1)+273.16)/G
      CALL SHP_VSLOPE (DUMMY, SATV, TS(1))
      CALL SHP_VSLOPE (DUMMY, SATVDT, TSDT(1))
      VAP=SATV*EXP(.018*G/UGAS/(TS(1)+273.16)*TOTPOT)
      VAPDT=SATVDT*EXP(.018*G/UGAS/(TSDT(1)+273.16)*TOTPDT)
      IF (NC.EQ.0 .AND. NR.EQ.0 .AND. NSP.EQ.0) CALL SHP_ATSTAB(NPLANT, NC, NSP, NR, TA, TADT, TS(1), TSDT(1), VAPA,
     >VAPADT, VAP, VAPDT, WIND, HEIGHT, HFLUX, VFLUX, ZC, ZR, RHOR, ICESDT(1), ITER)
      IF (NC .GT. 0) THEN
      IF (NSP .GT. 0) THEN
      CALL SHP_VSLOPE (DUMMY, SATV, TSP(1))
      CALL SHP_VSLOPE (DUMMY, SATVDT, TSPDT(1))
      TMP = TSP(1) + 273.16
      TMPDT = TSPDT(1) + 273.16
      VAPC(NC+1) = SATV*EXP(0.018/(UGAS*TMP)*LF*TSP(1)/TMP)
      VAPCDT(NC+1)=SATVDT*EXP(0.018/(UGAS*TMPDT)*LF*TSPDT(1)/TMPDT)
      TC(NC+1)=TSP(1)
      TCDT(NC+1)=TSPDT(1)
      ELSE
      IF (NR .GT. 0) THEN
      VAPC(NC+1) = VAPR(1)
      VAPCDT(NC+1) = VAPRDT(1)
      TC(NC+1) = TR(1)
      TCDT(NC+1) = TRDT(1)
      ELSE
      VAPC(NC+1) = VAP
      VAPCDT(NC+1) = VAPDT
      TC(NC+1) = TS(1)
      TCDT(NC+1) = TSDT(1)
      END IF
      END IF
      CALL SHP_EBCAN (N, NPLANT, NC, NSP, NR, NS, ZC, TC, TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN, WCANDT, PCAN, PCANDT,
     >MAT, MATDT, SWCAN, LWCAN, SWDOWN, CANMA, CANMB, DCHAR, RSTOM0, RSTEXP, PLEAF0, RLEAF0, ITYPE, ISTOMATE, STOMATE,
     >ITER)
      MATERL = MATERL + 1
      END IF
      IF (NSP .GT. 0) THEN
      IF (NR .GT. 0) THEN
      VAPSP = VAPR(1)
      VAPSPT = VAPRDT(1)
      TSP(NSP+1) = TR(1)
      TSPDT(NSP+1) = TRDT(1)
      ELSE
      VAPSP = VAP
      VAPSPT = VAPDT
      TSP(NSP+1) = TS(1)
      TSPDT(NSP+1) = TSDT(1)
      END IF
      CALL SHP_EBSNOW (N, NSP, NR, ICESPT, TSP, TSPDT, DLW, DLWDT, RHOSP, ZSP, DZSP, QVSP, VAPSP, VAPSPT, SSP, ITER)
      MATERL = MATERL + 1
      END IF
      IF (NR .GT. 0) THEN
      VAPR(NR+1) = VAP
      VAPRDT(NR+1)=VAPDT
      TR(NR+1)=TS(1)
      TRDT(NR+1)=TSDT(1)
      CALL SHP_EBRES (N, NR, NSP, ZR, TR, TRDT, VAPR, VAPRDT, GMC, GMCDT, GMCMAX, RHOR, RESCOF, RESTKB, SR, UR, QVR,
     >RHOSP, ITER)
      MATERL = MATERL + 1
      END IF
      CALL SHP_EBSOIL (N, NS, ZS, TS, TSDT, MAT, MATDT, CONC, CONCDT, VLC, VLCDT, VIC, VICDT, ICES, ICESDT, QSL, QSV,
     >SS, GFLUX, ITER)
      IF (LEVEL(1) .GE. 2) THEN
      WRITE (6, *) 'HFLUX (W/M2), VFLUX (KG/S): ' , HFLUX, VFLUX
      WRITE (6, *) ' VAPOR FLUXES (KG/S)'
      WRITE (6, *) (QSV(K), K=1, NS-1)
      WRITE (6, *) ' LIQUID FLUXES (M/S)'
      WRITE (6, *) (QSL(K), K=1, NS-1)
      WRITE (6, *) ' JACOBIAN MATRIX'
      DO 215 K=1, N
      WRITE (6, *) A1(K), B1(K), C1(K), D1(K)
  215 CONTINUE
      WRITE (6, *)
      WRITE (6, *) ' VALUES FOR ENERGY BALANCE ITERATION ' , ITER
      END IF
      CALL SHP_TDMA (N, A1, B1, C1, D1, DELTA)
      MATERL=2
      N=1
      IEFLAG=0
      IWFLAG=0
      IF (NC .GT. 0) THEN
      DO 220 I=1, NC
      IF (ABS(DELTA(N)) .GT. 25. .AND. NDT .LT. MAXNDT) THEN
      IEFLAG=1
      SHP_FORCED_REFINEMENT=1
      ITER=11
      GO TO 350
      END IF
      IF (ABS(DELTA(N)) .GT. 0.1) IEFLAG = IEFLAG+1
      IF (ITER .GT. 3 .AND. DELNRG(N)*DELTA(N) .LT. 0) THEN
      DELTA(N)=DELTA(N)/2.
      END IF
      DELNRG(N)=DELTA(N)
      TCDT(I)=TCDT(I)-DELTA(N)
      IF (LEVEL(1) .GE. 2) WRITE (6, *) DELTA(N), TCDT(I), VAPCDT(I), WCANDT(I)
      N=N+1
  220 CONTINUE
      MATERL=MATERL+1
      END IF
      IF (NSP .GT. 0) THEN
      DO 230 I=1, NSP
      IF (ABS(DELTA(N)) .GT. 25. .AND. NDT .LT. MAXNDT) THEN
      IEFLAG=1
      SHP_FORCED_REFINEMENT=1
      ITER=11
      GO TO 350
      END IF
      IF (ICESPT(I) .EQ. 0) THEN
      IF (ABS(DELTA(N)) .GT. TOLER) IEFLAG = IEFLAG + 1
      IF (ITER .GT. 3 .AND. DELNRG(N)*DELTA(N) .LT. 0) THEN
      DELTA(N)=DELTA(N)/2.
      END IF
      DELNRG(N)=DELTA(N)
      TSPDT(I) = TSPDT(I) - DELTA(N)
      IF (TSPDT(I) .GT. 0) THEN
      ICESPT(I) = 1
      TSPDT(I) = 0.0
      END IF
      ELSE
      IF (ABS(DELTA(N))/DZSP(I) .GT. 0.001*TOLER) THEN
      IF (ABS(DELTA(N)) .GT. DLWDT(I)*10E-07) IEFLAG=IEFLAG+1
      END IF
      IF (ITER .GT. 3 .AND. DELNRG(N)*DELTA(N) .LT. 0) THEN
      DELTA(N)=DELTA(N)/2.
      END IF
      DELNRG(N)=DELTA(N)
      DLWDT(I) = DLWDT(I) - DELTA(N)
      IF (DLWDT(I) .LT. 0.0) THEN
      ICESPT(I) = 0
      DLWDT(I) = 0.0
      END IF
      END IF
      IF (LEVEL(1) .GE. 2) WRITE (6, *) DELTA(N), TSPDT(I), DLWDT(I), DZSP(I)
      N=N+1
  230 CONTINUE
      MATERL=MATERL+1
      END IF
      IF (NR .GT. 0) THEN
      DO 240 I=1, NR
      IF (ABS(DELTA(N)) .GT. 25. .AND. NDT .LT. MAXNDT) THEN
      IEFLAG=1
      SHP_FORCED_REFINEMENT=1
      ITER=11
      GO TO 350
      END IF
      IF (ABS(DELTA(N)) .GT. TOLER) IEFLAG = IEFLAG+1
      IF (ITER .GT. 3 .AND. DELNRG(N)*DELTA(N) .LT. 0) THEN
      DELTA(N)=DELTA(N)/2.
      END IF
      DELNRG(N)=DELTA(N)
      TRDT(I)=TRDT(I)-DELTA(N)
      IF (LEVEL(1) .GE. 2) WRITE (6, *) DELTA(N), TRDT(I), VAPRDT(I), GMCDT(I)
      N=N+1
  240 CONTINUE
      MATERL=MATERL+1
      END IF
      DO 250 I=1, NS-1
      IF (ABS(DELTA(N)) .GT. 25. .AND. NDT .LT. MAXNDT) THEN
      IEFLAG=1
      SHP_FORCED_REFINEMENT=1
      ITER=11
      GO TO 350
      END IF
      IF (ABS(DELTA(N)) .GT. TOLER) IEFLAG = IEFLAG+1
      IF (ITER .GT. 3 .AND. DELNRG(N)*DELTA(N) .LT. 0) THEN
      DELTA(N)=DELTA(N)/2.
      END IF
      DELNRG(N)=DELTA(N)
      TSDT(I)=TSDT(I)-DELTA(N)
      IF (TSDT(I) .LE. 0.0) THEN
      ICE=ICESDT(I)
      CALL SHP_FROZEN (I, VLCDT, VICDT, MATDT, CONCDT, TSDT, SALTDT, ICESDT)
      IF (ICE .EQ. 0 .AND. ICESDT(I) .EQ. 1) CALL SHP_ADJUST (I, VICDT, VLCDT, MATDT, CONCDT, TSDT, SALTDT, ICESDT)
      ELSE
      IF (ICESDT(I) .EQ. 1) THEN
      VLCDT(I) = VLCDT(I) + VICDT(I)*RHOI/RHOL
      IF (VLCDT(I) .GT. SoilWRC(I, 2)) VLCDT(I)=SoilWRC(I, 2)
      VICDT(I) = 0.0
      ICESDT(I) = 0
      IF (VLCDT(I) .GT. SOILWRC(I, 4)) CALL SHP_MATVL1 (I, MATDT(I), VLCDT(I), DUMMY)
      END IF
      END IF
      IF (LEVEL(1) .GE. 2) WRITE (6, *) DELTA(N), TSDT(I), VLCDT(I), VICDT(I), MATDT(I), CONCDT(1, I), ICESDT(I)
      N=N+1
  250 CONTINUE
      IF (NC .GT. 0) THEN
      IF (NSP .GT. 0) THEN
      TCDT(NC+1) = TSPDT(1)
      ELSE
      IF (NR .GT. 0) THEN
      TCDT(NC+1) = TRDT(1)
      ELSE
      TCDT(NC+1) = TSDT(1)
      END IF
      END IF
      END IF
      IF (NSP .GT. 0) THEN
      IF (NR .GT. 0) THEN
      TSPDT(NSP+1) = TRDT(1)
      ELSE
      TSPDT(NSP+1) = TSDT(1)
      END IF
      END IF
      IF (NR .GT. 0) TRDT(NR+1) = TSDT(1)
      IF (ITMPBC .EQ. 2) THEN
      TSDT(NS)=TSDT(NS-1)
      END IF
      IF (LEVEL(1) .GE. 1) THEN
      WRITE (6, *) ' ENERGY BALANCE AT ITER = ' , ITER, JULIAN, HOUR, NTIMES, NDT
      CONTINUE
      END IF
      N = 1
      IF (NC .GT. 0) THEN
      CALL SHP_WBCAN(N, NPLANT, NC, NSP, NR, NS, ZC, TC, TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN, WCANDT, PCAN, PCANDT,
     >QVC, TRNSP, MAT, MATDT, XTRACT, SWCAN, LWCAN, SWDOWN, CANMA, CANMB, DCHAR, RSTOM0, RSTEXP, PLEAF0, RLEAF0, ITYPE,
     >ISTOMATE, STOMATE, ICESDT(1), ITER)
      ELSE
      DO 300 I=1, NS
      XTRACT(I)=0.0
  300 CONTINUE
      DO 302 I=1, NPLANT+1
      TRNSP(I)=0.0
  302 CONTINUE
      END IF
      IF (NSP .GT. 0.0) THEN
      A2(N) = 0.0
      CALL SHP_SNOWBC (N, NSP, NR, ZSP, QVSP, VAPSPT, TSDT, TSPDT, ICESDT(1))
      END IF
      IF (NR .GT. 0) CALL SHP_WBRES (N, NR, NSP, ZR, TR, TRDT, VAPR, VAPRDT, GMC, GMCDT, RHOR, RESTKB, QVR, RHOSP,
     >ICESDT(1), ITER)
      CALL SHP_WBSOIL (N, NS, ZS, TS, TSDT, MAT, MATDT, VLC, VLCDT, VIC, VICDT, CONC, CONCDT, ICESDT, QSL, QSV, XTRACT,
     >SEEP, FLOLAT, US, SLOPE, ITER)
      IF (LEVEL(1) .GE. 2) THEN
      WRITE (6, *) 'HFLUX (W/M2), VFLUX (KG/S): ' , HFLUX, VFLUX
      WRITE (6, *) ' VAPOR FLUXES (KG/S)'
      WRITE (6, *) (QSV(K), K=1, NS-1)
      WRITE (6, *) ' LIQUID FLUXES (M/S)'
      WRITE (6, *) (QSL(K), K=1, NS-1)
      WRITE (6, *) ' JACOBIAN MATRIX'
      DO 305 I=1, N
      WRITE (6, *) A2(I), B2(I), C2(I), D2(I)
  305 CONTINUE
      WRITE (6, *)
      WRITE (6, *) ' VALUES AT WATER BALANCE ITERATION ' , ITER
      END IF
      CALL SHP_TDMA (N, A2, B2, C2, D2, DELTA)
      MATERL=2
      N=1
      IWFLAG=0
      IF (NC .GT. 0) THEN
      DO 310 I=1, NC
      IF (ABS(DELTA(N)/VAPCDT(I)) .GT. SHP_CANOPY_WATER_TOL) IWFLAG = IWFLAG+1
      IF (ITER .GT. 3 .AND. DELWTR(N)*DELTA(N) .LT. 0) THEN
      DELTA(N)=DELTA(N)/2.
      END IF
      DELWTR(N)=DELTA(N)
      VAPCDT(I)=VAPCDT(I)-DELTA(N)
      IF (LEVEL(1) .GE. 2) WRITE (6, *) DELTA(N), VAPCDT(I), TCDT(I), WCANDT(I)
      N=N+1
  310 CONTINUE
      MATERL=MATERL+1
      END IF
      IF (NSP .GT. 0) THEN
      MATERL=MATERL+1
      END IF
      IF (NR .GT. 0) THEN
      DO 320 I=1, NR
      IF (ABS(DELTA(N)/VAPRDT(I)) .GT. TOLER) IWFLAG = IWFLAG+1
      IF (ITER .GT. 3 .AND. DELWTR(N)*DELTA(N) .LT. 0) THEN
      DELTA(N)=DELTA(N)/2.
      END IF
      DELWTR(N)=DELTA(N)
      VAPRDT(I)=VAPRDT(I)-DELTA(N)
      IF (LEVEL(1) .GE. 2) WRITE (6, *) DELTA(N), VAPRDT(I), TRDT(I), GMCDT(I)
      N=N+1
  320 CONTINUE
      MATERL=MATERL+1
      END IF
      DO 330 I=1, NS-1
      IF (ICESDT(I) .EQ. 1) THEN
      IF (ABS(DELTA(N)) .GT. 1.0 .AND. NDT .LT. MAXNDT) THEN
      IWFLAG=1
      SHP_FORCED_REFINEMENT=1
      ITER=11
      GO TO 350
      END IF
      IF (ABS(DELTA(N)) .GT. TOLER) IWFLAG = IWFLAG+1
      IF (ITER .GT. 3 .AND. DELWTR(N)*DELTA(N) .LT. 0) THEN
      DELTA(N)=DELTA(N)/2.
      END IF
      DELWTR(N)=DELTA(N)
      if (abs(delta(n)) .gt. 0.20) then
      if (i .eq. 1) then
      dz = (ZS(2)-ZS(1))/2.
      else
      dz = (ZS(I+1)-ZS(I-1))/2.
      end if
      if (abs(RHOI*LF*delta(n)*dz/dt) .gt. 2000.) then
      delta(n) = delta(n)/abs(delta(n))*2000.*dt/(RHOI*LF*dz)
      end if
      end if
      VICDT(I)=VICDT(I)-DELTA(N)
      IF (VICDT(I) .LT. 0.0) THEN
      IF ((VLCDT(I)+VICDT(I)*RHOI/RHOL) .GT. (VLCDT(I)+SOILWRC(I, 4))/2.) THEN
      VLCDT(I) = VLCDT(I) + VICDT(I)*RHOI/RHOL
      ELSE
      VLCDT(I) = (VLCDT(I)+SOILWRC(I, 4))/2.
      END IF
      IF (VLCDT(I) .GT. SOILWRC(I, 4)) CALL SHP_MATVL1 (I, MATDT(I), VLCDT(I), DUMMY)
      VICDT(I)=0.0
      ICESDT(I)=0
      END IF
      ELSE
      CHKMAT=MATDT(I)
      IF (ABS(CHKMAT).LT.1.0) CHKMAT=1.0
      IF (ABS(DELTA(N)/CHKMAT).GT.100. .AND. NDT.LT.MAXNDT) THEN
      IWFLAG=1
      SHP_FORCED_REFINEMENT=1
      ITER=11
      GO TO 350
      END IF
      IF (ABS(DELTA(N)/CHKMAT) .GT. TOLER) IWFLAG = IWFLAG+1
      IF (ITER .GT. 3 .AND. DELWTR(N)*DELTA(N) .LT. 0) THEN
      DELTA(N)=DELTA(N)/2.
      END IF
      DELWTR(N)=DELTA(N)
      MATDT(I)=MATDT(I)-DELTA(N)
      END IF
      CALL SHP_MATVL2 (I, MATDT(I), VLCDT(I), DLDM)
      IF (LEVEL(1) .GE. 2) WRITE (6, *) DELTA(N), MATDT(I), VLCDT(I), VICDT(I)
      N=N+1
  330 CONTINUE
      IF (MATDT(1).GT.0.0) THEN
      DO 335 I=2, NS
      IF (MATDT(I).GT.0.0) THEN
      MATDT(I) = MATDT(I) - MATDT(1)
      CALL SHP_MATVL2 (I, MATDT(I), VLCDT(I), DUMMY)
      ELSE
      GO TO 340
      END IF
  335 CONTINUE
  340 MATDT(1)=0.0
      CALL SHP_MATVL2 (1, MATDT(1), VLCDT(1), DUMMY)
      END IF
      IF (LEVEL(1) .GE. 1) THEN
      WRITE (6, *) ' WATER BALANCE AT ITERWB = ' , ITER, JULIAN, HOUR, NTIMES, NDT
      CONTINUE
      WRITE (6, *) ' ITERATION =' , ITER, 'ENERGY FLAGS =' , IEFLAG, 'WATER FLAGS =' , IWFLAG
      END IF
  350 IF (IWFLAG .GT. 0 .OR. IEFLAG .GT. 0) THEN
      IF (ITER .LE. 10) GO TO 200
      IF (SHP_CANOPY_JACOBIAN .NE. 0 .AND. SHP_FORCED_REFINEMENT .EQ. 0 .AND. ITER .LT. 40) GO TO 200
      IF (NDT .LT. MAXNDT) THEN
      NDT=NDT*2
      NTIMES=NTIMES*2 - 1
      DT=DTIME/NDT
      CALL SHP_BACKUP (NS, NR, NSP, NC, NPLANT, NSALT, ICES, ICESDT, TS, TSDT, MAT, MATDT, CONC, CONCDT, VLC, VLCDT,
     >VIC, VICDT, SALT, SALTDT, TR, TRDT, VAPR, VAPRDT, GMC, GMCDT, TC, TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN, WCANDT,
     >PCAN, PCANDT, TSP, TSPDT, DLW, DLWDT, ICESP, ICESPT)
      GO TO 120
      END IF
      IF (LVLOUT(20).NE.0) WRITE (6, 535) (BCKSPACE, J=1, 56), JULIAN, HOUR, YEAR, NTIMES, NDT
      WRITE (6, *) ' CONVERGENCE PROBLEMS AT : ' , JULIAN, HOUR, YEAR, NTIMES
      IF (IEFLAG.GT.0) WRITE (6, *) ' ENERGY BALANCE WILL NOT CONVERGE'
      IF (IWFLAG.GT.0) WRITE (6, *) ' WATER BALANCE WILL NOT CONVERGE'
      SHP_RESULT_VALUES = 0.0
      SHP_RESULT_VALUES(320) = -1.0
      RETURN
      ITER = 0
      SHP_FORCED_REFINEMENT=0
      IF (LEVEL(1) .EQ. 1 .OR. LEVEL(1) .EQ. 2) THEN
      WRITE (6, *) ' ***  Debugging limit reached ***'
      WRITE (6, *) ' ===> Press Enter to end'
      CONTINUE
      STOP 71
      END IF
      END IF
  400 CONTINUE
      IF (MINSTP.EQ.0) THEN
      MAXSTP=NDT
      MINSTP=NDT
      END IF
      IF (MAXSTP .LT. NDT) MAXSTP=NDT
      IF (MINSTP .GT. NDT) MINSTP=NDT
      CALL SHP_SUMDT (NC, NPLANT, NSP, NR, NS, HFLUX, VFLUX, GFLUX, LWCAN, LWSNOW, LWRES, LWSOIL, LWDOWN, LWUP, SWCAN,
     >SWSNOW, SWRES, SWSOIL, SWDOWN, SWUP, QVC, QVR, QVSP, QSL, QSV, TRNSP, XTRACT, US, FLOLAT, SEEP, TSWSNO, TLWSNO,
     >TSWCAN, TLWCAN, TSWRES, TLWRES, TSWSOI, TLWSOI, TSWDWN, TLWDWN, TSWUP, TLWUP, THFLUX, TGFLUX, EVAP1, ETSUM, TSEEP,
     >ROOTXT, TOTFLO, TOTSINK, TOTLAT, NTIMES, TOPSNO, TQVSP)
      IF (NTIMES .NE. NDT) THEN
      IF (MOD(NTIMES, 2).EQ.0 .AND. (IEFLAG+IWFLAG).EQ.0) THEN
      IF (NDT .LE. MAXDBL) THEN
      IF (NDT .LT. MAXDBL) MAXTRY=0
      IF (NDT .LE. 8) MAXTRY=MAXTRY+2
      MAXTRY=MAXTRY+1
      MAXDBL=NDT
      END IF
      IF (NDT.GT.MAXDBL .OR. MAXTRY.LE.3 .OR. NDT.GE.MAXNDT) THEN
      NDT=NDT/2
      NTIMES=NTIMES/2
      DT=DTIME/NDT
      END IF
      END IF
      NTIMES=NTIMES + 1
      GO TO 110
      ELSE
      DT = DTIME
      RAIN=PRECIP
      TADT=TMPDAY
      HUMDT=HUMDAY
      TA=TMPDAY
      HUM=HUMDAY
      NSPLST=NSP
      if (nsp .gt. 0) then
      tsurface = tspdt(1)
      elseif (nr .gt. 0) then
      tsurface = trdt(1)
      else
      tsurface = tsdt(1)
      end if
      CALL SHP_PRECP(NPLANT, NC, NSP, NR, NS, TA, TADT, HUM, HUMDT, ZC, PINTRCP, XANGLE, CLUMPNG, ITYPE, WCANDT, WCMAX,
     >PCANDT, ZSP, DZSP, TSPDT, BDLW, DLWDT, RHOSP, TQVSP, TOPSNO, WLAG, STORE, SNOWEX, ZR, TRDT, GMCDT, GMCMAX, RHOR,
     >ZS, TSDT, VLCDT, VICDT, MATDT, TOTFLO, TOTLAT, SALTDT, CONCDT, ICESPT, ICESDT, RAIN, POND, RUNOFF, EVAP1, MELT,
     >PONDMX, ISNOTMP, SNOTMP, SNODEN, DIRRES, SLOPE)
      RUNOFF=RUNOFF+TSEEP
      nclst =nc
      if (nclst .eq. 0) then
      windsub = winday
      tempsub = tmpday
      else
      windsub = windc(nclst)
      tempsub = tcdt(nclst)
      end if
      IF (NSP.GT.0 .OR. NSPLST.GT.0) THEN
      SHP_CANOPY_BEFORE=SHP_CANOPY_AIR_WATER(NC, ZC, VAPCDT)
      IF (NPLANT.NE.0) CALL SHP_CANOPY (NPLANT, NC, NCMAX, NSP, NSPLST, MZCINP, ITYPE, HTORDR, 1, PLTHGT, PLTWGT,
     >PLTLAI, RLEAF0, ZSP, ZC, TC, TCDT, TLC, TLCDT, BVAPC, VAPCDT, BWCAN, WCANDT, WCMAX, PCANDT, CANMA, CANMB, TMPDAY,
     >HUMDAY)
      SHP_CANOPY_EXCHANGE=SHP_CANOPY_EXCHANGE+(SHP_CANOPY_AIR_WATER(NC, ZC, VAPCDT)-SHP_CANOPY_BEFORE)
      END IF
      CONTINUE
      CONTINUE
      CONTINUE
      CONTINUE
      CONTINUE
      IF (LVLOUT(20) .NE. 0) THEN
      NPRINT=NPRINT+1
      IF (MOD(NPRINT, LVLOUT(20)).EQ.0) THEN
      WRITE (6, 530) (BCKSPACE, J=1, 56), JULIAN, HOUR, YEAR, MINSTP, MAXSTP
      NPRINT=0
      MAXSTP=0
      MINSTP=0
      END IF
      END IF
      SHP_RESULT_VALUES = 0.0
      SHP_RESULT_VALUES(1) = RUNOFF
      SHP_RESULT_VALUES(2) = EVAP1
      SHP_RESULT_VALUES(3) = ETSUM
      SHP_RESULT_VALUES(4) = MELT
      SHP_RESULT_VALUES(5) = RAIN
      SHP_RESULT_VALUES(6) = TSEEP
      SHP_RESULT_VALUES(7) = THFLUX
      SHP_RESULT_VALUES(8) = TGFLUX
      SHP_RESULT_VALUES(9) = TSWDWN-TSWUP+TLWDWN-TLWUP
      SHP_RESULT_VALUES(10) = REAL(MAXSTP)
      SHP_RESULT_VALUES(21:20+NS) = TOTFLO(1:NS)
      SHP_RESULT_VALUES(120:119+NS) = TOTLAT(1:NS)
      SHP_RESULT_VALUES(219:218+NS) = ROOTXT(1:NS)
      SHP_RESULT_VALUES(318) = SHP_CANOPY_EXCHANGE
      RETURN
      END IF
  522 FORMAT (I5, F5.2, F8.3, F6.3, F6.3, F8.2, E14.5, F8.3, F8.3, E14.5)
  530 FORMAT(56A1, '  Completed :      ' , I4, 3X, I4, 3X, I4, 5X, I4, 6X, I4, $)
  535 FORMAT(56A1, '  Converg. Prob. : ' , I4, 3X, I4, 3X, I4, 5X, I4, 6X, I4, $)
      END
C     USDA-ARS SHAW 3.0.3: CONSTANTS
      BLOCK DATA
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SWRCOE/ SOLCON, DIFATM, DIFRES, SNOCOF, SNOEXP
      COMMON /SHP_LWRCOF/ STEFAN, EMATM1, EMATM2, EMITC, EMITR, EMITSP, EMITS
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      COMMON /SHP_RSPARM/ RESMA, RESMB, RESMC, RESTKA
      COMMON /SHP_SPPROP/ G1, G2, G3, EXTSP, TKSPA, TKSPB, TKSPEX, VDIFSP, VAPSPX
      COMMON /SHP_SPWATR/ CLAG1, CLAG2, CLAG3, CLAG4, PLWMAX, PLWDEN, PLWHC, THICK, CTHICK
      COMMON /SHP_METASP/ CMET1, CMET2, CMET3, CMET4, CMET5, SNOMAX
      REAL LF, LS, LV
      DATA LF/335000./ LV/2500000./ LS/2835000./ G/9.81/ UGAS/8.3143/ VONKRM/0.4/ VDIFF/.0000212/ P0/101300./
      DATA RHOM/2650./ RHOL/1000./ RHOI/920./ RHOA/1.25/ RHOOM/1300./
      DATA TKL/0.57/ TKI/2.2/ TKA/0.025/ TKR/ 0.05/ TKRO/8.8/ TKSA/8.8/ TKSI/2.92/ TKCL/2.92/ TKOM/0.25/
      DATA CM/900./ COM/1920./ CL/4200./ CI/2100./ CA/1006./ CV/1860./ CR/1900./
      DATA SOLCON/1360./ STEFAN/5.6697E-08/
      DATA EMATM1/0.261/ EMATM2/0.000777/ EMITC/0.95/ EMITR/0.95/ EMITSP/0.9/ EMITS/0.95/
      DATA DIFATM/0.76/ DIFRES/0.667/ SNOCOF/0.0/ SNOEXP/1.0/
      DATA VAPCOF/99*0.66/ VAPEXP/99*1.0/
      DATA RESMA/-53.72/ RESMB/1.32/ RESMC/0.0/ RESTKA/0.007/
      DATA G1/0.16/ G2/0.0/ G3/110.0/ EXTSP/1.77/ TKSPA/0.021/ TKSPB/2.51/ TKSPEX/2.0/ VDIFSP/0.00009/ VAPSPX/14./
      DATA CLAG1/10.0/ CLAG2/1.0/ CLAG3/5.0/ CLAG4/450./ PLWMAX/0.1/ PLWDEN/200./ PLWHC/0.03/ THICK/0.025/ CTHICK/0.10/
     >CMET1/0.01/
      DATA CMET2/21./ CMET3/0.01/ CMET4/0.04/ CMET5/2.0/ SNOMAX/150./
      END
C     USDA-ARS SHAW 3.0.3: CLOUDY
      SUBROUTINE SHP_CLOUDY (CLOUDS, ALATUD, DECLIN, HAFDAY, SUNHOR, JULIAN, NHRPDT)
      COMMON /SHP_SWRCOE/ SOLCON, DIFATM, DIFRES, SNOCOF, SNOEXP
      REAL SUNHOR(24)
      TOTSUN=0.0
      DO 10, I=NHRPDT, 24
      IF (SUNHOR(I) .LT. 0.0) SUNHOR(I)=0.0
      TOTSUN=TOTSUN + SUNHOR(I)
   10 CONTINUE
      DECLIN=0.4102*SIN(2*3.14159*(JULIAN-80)/365.)
      COSHAF=-TAN(ALATUD)*TAN(DECLIN)
      IF (ABS(COSHAF) .GE. 1.0) THEN
      IF (COSHAF .GE. 1.0) THEN
      HAFDAY=0.0
      ELSE
      HAFDAY=3.14159
      END IF
      ELSE
      HAFDAY=ACOS(COSHAF)
      END IF
      SUNMAX=24.*SOLCON*(HAFDAY*SIN(ALATUD)*SIN(DECLIN) +COS(ALATUD)*COS(DECLIN)*SIN(HAFDAY))/3.14159
      IF (SUNMAX .GT. 0.0) THEN
      TTOTAL=TOTSUN/SUNMAX
      CLOUDS=1.333 - 1.666*TTOTAL
      IF (CLOUDS .GT. 1.0) CLOUDS=1.0
      IF (CLOUDS .LT. 0.0) CLOUDS=0.0
      ELSE
      CLOUDS = 0.5
      END IF
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: CANOPY
      SUBROUTINE SHP_CANOPY (NPLANT, NC, NCMAX, NSP, NSPLST, MZCINP, ITYPE, HTORDR, INITAL, PLTHGT, PLTWGT, PLTLAI,
     >RLEAF0, ZSP, ZC, TC, TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN, WCANDT, WCMAX, PCANDT, CANMA, CANMB, TA, HUMID)
      COMMON /SHP_CLAYRS/ PLANTZ(8), DRYCAN(8, 10), CANLAI(8, 10), TOTLAI(8), IEVAP(8), RLEAF(8, 10), RROOT(8, 99),
     >ROOTDN(8, 99), TOTROT(8)
      COMMON /SHP_WRITEIT/ hflux1, rh, hnc, xlenc, contk, tleaf(8, 10)
      REAL PLTHGT(8), PLTWGT(8), PLTLAI(8), ZSP(200), RLEAF0(8), ZC(11), TC(11), TCDT(11), TLC(8, 10), TLCDT(8, 10),
     >VAPC(11), VAPCDT(11), WCAN(10), WCANDT(10), PCANDT(8)
      REAL ZZC(11), DZCAN(10), DDRYCAN(8, 10), CCANLAI(8, 10), PLANTW(8), TMP(8)
      INTEGER ITYPE(8)
      INTEGER HTINDX, HTORDR(8)
      COMMON /SHP_SV_CANOPY/ ZZC, DZCAN, DDRYCAN, CCANLAI
      IF (INITAL .EQ. 0) THEN
      IF (MZCINP.LE.0) NC=1
      NCLAST = 1
      CALL SHP_VSLOPE (DUMMY, SATV, TA)
      TCDT(1)=TA
      VAPCDT(1)=HUMID*SATV
      DO J=1, NPLANT
      TLCDT(J, 1)=TCDT(1)
      PCANDT(J)=0.0
      END DO
      IF (WCANDT(1) .LE. 0.0) THEN
      CALL SHP_CANHUM (2, HUMID, DUMMY, WCANDT(1), TCDT(1), CANMA, CANMB)
      END IF
      IF (ABS(MZCINP) .GT. 0) THEN
      MZC = ABS(MZCINP)
      DO I=1, MZC
      ZZC(I)=ZC(I)
      IF (I.EQ.1) THEN
      DZCAN(I)=ZC(2)-ZC(1)
      IF (NC.GT.1) DZCAN(I)=DZCAN(I)/2.
      ELSEIF (I.EQ.NC) THEN
      DZCAN(I)= ZC(I+1)-ZC(I)+(ZC(I)-ZC(I-1))/2.
      ELSE
      DZCAN(I)=(ZC(I+1)-ZC(I-1))/2.
      END IF
      IF (MZCINP .GT. 0) THEN
      DO J=1, NPLANT
      CCANLAI(J, I)=CANLAI(J, I)
      DDRYCAN(J, I)=DRYCAN(J, I)
      END DO
      END IF
      END DO
      ZZC(MZC+1)=ZC(MZC+1)
      END IF
      ELSE
      NCLAST = NC
      END IF
      SNODEPTH=0.0
      IF (NSP .GT. 0) SNODEPTH = ZSP(NSP+1)
      NCCHK=0
      PLTHMAX = 0.0
      DO J=1, NPLANT
      TOTLAI(J) = PLTLAI(J)
      IF (PLTLAI(J).GT.0.) THEN
      IF (PLTHGT(J) .GT. PLTHMAX) THEN
      PLTHMAX = PLTHGT(J)
      IF (NSP .GT. 0) THEN
      IF(PLTHGT(J).GT.SNODEPTH) NCCHK=1
      ELSE
      NCCHK=1
      END IF
      END IF
      END IF
      END DO
      IF (NCCHK.EQ.0) THEN
      NC=0
      NCMAX = NC
      IF (ABS(MZCINP) .GT. 0) NCMAX = ABS(MZCINP)
      GO TO 80
      END IF
      IF (NCLAST .EQ. 0) THEN
      NC=1
      TC(1)=TA
      TCDT(1)=TA
      DO J=1, NPLANT
      TLCDT(J, 1)=TCDT(1)
      END DO
      CALL SHP_VSLOPE (DUMMY, SATV, TA)
      VAPC(1)=HUMID*SATV
      VAPCDT(1)=HUMID*SATV
      IF (NSPLST.GT.0) THEN
      WCAN(1)=WCMAX
      WCANDT(1)=WCMAX
      ELSE
      CALL SHP_CANHUM (2, HUMID, DUMMY, WCANDT(1), TCDT(1), CANMA, CANMB)
      WCAN(1)=WCANDT(1)
      END IF
      END IF
      DO J=1, NPLANT
      TMP(J) = PLTHGT(J)
      IF (PLTHGT(J)*PLTLAI(J) .LE. 0.0) TMP(J)=0.0
      END DO
      DO HTINDX = 1, NPLANT
      HTORDR(HTINDX) = 1
      DO J = 1, NPLANT
      IF (TMP(HTORDR(HTINDX)).GT.TMP(J)) HTORDR(HTINDX) = J
      END DO
      TMP(HTORDR(HTINDX)) = 9999.0
      END DO
      IF (MZCINP .LE. 0) THEN
      DO 10 J=1, NPLANT
      IF (NSP .GT. 0) THEN
      PLANTZ(J)=PLTHGT(J)-SNODEPTH
      IF (PLANTZ(J).LE.0.0) THEN
      PLANTZ(J)=0.0
      PLANTW(J)=0.0
      TOTLAI(J)=0.0
      ELSE
      PLANTW(J)=PLTWGT(J)*PLANTZ(J)/PLTHGT(J)
      TOTLAI(J)=PLTLAI(J)*PLANTZ(J)/PLTHGT(J)
      END IF
      ELSE
      PLANTZ(J)=PLTHGT(J)
      PLANTW(J)=PLTWGT(J)
      TOTLAI(J)=PLTLAI(J)
      END IF
   10 CONTINUE
      IF (MZCINP .EQ. 0) THEN
      CALL SHP_CANLAY (NC, NCMAX, NPLANT, ITYPE, HTORDR, ZC, WCANDT, TCDT, TLCDT, VAPCDT, PLANTZ, PLTHGT, PLANTW,
     >TOTLAI, PLTLAI, RLEAF0, DRYCAN, CANLAI, RLEAF)
      ELSE
      CALL SHP_CANLAYZC (NC, NCMAX, NPLANT, MZCINP, INITAL, ITYPE, ZC, ZZC, WCANDT, TCDT, TLCDT, VAPCDT, PLANTZ, PLANTW,
     >TOTLAI, RLEAF0, DRYCAN, CANLAI, RLEAF, PLTHMAX, SNODEPTH)
      END IF
      ELSE
      NCMAX = MZCINP
      IF (NSP .GT. 0) THEN
      DO 30 I=MZCINP, 1, -1
      IF ((ZZC(MZCINP+1)-ZZC(I)) .GT. SNODEPTH) THEN
      IF ((ZZC(MZCINP+1)-ZZC(I+1)) .LE. SNODEPTH) THEN
      NC=I
      ZC(NC+1) = ZZC(MZCINP+1)-SNODEPTH
      IF (NC .EQ. 1) THEN
      ZC(NC)=0.0
      DZ = ZC(NC+1)
      ELSE
      ZMID1=(ZZC(NC)+ZZC(NC-1))/2.
      ZMID2=(ZZC(NC+1)+ZZC(NC))/2.
      IF (ZC(NC+1) .GT. ZMID2) THEN
      ZC(NC)=ZZC(NC)
      ELSE
      ZC(NC)=ZZC(NC) - (ZZC(NC)-ZMID1)*(ZMID2-ZC(NC+1)) /(ZMID2-ZZC(NC))
      END IF
      DZ =ZC(NC+1)-ZZC(NC)+(ZZC(NC)-ZZC(NC-1))/2.
      END IF
      FACTOR = DZ/DZCAN(NC)
      IF (FACTOR. GT. 1.0) FACTOR = 1.0
      ELSE
      FACTOR = 1.0
      ZC(I)=ZZC(I)
      END IF
      DO J=1, NPLANT
      CANLAI(J, NC)=CCANLAI(J, NC)*FACTOR
      DRYCAN(J, NC)=DDRYCAN(J, NC)*FACTOR
      END DO
      END IF
   30 CONTINUE
      DO J=1, NPLANT
      PLANTZ(J)=PLTHGT(J)-SNODEPTH
      IF (PLANTZ(J).LT.0.0) PLANTZ(J)=0.0
      TOTLAI(J)=0.0
      PLANTW(J)=0.0
      DO I=1, NC
      TOTLAI(J)=TOTLAI(J)+CANLAI(J, I)
      PLANTW(J)=PLANTW(J)+DRYCAN(J, I)
      END DO
      END DO
      ELSE
      NC=MZCINP
      DO J=1, NPLANT
      PLANTZ(J)=PLTHGT(J)
      PLANTW(J)=PLTWGT(J)
      TOTLAI(J)=PLTLAI(J)
      DO I=1, NC
      CANLAI(J, NC)=CCANLAI(J, NC)
      DRYCAN(J, NC)=DDRYCAN(J, NC)
      END DO
      END DO
      DO I=1, NC+1
      ZC(I)=ZZC(I)
      END DO
      END IF
      IF (NC .GT. NCLAST) THEN
      NC1=NCLAST
      IF (NCLAST .EQ. 0) NC1=1
      DO I=NC1+1, NC
      TCDT(I)=TCDT(I-1)
      VAPCDT(I)=VAPCDT(I-1)
      DO J=1, NPLANT
      TLCDT(J, I)=TLCDT(J, I-1)
      END DO
      END DO
      END IF
      END IF
      IF (NC .GT. NCLAST) THEN
      NC1=NCLAST
      IF (NCLAST .EQ. 0) NC1=1
      DO 60 I=NC1+1, NC
      IF (NSPLST .GT. 0) THEN
      WCANDT(I)=WCMAX
      ELSE
      WCANDT(I)=WCANDT(I-1)
      END IF
      WCAN(I)=WCANDT(I)
      TC(I)=TCDT(I)
      VAPC(I)=VAPCDT(I)
      DO J=1, NPLANT
      TLC(J, I)=TLCDT(J, I)
      END DO
   60 CONTINUE
      END IF
   80 DO J=1, NPLANT
      IF (PLTLAI(J).LE. 0.0 .OR. TOTLAI(J) .LE. 0.0) PCANDT(J)=0.0
      END DO
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: CANLAY
      SUBROUTINE SHP_CANLAY (NC, NCMAX, NPLANT, ITYPE, HTORDR, ZC, WCANDT, TCDT, TLCDT, VAPCDT, PLANTZ, PLANTW, PLTHGT,
     >TOTLAI, PLTLAI, RLEAF0, DRYCAN, CANLAI, RLEAF)
      REAL ZC(11), WCANDT(10), TCDT(11), TLCDT(8, 10), VAPCDT(11), PLANTZ(8), PLTHGT(8), PLANTW(8), TOTLAI(8),
     >PLTLAI(8), RLEAF0(8)
      REAL DRYCAN(8, 10), CANLAI(8, 10), RLEAF(8, 10)
      REAL LAISUM, LAILYR, LYRTOP, LYRTOT, DZMAX, A, DZ(10), FACTOR, TMPLAI
      INTEGER NC, HTINDX, HTORDR(8), J, LAYER, OLDNC, ITYPE(8)
      LAILYR = 0.0
      LYRTOT = 0.0
      LAISUM = 0.0
      TMPLAI = 0.0
      TMXLAI = 0.0
      NZEROS = 0
      LYRTOP = 0.0
      OLDNC = NC
      DO 10 J=1, NPLANT
      IF (PLTHGT(J)*PLTLAI(J) .NE. 0.0) THEN
      TMPLAI = TMPLAI + TOTLAI(J)
      TMXLAI = TMXLAI + PLTLAI(J)
      LAISUM = LAISUM + TOTLAI(J) / PLANTZ(J)
      ELSE
      NZEROS=NZEROS+1
      TOTLAI(J) = 0.0
      END IF
   10 CONTINUE
      NC = NINT (TMPLAI / 0.50)
      IF (NC.EQ.0) THEN
      NC=1
      ELSE
      IF (NC.GT.10) NC = 10
      END IF
      NCMAX = NINT (TMXLAI / 0.50)
      IF (NCMAX.EQ.0) THEN
      NCMAX=1
      ELSE
      IF (NCMAX.GT.10) NCMAX = 10
      END IF
      HTINDX = NZEROS+1
      A = TMPLAI / NC
      LAYER = NC
      ZC(NC+1) = PLANTZ(HTORDR(NPLANT))
  100 IF (LAYER .NE. 1) THEN
      DZMAX = (A - LAILYR) / LAISUM
      ELSE
      DZMAX = PLANTZ(HTORDR(NPLANT)) - LYRTOP
      END IF
      IF(LYRTOP+DZMAX.LE.PLANTZ(HTORDR(HTINDX)).OR.LAYER.EQ.1)THEN
      LYRTOP = LYRTOP + DZMAX
      DZ(LAYER) = LYRTOT + DZMAX
      DO 110 J = 1, NPLANT
      IF (PLANTZ(J).GE.LYRTOP) THEN
      FACTOR = DZ(LAYER) / PLANTZ(J)
      ELSE IF (PLANTZ(J).GT.LYRTOP-DZ(LAYER)) THEN
      FACTOR = (PLANTZ(J)-(LYRTOP-DZ(LAYER))) / PLANTZ(J)
      ELSE
      FACTOR = 0.0
      END IF
      CANLAI(J, LAYER) = TOTLAI(J) * FACTOR
      DRYCAN(J, LAYER) = PLANTW(J) * FACTOR
      IF (ITYPE(J).NE.0) THEN
      IF (FACTOR*TOTLAI(J).NE.0) THEN
      RLEAF(J, LAYER) = RLEAF0(J)*(CANLAI(J, LAYER)/TOTLAI(J))
      ELSE
      RLEAF(J, LAYER) = 0.0
      END IF
      ELSE
      RLEAF (J, LAYER) = 0.0
      END IF
  110 CONTINUE
      IF (OLDNC.LT.LAYER) THEN
      TCDT(LAYER) = TCDT(OLDNC)
      VAPCDT(LAYER) = VAPCDT(OLDNC)
      WCANDT(LAYER) = WCANDT(OLDNC)
      DO 120 J=1, NPLANT
      TLCDT(J, LAYER)=TLCDT(J, OLDNC)
  120 CONTINUE
      END IF
      IF (LAYER.EQ.1) THEN
      ZC(1) = 0.0
      ELSE
      ZC(LAYER) = PLANTZ(HTORDR(NPLANT))-(LYRTOP-DZ(LAYER)/2.)
      END IF
      IF (LAYER.EQ.1) THEN
      IF (ABS(PLANTZ(HTORDR(NPLANT))-LYRTOP).GT.0.0001) THEN
      WRITE (6, *) 'ERROR MATCHING TOP OF CANOPY'
      WRITE (6, *) '  LYRTOP =  ' , LYRTOP
      END IF
      GO TO 190
      END IF
      IF (LYRTOP .GE. PLANTZ(HTORDR(HTINDX))-.0001) THEN
      LAISUM = LAISUM - TOTLAI(HTORDR(HTINDX))/PLANTZ(HTORDR(HTINDX))
      HTINDX = HTINDX + 1
      END IF
      LYRTOT = 0.0
      LAILYR = 0.0
      LAYER = LAYER - 1
      ELSE
      LYRTOT = LYRTOT + PLANTZ(HTORDR(HTINDX))-LYRTOP
      LAILYR = LAILYR + (A-LAILYR) * ((PLANTZ(HTORDR(HTINDX))-LYRTOP)/DZMAX)
      LAISUM = LAISUM - TOTLAI(HTORDR(HTINDX))/PLANTZ(HTORDR(HTINDX))
      LYRTOP = PLANTZ(HTORDR(HTINDX))
      HTINDX = HTINDX + 1
      END IF
      GO TO 100
  190 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: CANLAYZC
      SUBROUTINE SHP_CANLAYZC (NC, NCMAX, NPLANT, MZCINP, INITAL, ITYPE, ZC, ZZC, WCANDT, TCDT, TLCDT, VAPCDT, PLANTZ,
     >PLANTW, TOTLAI, RLEAF0, DRYCAN, CANLAI, RLEAF, PLTHMAX, SNODEPTH)
      REAL ZC(11), ZZC(11), WCANDT(10), TCDT(11), TLCDT(8, 10), VAPCDT(11), PLANTZ(8), PLANTW(8), TOTLAI(8), RLEAF0(8),
     >DRYCAN(8, 10), CANLAI(8, 10), RLEAF(8, 10)
      REAL ZMID(10)
      REAL LYRTOP, LYRBTM
      INTEGER ITYPE(8), OLDNC
      COMMON /SHP_SV_CANLAYZC/ MZC, ZMID
      IF (INITAL .EQ. 0) THEN
      MZC = ABS(MZCINP)
      DO I=1, MZC
      ZMID(I) = ZZC(MZC+1) - (ZZC(I+1)+ZZC(I))/2.
      END DO
      ZMID(MZC) = 0.0
      END IF
      OLDNC = NC
      NC = MZC
      NCSNOW = MZC-1
      DO I=1, MZC
      IF (SNODEPTH .LT. ZZC(MZC+1)-ZZC(I)) NCSNOW = MZC-I
      IF (PLTHMAX .LT. ZMID(I)) NC = MZC-I
      END DO
      NMISS = MZC - NC
      NCMAX = NC
      NC = NC - NCSNOW
      DELTA = PLTHMAX - (ZZC(MZC+1)-ZZC(NMISS+1))
      PLTZMAX = PLTHMAX - SNODEPTH
      LYRTOP = PLTZMAX
      ZC(1) = 0.
      DO 25 I=1, NC
      ZC(I+1) = ZZC(NMISS+I+1) - ZZC(NMISS+1) + DELTA
      IF (I .EQ. NC) THEN
      IF (NC .EQ. 1) THEN
      DZ = PLTZMAX
      ELSE
      DZ = ZC(NC+1)-ZC(NC) + (ZC(NC)-ZC(NC-1))/2.
      IF (DZ .GT. LYRTOP) THEN
      DZ = LYRTOP
      IF (SNODEPTH .GT. ZMID(NC)) THEN
      DELSNO = SNODEPTH - ZMID(NC)
      ZC(NC) = ZC(NC) - (DELSNO/(ZC(NC+1)-ZC(NC))) *(ZC(NC)-(ZC(NC)+ZC(NC-1))/2.)
      END IF
      END IF
      END IF
      ZC(NC+1) = PLTZMAX
      ELSEIF (I .EQ. 1) THEN
      DZ = (ZC(I+1) - ZC(I))/2.
      ELSE
      DZ = (ZC(I+1) - ZC(I-1))/2.
      END IF
      LYRBTM = LYRTOP-DZ
      IF (LYRBTM .LT. 0.0) LYRBTM=0.0
      DO 24 J = 1, NPLANT
      IF (PLANTZ(J).GE.LYRTOP) THEN
      FACTOR = DZ / PLANTZ(J)
      ELSE IF (PLANTZ(J).GT.LYRBTM) THEN
      FACTOR = (PLANTZ(J)-LYRBTM) / PLANTZ(J)
      ELSE
      FACTOR = 0.0
      END IF
      CANLAI(J, I) = TOTLAI(J) * FACTOR
      DRYCAN(J, I) = PLANTW(J) * FACTOR
      IF (ITYPE(J).NE.0) THEN
      IF (FACTOR*TOTLAI(J).NE.0) THEN
      RLEAF(J, I) = RLEAF0(J)*(CANLAI(J, I)/TOTLAI(J))
      ELSE
      RLEAF(J, I) = 0.0
      END IF
      ELSE
      RLEAF (J, I) = 0.0
      END IF
   24 CONTINUE
      LYRTOP = LYRBTM
      IF (OLDNC.LT.I) THEN
      TCDT(I) = TCDT(OLDNC)
      VAPCDT(I) = VAPCDT(OLDNC)
      WCANDT(I) = WCANDT(OLDNC)
      DO J=1, NPLANT
      TLCDT(J, I)=TLCDT(J, OLDNC)
      END DO
      END IF
   25 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: RTDIST
      SUBROUTINE SHP_RTDIST (NPLANT, ITYPE, NS, ZS, ROOTDP, RROOT0)
      COMMON /SHP_CLAYRS/ PLANTZ(8), DRYCAN(8, 10), CANLAI(8, 10), TOTLAI(8), IEVAP(8), RLEAF(8, 10), RROOT(8, 99),
     >ROOTDN(8, 99), TOTROT(8)
      REAL ZS(99), ROOTDP(8), RROOT0(8)
      INTEGER ITYPE(8)
      DATA RMXDEN/ 0.1/
      DO 30 J=1, NPLANT
      TOTROT(J)=0.0
      IF (ITYPE(J).NE.0 .AND. TOTLAI(J).NE.0.0) THEN
      ZMXDEN=RMXDEN*ROOTDP(J)
      ZMID1=0.0
      DO 10 I=1, NS
      IF (I.LT.NS) THEN
      ZMID2=(ZS(I+1)+ZS(I))/2.
      ELSE
      ZMID2=ZS(NS)
      END IF
      IF (ZMID2.LT.ZMXDEN) THEN
      ROOTDN(J, I)=(ZMID2-ZMID1)*(ZMID2+ZMID1)/ZMXDEN /ROOTDP(J)
      ELSE
      IF (ZMID2.LT.ROOTDP(J)) THEN
      IF (ZMID1.LT.ZMXDEN) THEN
      AREA1=(ZMXDEN-ZMID1)*(ZMXDEN+ZMID1)/ZMXDEN
      AREA2=(ZMID2-ZMXDEN) *(2.-(ZMID2-ZMXDEN)/(ROOTDP(J)-ZMXDEN))
      ROOTDN(J, I)=(AREA1+AREA2)/ROOTDP(J)
      ELSE
      ROOTDN(J, I)=(ZMID2-ZMID1)*(2.*ROOTDP(J)-ZMID2-ZMID1) /(ROOTDP(J)-ZMXDEN)/ROOTDP(J)
      END IF
      ELSE
      IF (ZMID1.LT.ROOTDP(J)) THEN
      ROOTDN(J, I)=1.0-TOTROT(J)
      ELSE
      ROOTDN(J, I)=0.0
      END IF
      END IF
      END IF
      TOTROT(J)=TOTROT(J) + ROOTDN(J, I)
      ZMID1=ZMID2
   10 CONTINUE
      DO 20 I=1, NS
      RROOT(J, I)=RROOT0(J)*ROOTDN(J, I)/TOTROT(J)
   20 CONTINUE
      END IF
   30 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: RESIDUE
      SUBROUTINE SHP_RESIDUE (NR, NRCHANG, INITAL, ZR, RHOR, TRDT, VAPRDT, GMCDT, RLOAD, ZRTHIK, COVER, DIRRES, TMPDAY,
     >HUMDAY, NSALT, TSDT, MATDT, CONCDT)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      REAL TRDT(10), VAPRDT(10), GMCDT(10), RHOR(10), ZR(10)
      REAL TSDT(99), MATDT(99), CONCDT(10, 99)
      REAL LF, LS, LV
      IF (INITAL .EQ. 0 .OR. NR .EQ. 0) THEN
      IF (NR .EQ. 0) NR = 1
      TLCONC=0.0
      DO 10 J=1, NSALT
      TLCONC=TLCONC+CONCDT(J, 1)
   10 CONTINUE
      TOTPOT=MATDT(1)-TLCONC*UGAS*(TSDT(1)+273.16)/G
      CALL SHP_VSLOPE (DUMMY, SATV, TSDT(1))
      VAP=SATV*EXP(.018*G/UGAS/(TSDT(1)+273.16)*TOTPOT)
      IF (VAP .LT. 0.01*SATV) VAP = 0.01*SATV
      ZR(1) = 0.0
      TRDT(1) = TSDT(1)
      VAPRDT(1)=VAP
      IF(GMCDT(1).LE.0.0) THEN
      HUM=VAP/SATV
      CALL SHP_RESHUM(2, HUM, DUMMY, GMCDT(1), TRDT(1))
      END IF
      END IF
      RESDEN=RLOAD/ZRTHIK
      RHOR(1)=RESDEN
      IF (COVER .LT. 0.999) THEN
      DIRRES=-ALOG(1.-COVER)/RLOAD/10.
      ELSE
      DIRRES = 6.9/RLOAD/10.
      END IF
      IF (NRCHANG .EQ. 0 .AND. NR .GT. 1) THEN
      NRNEW = NR
      ELSE
      NRNEW = INT(ZRTHIK/0.050)
      IF (NRNEW .EQ. 0) NRNEW = 1
      IF (NRNEW .GT. 10) NRNEW = 10
      END IF
      IF (INITAL .EQ. 0) THEN
      NEW = NRNEW
      ELSE
      NEW = NRNEW - NR
      IF (NEW .GT. 0) THEN
      DO 20 I = 1, NR
      ZR(NEW+I)=ZRTHIK*(NEW+I-1)/NRNEW
      GMCDT(NEW+I)=GMCDT(I)
      VAPRDT(NEW+I)=VAPRDT(I)
      TRDT(NEW+I)= TRDT(I)
      RHOR(NEW+I)=RESDEN
   20 CONTINUE
      CALL SHP_VSLOPE (DUMMY, SATV, TMPDAY)
      VAP=HUMDAY*SATV
      IF (HUMDAY .LT. 0.01) VAP = 0.01*SATV
      HUM = SATV/VAP
      CALL SHP_RESHUM(2, HUM, DUMMY, GMCDT(1), TMPDAY)
      TRDT(1) = TMPDAY
      VAPRDT(1)=VAP
      END IF
      END IF
      DO 25 I=1, NEW
      ZR(I)=ZRTHIK*(I-1)/NRNEW
      GMCDT(I)=GMCDT(1)
      RHOR(I)=RESDEN
      VAPRDT(I)=VAP
      TRDT(I)= TRDT(1)
   25 CONTINUE
      ZR(NRNEW+1)= ZRTHIK
      NR=NRNEW
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SYSTM
      SUBROUTINE SHP_SYSTM (NC, NPLANT, NSP, HTORDR, ZC, ZSP, ZMSRF, ZHSRF, ZERSRF, ZMSP, ZHSP, HEIGHT, SOLR, TA,
     >TCCRIT)
      COMMON /SHP_WINDV/ ZH, ZM, ZERO, USTAR, STABLE, CONRH, CONRV, ZHLOG, ZMSUB, ZHSUB, ZERSUB, WINDC(11), WINDR(10)
      COMMON /SHP_CLAYRS/ PLANTZ(8), DRYCAN(8, 10), CANLAI(8, 10), TOTLAI(8), IEVAP(8), RLEAF(8, 10), RROOT(8, 99),
     >ROOTDN(8, 99), TOTROT(8)
      REAL ZC(11), ZSP(200), TCCRIT(8)
      INTEGER HTORDR(8)
      ZM=ZMSRF
      ZH=ZHSRF
      ZERO=ZERSRF
      IF (NC .GT. 0) THEN
      IF (NSP .GT. 0) THEN
      ZMSUB=ZMSP
      ZHSUB=ZHSP
      ZERSUB=0.0
      ELSE
      ZMSUB=ZMSRF
      ZHSUB=ZHSRF
      ZERSUB=ZERSRF
      END IF
      SUMLAI = 0.0
      ZMMAX = 0.0
      ZEROMAX = 0.0
      DO 10 K=NPLANT, 1, -1
      J = HTORDR(K)
      IF (PLANTZ(J) .LE. ZEROMAX) GO TO 15
      SUMLAI = SUMLAI + TOTLAI(J)
      ZEROFULL= 0.77*PLANTZ(J)
      ZMFULL = 0.13*PLANTZ(J)
      IF (SUMLAI .LT. 2.0) THEN
      V = (1.-EXP(-SUMLAI))/(1.-EXP(-2.))
      ZEROJ = V*ZEROFULL + (1.-V)*ZERSUB
      ZMJ = V*ZMFULL + (1.-V)*ZMSUB
      ELSE
      ZEROJ = ZEROFULL
      ZMJ = ZMFULL
      END IF
      IF (ZEROJ .GT. ZEROMAX) THEN
      ZEROMAX = ZEROJ
      ZMMAX = ZMJ
      END IF
      IF (SUMLAI .GE. 2.0) GO TO 15
   10 CONTINUE
   15 ZERO = ZEROMAX
      ZM = ZMMAX
      ZH = 0.2*ZM
      IF (SOLR .LT. 10.0) THEN
      DO 20 J=1, NPLANT
      IEVAP(J)=0
   20 CONTINUE
      ELSE
      DO 30 J=1, NPLANT
      IEVAP(J)=1
      IF (TA.LE.TCCRIT(J)) IEVAP(J)=0
   30 CONTINUE
      END IF
      ELSE
      IF (NSP .GT. 0) THEN
      ZM=ZMSP
      ZH=ZHSP
      ZERO=ZSP(NSP+1)
      IF (ZERO+ZM .GT. HEIGHT) ZERO=HEIGHT/2.
      END IF
      END IF
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SWRBAL
      SUBROUTINE SHP_SWRBAL (NPLANT, NC, NSP, NR, XANGLE, CLUMPNG, SWCAN, SWSNOW, SWRES, SWSOIL, SWDOWN, SWUP, SUNHOR,
     >CANALB, ZSP, DZSP, RHOSP, ZR, RHOR, ALBRES, DIRRES, ALBDRY, ALBEXP, VLC, ALATUD, SLOPE, ASPECT, HRNOON, HAFDAY,
     >DECLIN, HOUR, NHRPDT)
      COMMON /SHP_RADCAN/ TDIRCC(10), TDIFFC(10), DIRKL(9, 10), DIFKL(9, 10), FBDU(8), FDDU(8)
      COMMON /SHP_RADRES/ TDIREC(10), TDIFFU(10)
      REAL SWCAN(9, 10), SWSNOW(200), SWRES(10), SWDOWN(11), SWUP(11), CANALB(8), XANGLE(8), CLUMPNG(8), ZSP(200),
     >DZSP(200), RHOSP(200), ZR(10), RHOR(10)
      INTEGER HOUR
      CALL SHP_SOLAR (DIRECT, DIFFUS, SUNSLP, ALTITU, SUNHOR, ALATUD, SLOPE, ASPECT, HRNOON, HAFDAY, DECLIN, HOUR,
     >NHRPDT)
      SWDOWN(1) = DIRECT+DIFFUS
      IF ((DIRECT+DIFFUS) .LE. 0.0) GO TO 60
      ALBSOI=ALBDRY*EXP(-ALBEXP*VLC)
      IF (NSP.GT.0) THEN
      IF (NR .GT. 0) THEN
      ALBNXT=ALBRES
      ALBNXTDIR=ALBRES
      ELSE
      ALBNXT=ALBSOI
      ALBNXTDIR=ALBSOI
      END IF
      CALL SHP_SNOALB (NSP, ALBSNO, ALBSNODIR, ZSP, RHOSP, SUNSLP, ALBNXT)
      END IF
      IF (NC .GT. 0) THEN
      IF (NSP.EQ.0 .AND. NR.GT.0) THEN
      CALL SHP_SWRCAN (NPLANT, NC, NSP, NR, XANGLE, CLUMPNG, SWCAN, SWRES, DIRECT, DIFFUS, SWDOWN, SWUP, SUNSLP, ALTITU,
     >CANALB, ZR, RHOR, ALBRES, DIRRES, ALBSOI, ALBSOI)
      ELSE
      IF (NSP .GT. 0) THEN
      ALBNXT=ALBSNO
      ALBNXTDIR=ALBSNODIR
      ELSE
      ALBNXT=ALBSOI
      ALBNXTDIR=ALBSOI
      END IF
      CALL SHP_SWRCAN (NPLANT, NC, NSP, 0, XANGLE, CLUMPNG, SWCAN, SWRES, DIRECT, DIFFUS, SWDOWN, SWUP, SUNSLP, ALTITU,
     >CANALB, ZR, RHOR, ALBRES, DIRRES, ALBNXT, ALBNXTDIR)
      END IF
      END IF
      IF (NSP.GT.0) THEN
      CALL SHP_SWRSNO (NSP, SWSNOW, DZSP, RHOSP, DIRECT, DIFFUS, REFLECT, ALBSNO, ALBSNODIR)
      SWUP(NC+1) = REFLECT
      END IF
      IF (NR.GT.0) THEN
      IF (NSP.GT.0 .OR. NC.EQ.0) THEN
      CALL SHP_SWRCAN (NPLANT, 0, NSP, NR, XANGLE, CLUMPNG, SWCAN, SWRES, DIRECT, DIFFUS, SWDOWN, SWUP, SUNSLP, ALTITU,
     >CANALB, ZR, RHOR, ALBRES, DIRRES, ALBSOI, ALBSOI)
      END IF
      END IF
      SWSOIL=(DIRECT+DIFFUS)*(1.-ALBSOI)
      IF (NC.EQ.0 .AND. NSP.EQ.0 .AND. NR.EQ.0) SWUP(1)=(DIRECT+DIFFUS)*ALBSOI
      RETURN
   60 DO 70 I=1, NC
      DO 65 J=1, NPLANT+1
      SWCAN(J, I)=0.0
   65 CONTINUE
      SWDOWN(I)=0.0
      SWUP(I)=0.0
   70 CONTINUE
      SWDOWN(NC+1)=0.0
      SWUP(NC+1)=0.0
      IF (NC.GT.0) CALL SHP_TRANSC (NPLANT, NC, XANGLE, CLUMPNG, TDIRCC, TDIFFC, DIFKL, DIRKL, FBDU, FDDU, 0.0, 0.0)
      DO 80 I=1, NSP
      SWSNOW(I)=0.0
   80 CONTINUE
      DO 90 I=1, NR
      SWRES(I)=0.0
   90 CONTINUE
      IF (NR .GT. 0) CALL SHP_TRANSR (NR, TDIREC, TDIFFU, ZR, RHOR, 0.785, DIRRES)
      SWSOIL=0.0
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SOLAR
      SUBROUTINE SHP_SOLAR (DIRECT, DIFFUS, SUNSLP, ALTITU, SUNHOR, ALATUD, SLOPE, ASPECT, HRNOON, HAFDAY, DECLIN, HOUR,
     >NHRPDT)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_SWRCOE/ SOLCON, DIFATM, DIFRES, SNOCOF, SNOEXP
      INTEGER HOUR
      IF (SUNHOR .LE. 0.0) THEN
      DIRECT=0.0
      DIFFUS=0.0
      RETURN
      END IF
      SUNRIS=HRNOON - HAFDAY/0.261799
      SUNSET=HRNOON + HAFDAY/0.261799
      IF (ABS(DECLIN).GE.ABS(ALATUD)) THEN
      HRWEST=3.14159
      ELSE
      HRWEST=ACOS(TAN(DECLIN)/TAN(ALATUD))
      END IF
      SINAZM=0.0
      COSAZM=0.0
      SUMALT=0.0
      COSALT=0.0
      SUNMAX=0.0
      DO 10 IHR=HOUR-NHRPDT, HOUR
      THOUR=IHR
      HRANGL=0.261799*(IHR-HRNOON)
      IF (THOUR .GT. SUNRIS .AND. THOUR .LT. SUNSET) THEN
      SINALT=SIN(ALATUD)*SIN(DECLIN) + COS(ALATUD)*COS(DECLIN)*COS(HRANGL)
      ALTITU=ASIN(SINALT)
      term = (-COS(DECLIN)*SIN(HRANGL)/COS(ALTITU))
      IF (term .ge. 1.0) term = 1.0
      IF (term .le.-1.0) term = -1.0
      AZM = ASIN(TERM)
      IF (ALATUD-DECLIN .GT. 0.0) THEN
      IF (ABS(HRANGL).LT.HRWEST) AZM=3.14159-AZM
      ELSE
      IF (ABS(HRANGL).GE.HRWEST) AZM=3.14159-AZM
      END IF
      SUN=SOLCON*SINALT
      SUMALT=SUMALT+SUN*SINALT
      COSALT=COSALT+SUN*COS(ALTITU)
      SINAZM=SINAZM+SUN*SIN(AZM)
      COSAZM=COSAZM+SUN*COS(AZM)
      SUNMAX=SUNMAX+SUN
      END IF
   10 CONTINUE
      IF (SUNMAX .EQ. 0) THEN
      ALTITU=0.0
      SUNSLP=0.0
      ELSE
      ALTITU=ATAN(SUMALT/COSALT)
      AZMUTH=ATAN2(SINAZM, COSAZM)
      SUNMAX=SUNMAX/(NHRPDT+1)
      SUNSLP=ASIN( SIN(ALTITU)*COS(SLOPE) + COS(ALTITU)*SIN(SLOPE)*COS(AZMUTH-ASPECT))
      END IF
      IF (ALTITU .LE. 0.0) THEN
      DIFFUS=SUNHOR
      DIRECT=0.0
      RETURN
      END IF
      TTOTAL=SUNHOR/SUNMAX
      IF (TTOTAL .GT. DIFATM) TTOTAL = DIFATM
      TDIFFU=TTOTAL*(1. - EXP(0.6*(1.-DIFATM/TTOTAL)/(DIFATM-0.4)))
      DIFFUS=TDIFFU*SUNMAX
      DIRHOR=SUNHOR-DIFFUS
      IF (SUNSLP .LE. 0.0) THEN
      DIRECT=0.0
      ELSE
      DIRECT=DIRHOR*SIN(SUNSLP)/SIN(ALTITU)
      IF (DIRECT .GT. 5.*DIRHOR) DIRECT=5.*DIRHOR
      END IF
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SNOALB
      SUBROUTINE SHP_SNOALB (NSP, ALBSNO, ALBSNODIR, ZSP, RHOSP, SUNSLP, ALBNXT)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SWRCOE/ SOLCON, DIFATM, DIFRES, SNOCOF, SNOEXP
      COMMON /SHP_SPPROP/ G1, G2, G3, EXTSP, TKSPA, TKSPB, TKSPEX, VDIFSP, VAPSPX
      REAL LF, LS, LV
      REAL RHOSP(200), ZSP(200)
      data vis / 0.58/
      SPGRAV = RHOSP(1)/RHOL
      GRAIN = G1 + G2*SPGRAV*SPGRAV + G3*SPGRAV**4
      ALBSNO = 1. - 0.206*EXTSP*SQRT(GRAIN)
      IF (ALBSNO .LT. 0.35) ALBSNO = 0.35
      IF (ZSP(NSP+1) .LE. 0.04) THEN
      ABS = 1. - ALBNXT
      W = 2.*(1. - ALBSNO)/(1. + ALBSNO)
      EXC = EXTSP*SPGRAV*SQRT(1.0/GRAIN)*100.
      Y = EXP(-EXC*ZSP(NSP+1))*(ABS + W*(ABS/2.-1.)) / (W*(ABS/2.-1.)*COSH(EXC*ZSP(NSP+1))-ABS*SINH(EXC*ZSP(NSP+1)))
      ALBSNO = (1. - W*(1.-Y)/2)/(1. + W*(1.-Y)/2)
      END IF
      IF (ZSP(NSP+1) .LT. SNOCOF) THEN
      ALBSNO = ALBNXT + (ALBSNO-ALBNXT)*(ZSP(NSP+1)/SNOCOF)**SNOEXP
      END IF
      SPGRAV = RHOSP(1)/RHOL
      GRAIN = G1 + G2*SPGRAV*SPGRAV + G3*SPGRAV**4
      if (sunslp .gt. 0.0) then
      dzv = (1.375e-3*sqrt(grain*1000.))*(1.-sin(sunslp))
      dzir= (2.0e-3*sqrt(grain*1000.) + 0.1)*(1.-sin(sunslp))
      else
      DZV = 0.0
      DZIR = 0.0
      END IF
      albsnodir = albsno + dzv*vis + dzir*(1-vis)
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SWRSNO
      SUBROUTINE SHP_SWRSNO (NSP, SWSNOW, DZSP, RHOSP, DIRECT, DIFFUS, REFLECT, ALBSNO, ALBSNODIR)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SPPROP/ G1, G2, G3, EXTSP, TKSPA, TKSPB, TKSPEX, VDIFSP, VAPSPX
      REAL LF, LS, LV
      REAL SWSNOW(200), RHOSP(200), DZSP(200)
      TOTAL = DIRECT*(1.-ALBSNODIR) + DIFFUS*(1. - ALBSNO)
      REFLECT = DIRECT+DIFFUS-TOTAL
      DO 10 I= 1, NSP
      SPGRAV = RHOSP(I)/RHOL
      GRAIN = G1 + G2*SPGRAV*SPGRAV + G3*SPGRAV**4
      EXC = EXTSP*SPGRAV*SQRT(1.0/GRAIN)*100.
      PERCAB = 1.0 - EXP(-EXC*DZSP(I))
      SWSNOW(I) = TOTAL*PERCAB
      TOTAL = TOTAL - SWSNOW(I)
   10 CONTINUE
      DIFFUS = TOTAL
      DIRECT = 0.0
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SWRCAN
      SUBROUTINE SHP_SWRCAN (NPLANT, NC, NSP, NR, XANGLE, CLUMPNG, SWCAN, SWRES, DIRECT, DIFFUS, SWDOWN, SWUP, SUNSLP,
     >ALTITU, CANALB, ZR, RHOR, ALBRES, DIRRES, ALBNXT, ALBNXTDIR)
      COMMON /SHP_RADCAN/ TDIRCC(10), TDIFFC(10), DIRKL(9, 10), DIFKL(9, 10), FBDU(8), FDDU(8)
      COMMON /SHP_RADRES/ TDIREC(10), TDIFFU(10)
      REAL SWCAN(9, 10), SWRES(10), SWDOWN(11), SWUP(11), CANALB(8), XANGLE(8), CLUMPNG(8), DIRALB(10), DIFALB(10),
     >DIRTRN(10), DIFTRN(10), FBREFU(10), FDREFU(10), FBTRNU(10), FDTRNU(10), FBREFD(10), FDREFD(10), FBTRND(10),
     >FDTRND(10), ZR(10), RHOR(10), A(42), B(42), C(42), D(42), DIR(21), DOWN(21), UP(21)
      REAL CANTRN(8)
      DATA CANTRN /8*0.20/
      IF (NC .GT. 0) THEN
      CALL SHP_TRANSC (NPLANT, NC, XANGLE, CLUMPNG, TDIRCC, TDIFFC, DIFKL, DIRKL, FBDU, FDDU, SUNSLP, ALTITU)
      DO 15 I=1, NC
      DIRALB(I)=0.0
      DIFALB(I)=0.0
      DIRTRN(I)=0.0
      DIFTRN(I)=0.0
      FBREFU(I)=0.0
      FDREFU(I)=0.0
      FBTRNU(I)=0.0
      FDTRNU(I)=0.0
      DO 10 J=1, NPLANT
      DIRALB(I) = DIRALB(I) + CANALB(J)*DIRKL(J, I)
      DIFALB(I) = DIFALB(I) + CANALB(J)*DIFKL(J, I)
      DIRTRN(I) = DIRTRN(I) + CANTRN(J)*DIRKL(J, I)
      DIFTRN(I) = DIFTRN(I) + CANTRN(J)*DIFKL(J, I)
      FBREFU(I) = FBREFU(I) + FBDU(J)*CANALB(J)*DIRKL(J, I)
      FDREFU(I) = FDREFU(I) + FDDU(J)*CANALB(J)*DIFKL(J, I)
      FBTRNU(I) = FBTRNU(I) + (1.-FBDU(J))*CANTRN(J)*DIRKL(J, I)
      FDTRNU(I) = FDTRNU(I) + (1.-FDDU(J))*CANTRN(J)*DIFKL(J, I)
   10 CONTINUE
      IF (DIRALB(I) .GT. 0.0) THEN
      FBREFU(I)=FBREFU(I)/DIRALB(I)
      FDREFU(I)=FDREFU(I)/DIFALB(I)
      END IF
      IF (DIRTRN(I) .GT. 0.0) THEN
      FBTRNU(I)=FBTRNU(I)/DIRTRN(I)
      FDTRNU(I)=FDTRNU(I)/DIFTRN(I)
      END IF
      FBREFD(I)=1. - FBREFU(I)
      FDREFD(I)=1. - FDREFU(I)
      FBTRND(I)=1. - FBTRNU(I)
      FDTRND(I)=1. - FDTRNU(I)
      DIRALB(I)=DIRALB(I)/DIRKL(NPLANT+1, I)
      DIFALB(I)=DIFALB(I)/DIFKL(NPLANT+1, I)
      DIRTRN(I)=DIRTRN(I)/DIRKL(NPLANT+1, I)
      DIFTRN(I)=DIFTRN(I)/DIFKL(NPLANT+1, I)
   15 CONTINUE
      END IF
      IF (NR .GT. 0) CALL SHP_TRANSR (NR, TDIREC, TDIFFU, ZR, RHOR, SUNSLP, DIRRES)
      NR1=NR
      IF (NR.EQ.1) THEN
      NR1=2
      TDIREC(1)=SQRT(TDIREC(1))
      TDIFFU(1)=SQRT(TDIFFU(1))
      TDIREC(2)=TDIREC(1)
      TDIFFU(2)=TDIFFU(1)
      END IF
      N = 1
      A(1) = 0.0
      B(1) = 1.0
      C(1) = 0.0
      D(1) = DIFFUS
      DIR(1)=DIRECT
      DO 20 I=1, NC
      N = N + 1
      A(N) =-(1.-TDIFFC(I))*(FDREFU(I)*DIFALB(I)+FDTRNU(I)*DIFTRN(I))
      B(N) = 1.0
      C(N) = -TDIFFC(I) - (1.-TDIFFC(I))*(FDREFD(I)*DIFALB(I)+FDTRND(I)*DIFTRN(I))
      D(N) = (1.-TDIRCC(I))*(FBREFU(I)*DIRALB(I)+FBTRNU(I)*DIRTRN(I)) *DIR(I)
      N = N + 1
      A(N) = C(N-1)
      B(N) = 1.0
      C(N) = A(N-1)
      D(N) = (1.-TDIRCC(I))*(FBREFD(I)*DIRALB(I)+FBTRND(I)*DIRTRN(I)) *DIR(I)
      DIR(I+1)=DIR(I)*TDIRCC(I)
   20 CONTINUE
      DO 30 I=1, NR1
      N = N + 1
      A(N) = -ALBRES*(1.-TDIFFU(I))
      B(N) = 1.0
      C(N) = -TDIFFU(I)
      D(N) = ALBRES*(1.-TDIREC(I))*DIR(NC+I)
      N = N + 1
      A(N) = C(N-1)
      B(N) = 1.0
      C(N) = A(N-1)
      D(N) = 0.0
      DIR(NC+I+1)=DIR(NC+I)*TDIREC(I)
   30 CONTINUE
      N = N + 1
      B(N) = 1.0
      C(N) = 0.0
      A(N) = -ALBNXT
      D(N) = ALBNXTDIR*DIR(NC+NR1+1)
      NLAYR = NC + NR1
      CALL SHP_SOLVRAD (NLAYR, A, B, C, D, DOWN, UP)
      DO 65 I=1, NC
      TOTDIR=0.0
      TOTDIF=0.0
      DO 63 J=1, NPLANT
      TOTDIR = TOTDIR + (1.-CANALB(J)-CANTRN(J))*DIRKL(J, I)
      TOTDIF = TOTDIF + (1.-CANALB(J)-CANTRN(J))*DIFKL(J, I)
   63 CONTINUE
      SWCAN(NPLANT+1, I)=0.0
      DO 64 J=1, NPLANT
      FRACT1=(1.-CANALB(J)-CANTRN(J))*DIRKL(J, I)/TOTDIR
      FRACT2=(1.-CANALB(J)-CANTRN(J))*DIFKL(J, I)/TOTDIF
      SWCAN(J, I)= FRACT1*(1.-DIRALB(I)-DIRTRN(I)) *(1.-TDIRCC(I))*DIR(I) + FRACT2*(1.-DIFALB(I)-DIFTRN(I))
     >*(1.-TDIFFC(I))*(DOWN(I)+UP(I+1))
      SWCAN(NPLANT+1, I)=SWCAN(NPLANT+1, I)+SWCAN(J, I)
   64 CONTINUE
      SWDOWN(I)=DIR(I)+DOWN(I)
      SWUP(I) =UP(I)
   65 CONTINUE
      IF (NC .GT. 0)THEN
      SWDOWN(NC+1)=DIR(NC+1)+DOWN(NC+1)
      SWUP(NC+1)=UP(NC+1)
      ELSE
      IF (NSP .EQ. 0) SWUP(1)=UP(1)
      END IF
      ABSORB=0.0
      DO 70 I=1, NR1
      K=I+NC
      SWRES(I)=DIR(K)+DOWN(K)+UP(K+1)-DIR(K+1)-DOWN(K+1)-UP(K)
      ABSORB=ABSORB + SWRES(I)
   70 CONTINUE
      IF (NR .EQ. 1) THEN
      SWRES(1)=SWRES(1)+SWRES(2)
      SWRES(2)=0.0
      END IF
      IF (NR.GT.0 .AND. NSP.GT.0) THEN
      IF (ABSORB .GT. 0.0) THEN
      DO 80 I=1, NR
      SWRES(I)=SWRES(I) + UP(1)*SWRES(I)/ABSORB
   80 CONTINUE
      END IF
      END IF
      DIRECT=DIR(NC+NR1+1)
      DIFFUS=DOWN(NC+NR1+1)
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: TRANSC
      SUBROUTINE SHP_TRANSC (NPLANT, NC, XANGLE, CLUMPNG, TDIRCC, TDIFFC, DIFKL, DIRKL, FBDU, FDDU, SUNSLP, ALTITU)
      COMMON /SHP_CLAYRS/ PLANTZ(8), DRYCAN(8, 10), CANLAI(8, 10), TOTLAI(8), IEVAP(8), RLEAF(8, 10), RROOT(8, 99),
     >ROOTDN(8, 99), TOTROT(8)
      REAL XANGLE(8), CLUMPNG(8), TDIRCC(10), TDIFFC(10), DIRKL(9, 10), DIFKL(9, 10), FBDU(8), FDDU(8)
      REAL DIRCAN(8), DIFCAN(8)
      DATA AA/0.65/ BB/1.9/ CC/1.46/ DD/ 0.585/ EE/ 0.569/ FF/ 1.09/ GG/ 1.585/
      DO 5 J=1, NPLANT
      IF (SUNSLP .GT. 0.0) THEN
      IF (XANGLE(J) .LE. 0.0) THEN
      IF (ALTITU .GE. 1.57) THEN
      DIRCAN(J) = 0.0
      ELSE
      DIRCAN(J)=1./(1.5708*TAN(ALTITU))
      END IF
      ELSE
      ZEN = 1.571 - SUNSLP
      DIRCAN(J)=(XANGLE(J)*XANGLE(J) + (TAN(ZEN))**2)**0.5 /(XANGLE(J) + 1.774*(XANGLE(J)+1.182)**(-0.733))
      END IF
      IF (DIRCAN(J) .GT. 10.) DIRCAN(J)=10.
      ELSE
      DIRCAN(J) = 1.0
      END IF
      IF (XANGLE(J) .LE. 1.0) THEN
      DIFINF = ATAN(XANGLE(J))/1.5708
      ELSE
      DIFINF = XANGLE(J)**CC/(XANGLE(J)**CC + 1.)
      END IF
      DIFCAN(J)= (DIFINF*CLUMPNG(J)*TOTLAI(J)**AA + BB)/ (CLUMPNG(J)*TOTLAI(J)**AA + BB)
      FBDU(J) = 0.5 + 0.5*(ATAN(XANGLE(J))/1.5708)**DD *XANGLE(J)**((COS(ALTITU))**(EE+FF*XANGLE(J)))*SIN(ALTITU)
      FDDU(J) = 0.5 + 0.5*(ATAN(XANGLE(J))/1.5708)**GG
    5 CONTINUE
      DO 20 I=1, NC
      DIRKL(NPLANT+1, I)=0.0
      DIFKL(NPLANT+1, I)=0.0
      DO 10 J=1, NPLANT
      DIRKL(J, I)=CLUMPNG(J)*CANLAI(J, I)*DIRCAN(J)
      DIFKL(J, I)=CLUMPNG(J)*CANLAI(J, I)*DIFCAN(J)
      DIRKL(NPLANT+1, I)=DIRKL(NPLANT+1, I)+DIRKL(J, I)
      DIFKL(NPLANT+1, I)=DIFKL(NPLANT+1, I)+DIFKL(J, I)
   10 CONTINUE
      IF (SUNSLP .LE. 0.0) THEN
      TDIRCC(I)=0.0
      ELSE
      TDIRCC(I)=EXP(-DIRKL(NPLANT+1, I))
      END IF
      TDIFFC(I)=EXP(-DIFKL(NPLANT+1, I))
   20 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: TRANSR
      SUBROUTINE SHP_TRANSR (NR, TDIREC, TDIFFU, ZR, RHOR, ANGLE, DIRRES)
      COMMON /SHP_SWRCOE/ SOLCON, DIFATM, DIFRES, SNOCOF, SNOEXP
      REAL TDIREC(10), TDIFFU(10), ZR(10), RHOR(10)
      DO 10 I=1, NR
      IF (I .EQ. 1) THEN
      W=RHOR(I)*(ZR(2)-ZR(1))*10.
      IF (NR .NE. 1) W=W/2.
      ELSE
      IF (I .EQ. NR) THEN
      W=RHOR(I)*(ZR(NR+1)-ZR(NR)+(ZR(NR)-ZR(NR-1))/2)*5.
      ELSE
      W=RHOR(I)*(ZR(I+1)-ZR(I-1))*5.
      END IF
      END IF
      IF (ANGLE .LE. 0.0) THEN
      TDIREC(I)=0.0
      ELSE
      TDIREC(I)=EXP(-DIRRES*W)*SIN(ANGLE)
      END IF
      TDIFFU(I)=DIFRES*EXP(-DIRRES*W)
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SOLVRAD
      SUBROUTINE SHP_SOLVRAD (NLAYR, A, B, C, D, RD, RU)
      REAL A(42), B(42), C(42), D(42), RD(21), RU(21)
      DO 40 N=1, NLAYR
      K = 2*N - 1
      I = K + 1
      QUOT = A(I)/B(K)
      B(I)=B(I)-QUOT*C(K)
      D(I)=D(I)-QUOT*D(K)
      A(I) = 0.0
      I = K + 2
      QUOT = A(I)/B(K)
      A(I)=-QUOT*C(K)
      D(I)=D(I)-QUOT*D(K)
      K = K + 1
      QUOT = A(I)/B(K)
      C(I)=C(I)-QUOT*C(K)
      D(I)=D(I)-QUOT*D(K)
      A(I) = 0.0
   40 CONTINUE
      K = 2*(NLAYR+1) - 1
      I = K + 1
      QUOT = A(I)/B(K)
      B(I)=B(I)-QUOT*C(K)
      D(I)=D(I)-QUOT*D(K)
      A(I)=0.0
      RU(NLAYR+1)=D(2*(NLAYR+1))/B(2*(NLAYR+1))
      DO 60 N=NLAYR, 1, -1
      I = 2*N + 1
      RD(N+1) = (D(I) - C(I)*RU(N+1))/B(I)
      I = 2*N
      RU(N) = (D(I) - C(I)*RU(N+1))/B(I)
   60 CONTINUE
      RD(1) = D(1)/B(1)
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: UPDATE
      SUBROUTINE SHP_UPDATE (NS, NR, NSP, NC, NPLANT, NSALT, ICES, ICESDT, TS, TSDT, MAT, MATDT, CONC, CONCDT, VLC,
     >VLCDT, VIC, VICDT, SALT, SALTDT, TR, TRDT, VAPR, VAPRDT, GMC, GMCDT, TC, TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN,
     >WCANDT, PCAN, PCANDT, TSP, TSPDT, DLW, DLWDT, ICESP, ICESPT)
      REAL TS(99), TSDT(99), MAT(99), MATDT(99), CONC(10, 99), CONCDT(10, 99), VLC(99), VLCDT(99), VIC(99), VICDT(99),
     >SALT(10, 99), SALTDT(10, 99)
      REAL TR(10), TRDT(10), VAPR(10), VAPRDT(10), GMC(10), GMCDT(10)
      REAL TC(11), TCDT(11), TLC(8, 10), TLCDT(8, 10), VAPC(11), VAPCDT(11), WCAN(10), WCANDT(10), PCAN(8), PCANDT(8)
      REAL TSP(200), TSPDT(200), DLW(200), DLWDT(200)
      INTEGER ICES(99), ICESDT(99), ICESP(200), ICESPT(200)
      DO 15 I=1, NS
      TS(I)=TSDT(I)
      MAT(I)=MATDT(I)
      VLC(I)=VLCDT(I)
      VIC(I)=VICDT(I)
      ICES(I)=ICESDT(I)
      DO 10 J=1, NSALT
      SALT(J, I)=SALTDT(J, I)
      CONC(J, I)=CONCDT(J, I)
   10 CONTINUE
   15 CONTINUE
      DO 20 I=1, NR
      TR(I)=TRDT(I)
      VAPR(I)=VAPRDT(I)
      GMC(I)=GMCDT(I)
   20 CONTINUE
      DO 30 I=1, NSP
      ICESP(I) = ICESPT(I)
      TSP(I) = TSPDT(I)
      DLW(I) = DLWDT(I)
   30 CONTINUE
      DO 40 I=1, NC
      TC(I)=TCDT(I)
      VAPC(I)=VAPCDT(I)
      WCAN(I)=WCANDT(I)
      DO 35 J=1, NPLANT
      TLC(J, I)=TLCDT(J, I)
   35 CONTINUE
   40 CONTINUE
      DO 45 J=1, NPLANT
      PCAN(J)=PCANDT(J)
   45 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: LWRBAL
      SUBROUTINE SHP_LWRBAL (NC, NSP, NR, NPLANT, TA, TADT, TLC, TLCDT, TSP, TSPDT, TR, TRDT, TS, TSDT, VAPA, VAPADT,
     >CLOUDS, LWCAN, LWSNOW, LWRES, LWSOIL, LWDOWN, LWUP)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_LWRCOF/ STEFAN, EMATM1, EMATM2, EMITC, EMITR, EMITSP, EMITS
      common/ canlwr/ tlclwr(8, 10)
      REAL TLC(8, 10), TLCDT(8, 10), TSP(200), TSPDT(200), TR(10), TRDT(10), TS(99), TSDT(99), LWCAN(9, 10), LWSNOW,
     >LWRES(10), LWSOIL, LWDOWN(11), LWUP(11)
      CALL SHP_LWRATM (ABOVE, CLOUDS, TA, TADT, VAPA, VAPADT)
      LWDOWN(1) = ABOVE
      IF (NSP .GT. 0) THEN
      TK = TSP(1)+273.16
      EMITSFC=EMITSP*STEFAN *(TK**4 + 4.*WDT*(TK**3) *(TSPDT(1)-TSP(1)))
      ELSE
      TK=TS(1) + 273.16
      EMITSFC=EMITS*STEFAN*((TK**4)+4.*WDT*(TK**3)*(TSDT(1)-TS(1)))
      END IF
      IF (NC .GT. 0) THEN
      DO 25 I=1, NC
      DO 20 J=1, NPLANT
      tlclwr(j, i) = tlcdt(j, i)
   20 CONTINUE
   25 CONTINUE
      IF (NSP.EQ.0 .AND. NR.GT.0) THEN
      CALL SHP_LWRCAN (NPLANT, NC, NSP, NR, TLC, TLCDT, TR, TRDT, ABOVE, EMITSFC, LWCAN, LWRES, LWDOWN, LWUP)
      ELSE
      CALL SHP_LWRCAN (NPLANT, NC, NSP, 0, TLC, TLCDT, TR, TRDT, ABOVE, EMITSFC, LWCAN, LWRES, LWDOWN, LWUP)
      END IF
      END IF
      IF (NSP .GT. 0) THEN
      LWSNOW = EMITSP*ABOVE - EMITSFC
      LWSOIL = 0.0
      DO 30 I=1, NR
      LWRES(I) = 0.0
   30 CONTINUE
      LWUP(NC+1)= (1.-EMITSP)*ABOVE + EMITSFC
      ELSE
      IF (NR .GT. 0) THEN
      IF (NC.EQ.0) THEN
      CALL SHP_LWRCAN (NPLANT, 0, NSP, NR, TLC, TLCDT, TR, TRDT, ABOVE, EMITSFC, LWCAN, LWRES, LWDOWN, LWUP)
      END IF
      END IF
      LWSOIL = EMITS*ABOVE - EMITSFC
      IF (NC.EQ.0 .AND. NR.EQ.0) LWUP(1)=(1.-EMITS)*ABOVE + EMITSFC
      END IF
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: LWRCAN
      SUBROUTINE SHP_LWRCAN (NPLANT, NC, NSP, NR, TLC, TLCDT, TR, TRDT, ABOVE, EMITSFC, LWCAN, LWRES, LWDOWN, LWUP)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_LWRCOF/ STEFAN, EMATM1, EMATM2, EMITC, EMITR, EMITSP, EMITS
      COMMON /SHP_RADCAN/ TDIRCC(10), TDIFFC(10), DIRKL(9, 10), DIFKL(9, 10), FBDU(8), FDDU(8)
      COMMON /SHP_RADRES/ TDIREC(10), TDIFFU(10)
      REAL TLC(8, 10), TLCDT(8, 10), TR(10), TRDT(10), LWCAN(9, 10), LWRES(10), LWDOWN(11), LWUP(11)
      REAL A(42), B(42), C(42), D(42), RD(21), RU(21), DDU(10)
      N = 1
      A(1) = 0.0
      B(1) = 1.0
      C(1) = 0.0
      D(1) = ABOVE
      DO 20 I=1, NC
      N = N + 1
      D(N) = 0.0
      DDU(I) = 0.0
      DO 10 J=1, NPLANT
      TK=TLC(J, I)+273.16
      EMIT=EMITC*STEFAN*(TK**4 + 4.*(TK**3)*(TLCDT(J, I)-TLC(J, I)))
      FRACTN = (1.-TDIFFC(I))*DIFKL(J, I)/DIFKL(NPLANT+1, I)
      LWCAN(J, I)= -2.*FRACTN*EMIT
      D(N) = D(N) + FRACTN*EMIT
      DDU(I) = DDU(I) + FDDU(J)*DIFKL(J, I)
   10 CONTINUE
      DDU(I) = DDU(I)/DIFKL(NPLANT+1, I)
      A(N) = -DDU(I)*(1.-EMITC)*(1.-TDIFFC(I))
      B(N) = 1.0
      C(N) = -(TDIFFC(I) + (1.-DDU(I))*(1.-EMITC)*(1.-TDIFFC(I)))
      N = N + 1
      A(N) = C(N-1)
      B(N) = 1.0
      C(N) = A(N-1)
      D(N) = D(N-1)
   20 CONTINUE
      DO 30 I=1, NR
      N = N + 1
      TK=TR(I)+273.16
      EMIT=(1.-TDIFFU(I))*EMITR*STEFAN *(TK**4 + 4.*WDT*(TK**3)*(TRDT(I)-TR(I)))
      LWRES(I)=-2.*EMIT
      A(N) = -(1.-EMITR)*(1.-TDIFFU(I))
      B(N) = 1.0
      C(N) = -TDIFFU(I)
      D(N) = EMIT
      N = N + 1
      A(N) = C(N-1)
      B(N) = 1.0
      C(N) = A(N-1)
      D(N) = D(N-1)
   30 CONTINUE
      N = N + 1
      B(N) = 1.0
      C(N) = 0.0
      IF (NSP .GT. 0) THEN
      A(N) = -(1.-EMITSP)
      ELSE
      A(N) = -(1.-EMITS)
      END IF
      D(N) = EMITSFC
      NLAYR = NC + NR
      CALL SHP_SOLVRAD (NLAYR, A, B, C, D, RD, RU)
      N = 0
      DO 40 I=1, NC
      N = N + 1
      LWCAN(NPLANT+1, I) = 0.0
      ABSORB = (1.-TDIFFC(I))*EMITC*(RD(N)+RU(N+1))
      DO 35 J=1, NPLANT
      LWCAN(J, I)=LWCAN(J, I) + ABSORB*DIFKL(J, I)/DIFKL(NPLANT+1, I)
      LWCAN(NPLANT+1, I) = LWCAN(NPLANT+1, I) + LWCAN(J, I)
   35 CONTINUE
      LWDOWN(I)=RD(I)
      LWUP(I) =RU(I)
   40 CONTINUE
      IF (NC .GT. 0)THEN
      LWDOWN(NC+1)=RD(NC+1)
      LWUP(NC+1)=RU(NC+1)
      ELSE
      IF (NSP .EQ. 0) LWUP(1)=RU(1)
      END IF
      DO 50 I=1, NR
      N = N + 1
      LWRES(I)=LWRES(I) + (1.-TDIFFU(I))*EMITR*(RD(N)+RU(N+1))
   50 CONTINUE
      ABOVE = RD(N+1)
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: LWRATM
      SUBROUTINE SHP_LWRATM (ABOVE, CLOUDS, TA, TADT, VAPA, VAPADT)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_LWRCOF/ STEFAN, EMATM1, EMATM2, EMITC, EMITR, EMITSP, EMITS
      AVGTMP = WT*TA + WDT*TADT
      AVGVAP = WT*VAPA + WDT*VAPADT
      AVGVAP = 0.4619*AVGVAP*(AVGTMP+273.16)
      CLEAR =59.38+113.7*((AVGTMP+273.16)/273.16)**6 +96.96*SQRT((465.*AVGVAP/(AVGTMP+273.16))/2.5)
      BLACK = STEFAN*(AVGTMP+273.16)**4
      EMITAT=CLEAR/BLACK
      EMITAT=(1.-0.84*CLOUDS)*EMITAT + 0.84*CLOUDS
      ABOVE = EMITAT*BLACK
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: LWRMAT
      SUBROUTINE SHP_LWRMAT (NC, NSP, NR, TC, TSP, TR, TS, ICESPT)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_MATRIX/ A1(350), B1(350), C1(350), D1(350), A2(350), B2(350), C2(350), D2(350)
      COMMON /SHP_LWRCOF/ STEFAN, EMATM1, EMATM2, EMITC, EMITR, EMITSP, EMITS
      COMMON /SHP_RADCAN/ TDIRCC(10), TDIFFC(10), DIRKL(9, 10), DIFKL(9, 10), FBDU(8), FDDU(8)
      COMMON /SHP_RADRES/ TDIREC(10), TDIFFU(10)
      REAL TC(11), TSP(200), TR(10), TS(99)
      INTEGER ICESPT(200)
      N = 1
      MATERL=2
      B1(N) = 0.0
      IF (NC .GT. 0) THEN
      EMITNC=(1.-TDIFFC(1))*EMITC
      B1(N) =0.0
      C1(N) =0.0
      A1(N+1) =0.0
      N = N + 1
      DO 10 I=2, NC
      EMITNC=(1.-TDIFFC(I))*EMITC
      C1(N-1)=0.0
      A1(N) = 0.0
      B1(N) = 0.0
      C1(N)= 0.0
      A1(N+1) = 0.0
      N = N + 1
   10 CONTINUE
      MATERL=MATERL + 1
      END IF
      IF (NSP .GT. 0) THEN
      IF (ICESPT(1) .GT. 0) THEN
      IF (MATERL .GT. 2) THEN
      A1(N) = A1(N)*EMITSP
      C1(N-1)=0.0
      END IF
      B1(N) = 0.0
      ELSE
      TSP3=STEFAN*4.*WDT*(TSP(1)+273.16)**3
      IF (MATERL .GT. 2) THEN
      A1(N) = A1(N)*EMITSP
      C1(N-1)=C1(N-1)*EMITSP*TSP3
      END IF
      B1(N) = -EMITSP*TSP3
      END IF
      N = N + NSP
      MATERL=MATERL + 1
      IF (NSP .GT. 1) B1(N-1) = 0.0
      C1(N-1) = 0.0
      DO 5 I=1, NR+1
      A1(N) = 0.0
      B1(N) = 0.0
      C1(N) = 0.0
      N = N + 1
    5 CONTINUE
      GO TO 50
      END IF
      IF (NR .GT. 0) THEN
      EMITNC=(1-TDIFFU(1))*EMITR
      TR3=STEFAN*4.*WDT*(TR(1)+273.16)**3
      IF (MATERL .GT. 2) THEN
      A1(N) = A1(N)*EMITNC
      C1(N-1)=C1(N-1)*EMITNC*TR3
      END IF
      B1(N) =-2.*EMITNC*TR3
      C1(N) = EMITNC
      A1(N+1) = EMITNC*TR3
      N = N + 1
      DO 20 I=2, NR
      EMITNC=(1-TDIFFU(I))*EMITR
      TR3=STEFAN*4.*WDT*(TR(I)+273.16)**3
      C1(N-1)=C1(N-1)*EMITNC*TR3
      A1(N) = A1(N)*EMITNC
      B1(N) = -2.*EMITNC*TR3
      C1(N) = EMITNC
      A1(N+1) =EMITNC*TR3
      N = N + 1
   20 CONTINUE
      MATERL = MATERL + 1
      END IF
      TS3=STEFAN*4.*WDT*(TS(1)+273.16)**3
      IF (MATERL .GT. 2) THEN
      A1(N) = A1(N)*EMITS
      C1(N-1)=C1(N-1)*EMITS*TS3
      END IF
      B1(N)=-EMITS*TS3
   50 RETURN
      END
C     USDA-ARS SHAW 3.0.3: SOURCE
      SUBROUTINE SHP_SOURCE (NC, NSP, NR, NS, NSALT, NPLANT, UC, SC, USP, SSP, UR, SR, US, SS, SINK, SWCAN, SWSNOW,
     >SWRES, SWSOIL, LWCAN, LWSNOW, LWRES, LWSOIL, SOILXT)
      REAL UC(10), SC(10), USP(200), SSP(200), UR(10), SR(10), US(99), SS(99), SINK(10, 99), SWCAN(9, 10), SWSNOW(200),
     >SWRES(10), SWSOIL, LWCAN(9, 10), LWSNOW, LWRES(10), LWSOIL, SOILXT(99)
      DO 10 I=1, NC
      UC(I)=0.0
      SC(I)=SWCAN(NPLANT+1, I)+LWCAN(NPLANT+1, I)
   10 CONTINUE
      IF (NSP .GT. 0) THEN
      DO 20 I=1, NSP
      USP(I)=0.0
      SSP(I)=SWSNOW(I)
   20 CONTINUE
      SSP(1)=SSP(1)+LWSNOW
      END IF
      DO 30 I=1, NR
      UR(I)=0.0
      SR(I)=SWRES(I)+LWRES(I)
   30 CONTINUE
      DO 50 I=1, NS
      US(I)=-SOILXT(I)
      SS(I)=0.0
      DO 40 J=1, NSALT
      SINK(J, I)=0.0
   40 CONTINUE
   50 CONTINUE
      SS(1)=SS(1)+SWSOIL+LWSOIL
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: ATSTAB
      SUBROUTINE SHP_ATSTAB (NPLANT, NC, NSP, NR, TA, TADT, T, TDT, VAPA, VAPADT, VAP, VAPDT, WIND, HEIGHT, HFLUX,
     >VFLUX, ZC, ZR, RHOR, ICE, ITER)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_MATRIX/ A1(350), B1(350), C1(350), D1(350), A2(350), B2(350), C2(350), D2(350)
      COMMON /SHP_CLAYRS/ PLANTZ(8), DRYCAN(8, 10), CANLAI(8, 10), TOTLAI(8), IEVAP(8), RLEAF(8, 10), RROOT(8, 99),
     >ROOTDN(8, 99), TOTROT(8)
      COMMON /SHP_WINDV/ ZH, ZM, ZERO, USTAR, STABLE, CONRH, CONRV, ZHLOG, ZMSUB, ZHSUB, ZERSUB, WINDC(11), WINDR(10)
      COMMON /SHP_WRITEIT/ hflux1, rh, hnc, xlenc, contk, tleaf(8, 10)
      REAL LF, LS, LV
      REAL ZC(11), ZR(10), RHOR(10)
      COMMON /SHP_SV_ATSTAB/ TMPAIR, VAPAIR, ZMLOG, ZCLOG, PSIM, PSIH
      IF (ITER .LE. 2) THEN
      IF (ITER .LE. 1) THEN
      TMPAIR=WT*TA + WDT*TADT
      VAPAIR=WT*VAPA + WDT*VAPADT
      ZMLOG=ALOG((HEIGHT+ZM-ZERO)/ZM)
      ZHLOG=ALOG((HEIGHT+ZH-ZERO)/ZH)
      IF (NC .GT. 0) ZCLOG=ALOG((ZC(NC+1)-ZERO+ZH)/ZH)
      END IF
      HFLUX=0.0
      PSIM=0.0
      PSIH=0.0
      END IF
      TMPSFC=WT*T + WDT*TDT
      VAPSFC=WT*VAP + WDT*VAPDT
      IF (WIND .LE. 0.0) THEN
      HFLUX=0.0
      VFLUX=0.0
      STABLE=0.0
      USTAR=0.0
      ELSE
      CALL SHP_STAB(ITER, NC, ZC(NC+1), TMPAIR, TMPSFC, WIND, HEIGHT, ZMLOG, ZHLOG, ZCLOG, HFLUX, USTAR, STABLE, PSIM,
     >PSIH, RH, ZERO)
      END IF
      IF (NC .gt. 0) THEN
      HMIN=TKA*(TMPAIR-TMPSFC)/(HEIGHT-ZC(NC+1))
      ELSE
      HMIN=TKA*(TMPAIR-TMPSFC)/(HEIGHT-ZERO)
      END IF
      IF (ABS(HMIN) .LE. ABS(HFLUX)) THEN
      IF (NC .GT. 0) THEN
      RHZC=RH*(1. - (ZCLOG/ZHLOG))
      CON=RHOA*CA/RHZC
      ELSE
      CON=RHOA*CA/RH
      END IF
      ELSE
      HFLUX=HMIN
      if (nc .gt. 0) then
      CON=TKA/(HEIGHT-ZC(NC+1))
      else
      CON=TKA/(HEIGHT-ZERO)
      end if
      END IF
      CONRH = 1./RH
      hflux1=hflux
      RV=RH
      if (nc .gt. 0) RV = RHZC
      VFLUX=(VAPAIR-VAPSFC)/RV
      DV=VDIFF*(((TMPAIR+273.16)/273.16)**2)*(P0/PRESUR)
      if (nc .eq. 0) then
      VMIN=DV*(VAPAIR-VAPSFC)/(HEIGHT-ZERO)
      else
      VMIN=DV*(VAPAIR-VAPSFC)/(HEIGHT-ZC(NC+1))
      end if
      IF (ABS(VMIN) .LE. ABS(VFLUX)) THEN
      CONV=1./RV
      ELSE
      VFLUX=VMIN
      CONV=DV
      END IF
      IF (NC .GT. 0) THEN
      B1(1)=B1(1) - CON
      D1(1)=HFLUX
      B2(1)=-CONV
      D2(1)=VFLUX
      WINDC(1)=USTAR*ALOG((ZC(NC+1)+ZM-ZERO)/ZM)/VONKRM
      SUMLAI=0.0
      DO 40 J=1, NPLANT
      SUMLAI = SUMLAI + TOTLAI(J)
   40 CONTINUE
      AWIND = 2.879*(1-EXP(-SUMLAI))
      DO 45 I=2, NC+1
      SUML = 0.0
      DO 42 J=1, NPLANT
      SUML = SUML+CANLAI(J, I-1)
   42 CONTINUE
      WINDEXP = WINDC(I-1)*EXP(-AWIND*SUML/SUMLAI)
      IF (I .LT. NC+1) THEN
      HNODE1 = ZC(NC+1) - ZC(I-1)
      HNODE2 = ZC(NC+1) - ZC(I)
      ZMCAN1 = ALOG((HNODE1+ZMSUB-ZERSUB)/ZMSUB)
      ZMCAN2 = ALOG((HNODE2+ZMSUB-ZERSUB)/ZMSUB)
      WSTAR = WINDC(I-1)*VONKRM/ZMCAN1
      WINDLOG = WSTAR*ZMCAN2/VONKRM
      WINDC(I) = MIN(WINDLOG, WINDEXP)
      ELSE
      WINDC(I) = WINDEXP
      END IF
   45 CONTINUE
      IF (NR.GT.0 .AND. NSP.EQ.0) THEN
      WINDRH = WINDC(NC+1)
      ELSE
      WINDRH=0.0
      END IF
      ELSE
      IF (NSP .GT. 0) THEN
      CALL SHP_VSLOPE (S, DUMMY, TDT)
      IF (ICE .EQ. 0) THEN
      B1(1) = B1(1) - WDT*CON - WDT*LS*S*CONV
      ELSE
      B1(1) = B1(1)
      END IF
      D1(1)=HFLUX + LS*VFLUX
      B2(1)=0.0
      D2(1)=0.0
      WINDRH=0.0
      ELSE
      IF (NR .GT. 0) THEN
      B1(1)=B1(1) - WDT*CON
      D1(1)=HFLUX
      B2(1)=-WDT*CONV
      D2(1)=VFLUX
      WINDRH=USTAR*ALOG((ZR(NR+1)+ZM-ZERO)/ZM)/VONKRM
      ELSE
      CALL SHP_VSLOPE (S, DUMMY, TDT)
      D1(1)=HFLUX+LV*VFLUX
      D2(1)=VFLUX/RHOL
      IF (ICE .EQ. 0) THEN
      B1(1) = B1(1) - WDT*CON - WDT*LV*S*CONV
      B2(1) = -WDT*VAPDT*CONV*0.018*G/(UGAS*(TDT+273.16))/RHOL
      ELSE
      B1(1) = B1(1)
      B2(1) = 0.0
      END IF
      END IF
      END IF
      END IF
      IF (NR .GT. 0) THEN
      AWIND = 0.1*(RHOR(1) - 20.)
      IF (AWIND .LT. 0.0) AWIND=0.0
      WINDR(1)=WINDRH*EXP(-AWIND*(ZR(1)+ZR(2))/4/ZR(NR+1))
      DO 65 I=2, NR+1
      WINDR(I) = WINDRH*EXP(-AWIND*ZR(I)/ZR(NR+1))
   65 CONTINUE
      END IF
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: EBCAN
      SUBROUTINE SHP_EBCAN (N, NPLANT, NC, NSP, NR, NS, ZC, TC, TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN, WCANDT, PCAN,
     >PCANDT, MAT, MATDT, SWCAN, LWCAN, SWDOWN, CANMA, CANMB, DCHAR, RSTOM0, RSTEXP, PLEAF0, RLEAF0, ITYPE, ISTOMATE,
     >STOMATE, ITER)
      COMMON /SHP_OPTIONS/ SHP_CANOPY_WATER_TOL, SHP_CANOPY_JACOBIAN
      REAL SHP_CANOPY_WATER_TOL
      INTEGER SHP_CANOPY_JACOBIAN
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_MATRIX/ A1(350), B1(350), C1(350), D1(350), A2(350), B2(350), C2(350), D2(350)
      COMMON /SHP_WRITEIT/ hflux1, rh, hnc, xlenc, contk, tleaf(8, 10)
      REAL LF, LS, LV
      REAL ZC(11), TC(11), TCDT(11), TLC(8, 10), TLCDT(8, 10), VAPC(11), VAPCDT(11), WCAN(10), WCANDT(10), PCAN(8),
     >PCANDT(8), MAT(99), MATDT(99), SWCAN(9, 10), LWCAN(9, 10), SWDOWN(11)
      REAL DCHAR(8), RSTOM0(8), RSTEXP(8), PLEAF0(8), RLEAF0(8), STOMATE(8, 10)
      REAL CON(10), TRNSP(9), XTRACT(99), HEATC(10), ETLYR(10), DETLYR(10), DHEATC(10), DTLDTC(10)
      INTEGER ITYPE(8)
      CALL SHP_LEAFT (NPLANT, NC, NS, ITER, ITYPE, TC, TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN, WCANDT, PCAN, PCANDT, MAT,
     >MATDT, TRNSP, XTRACT, SWCAN, LWCAN, SWDOWN, HEATC, ETLYR, DETLYR, CANMA, CANMB, DCHAR, RSTOM0, RSTEXP, PLEAF0,
     >RLEAF0, ISTOMATE, STOMATE, DHEATC, DTLDTC)
      CALL SHP_CANTK (ITER, NC, CON, TCDT, ZC)
      contk = con(nc)
      A1(N+1)=A1(N+1) + CON(1)
C     Optional canopy storage Jacobian correction; residual volume is unchanged.
      IF (SHP_CANOPY_JACOBIAN .NE. 0 .AND. NC .EQ. 1) THEN
      B1(N)=B1(N)-(CON(1)+DHEATC(1)*(1.-DTLDTC(1)))-(ZC(2)-ZC(1))/DT*RHOA*CA
      ELSE
      B1(N)=B1(N) - (CON(1)+DHEATC(1)*(1.-DTLDTC(1))) - (ZC(2)-ZC(1))/(2.*DT)*RHOA*CA
      END IF
      IF (NC .EQ. 1) THEN
      C1(N)=C1(N) + WDT*CON(1)
      D1(N)=D1(N) - CON(1)*(WT*(TCDT(1)-TC(2))+WDT*(TCDT(1)-TCDT(2))) + HEATC(1)
     >-(ZC(2)-ZC(1))/DT*RHOA*CA*(TCDT(1)-TC(1))
      ELSE
      C1(N)=C1(N) + CON(1)
      D1(N)=D1(N) - CON(1)*(TCDT(1)-TCDT(2)) + HEATC(1) -(ZC(2)-ZC(1))/(2.*DT)*RHOA*CA*(TCDT(1)-TC(1))
      END IF
      DO 10 I=N+1, N+NC-1
      J=I-N+1
      A1(I+1)=A1(I+1) + CON(J)
C     Optional canopy storage Jacobian correction; residual volume is unchanged.
      IF (SHP_CANOPY_JACOBIAN .NE. 0 .AND. J .EQ. NC) THEN
      B1(I)=B1(I)-(CON(J-1)+CON(J)+DHEATC(J)*(1.-DTLDTC(J)))-(ZC(J+1)-ZC(J)+(ZC(J)-ZC(J-1))/2.)/DT*RHOA*CA
      ELSE
      B1(I)=B1(I) - (CON(J-1) +CON(J) +DHEATC(J)*(1.-DTLDTC(J))) - (ZC(J+1)-ZC(J-1))/(2.*DT)*RHOA*CA
      END IF
      IF (J .EQ. NC) THEN
      C1(I)=C1(I) + WDT*CON(J)
      D1(I)=CON(J-1)*(TCDT(J-1)-TCDT(J)) -CON(J)*(WDT*(TCDT(J)-TCDT(J+1)) + WT*(TCDT(J)-TC(J+1)))
     >-(ZC(J+1)-ZC(J)+(ZC(J)-ZC(J-1))/2)/DT *RHOA*CA*(TCDT(J)-TC(J)) + HEATC(J)
      ELSE
      C1(I)=C1(I) + CON(J)
      D1(I)=CON(J-1)*(TCDT(J-1)-TCDT(J))-CON(J)*(TCDT(J)-TCDT(J+1)) -(ZC(J+1)-ZC(J-1))/(2.*DT)*RHOA*CA*(TCDT(J)-TC(J))
     >+HEATC(J)
      END IF
   10 CONTINUE
      N=N+NC
      IF (NSP.GT.0 .OR. NR.EQ.0) THEN
      CONV=CON(NC)/RHOA/CA
      QVCAN=CONV*(WDT*(VAPCDT(NC)-VAPCDT(NC+1)) + WT*(VAPCDT(NC)-VAPC(NC+1)))
      CALL SHP_VSLOPE (SLPNC, SATV, TC(NC))
      HUMNC=VAPCDT(NC)
      CALL SHP_VSLOPE (SLPNC1, SATV, TC(NC+1))
      HUMNC1=VAPCDT(NC+1)/SATV
      END IF
      IF (NSP.GT.0) THEN
      A1(N) = A1(N) + CONV*LS*SLPNC*HUMNC
      B1(N) = B1(N) - WDT*(CON(NC) + CONV*LS*SLPNC1*HUMNC1)
      D1(N) =CON(NC)*(WT*(TCDT(NC)-TC(NC+1)) +WDT*(TCDT(NC)-TCDT(NC+1))) + LS*QVCAN
      ELSE
      IF (NR.GT.0) THEN
      B1(N) = B1(N) - WDT*CON(NC)
      D1(N) =CON(NC)*(WT*(TCDT(NC)-TC(NC+1)) +WDT*(TCDT(NC)-TCDT(NC+1)))
      ELSE
      A1(N) = A1(N) + CONV*LV*SLPNC*HUMNC
      B1(N) = B1(N) - WDT*(CON(NC) + CONV*LV*SLPNC1*HUMNC1)
      D1(N) = CON(NC)*(WT*(TCDT(NC)-TC(NC+1)) + WDT*(TCDT(NC)-TCDT(NC+1)))+ LV*QVCAN
      END IF
      END IF
      hnc = CON(NC)*(WT*(TCDT(NC)-TCDT(NC+1))+WDT*(TCDT(NC)-TCDT(NC+1)))
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: LEAFT
      SUBROUTINE SHP_LEAFT (NPLANT, NC, NS, ITER, ITYPE, TC, TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN, WCANDT, PCAN, PCANDT,
     >MAT, MATDT, TRNSP, XTRACT, SWCAN, LWCAN, SWDOWN, HEATC, ETLYR, DETLYR, CANMA, CANMB, DCHAR, RSTOM0, RSTEXP,
     >PLEAF0, RLEAF0, ISTOMATE, STOMATE, DHEATC, DTLDTC)
      COMMON /SHP_OPTIONS/ SHP_CANOPY_WATER_TOL, SHP_CANOPY_JACOBIAN
      REAL SHP_CANOPY_WATER_TOL
      INTEGER SHP_CANOPY_JACOBIAN
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_CLAYRS/ PLANTZ(8), DRYCAN(8, 10), CANLAI(8, 10), TOTLAI(8), IEVAP(8), RLEAF(8, 10), RROOT(8, 99),
     >ROOTDN(8, 99), TOTROT(8)
      COMMON /SHP_WINDV/ ZH, ZM, ZERO, USTAR, STABLE, CONRH, CONRV, ZHLOG, ZMSUB, ZHSUB, ZERSUB, WINDC(11), WINDR(10)
      COMMON /SHP_LWRCOF/ STEFAN, EMATM1, EMATM2, EMITC, EMITR, EMITSP, EMITS
      COMMON /SHP_RADCAN/ TDIRCC(10), TDIFFC(10), DIRKL(9, 10), DIFKL(9, 10), FBDU(8), FDDU(8)
      common/ canlwr/ tlclwr(8, 10)
      COMMON /SHP_WRITEIT/ hflux1, rh, hnc, xlenc, contk, tleaf(8, 10)
      REAL LF, LV, LS
      REAL TC(11), TCDT(11), TLC(8, 10), TLCDT(8, 10), VAPC(11), VAPCDT(11), WCAN(10), WCANDT(10), PCAN(8), PCANDT(8),
     >MAT(99), MATDT(99), TRNSP(9), XTRACT(99), SWCAN(9, 10), LWCAN(9, 10), SWDOWN(11), HEATC(10), ETLYR(10),
     >DETLYR(10), DHEATC(10), DTLDTC(10)
      REAL DCHAR(8), RSTOM0(8), RSTEXP(8), PLEAF0(8), RLEAF0(8), STOMATE(8, 10)
      REAL AVGTMP(10), AVGVAP(10), AVGDEF(10), RSTOM(10), PLEAF(10), PEVAP(10), PXYLEM(8), RHCAN(8, 10), RVCAN(8, 10),
     >ETCAN(8, 10), AVGMAT(99), HUMID(10), VTSLOP(10)
      REAL F1(10), DF1DP(10), DF1DT(10), DF1DX(10), DP(10), AA1(10), CC1(10), F2(10), DF2DP(10), DF2DT(10), DF2DX(10),
     >DTLC(10), DF3DP(10), A1LWR(8, 10)
      INTEGER INIT(8), ITYPE(8)
      COMMON /SHP_SV_LEAFT/ INIT, PXYLEM, RHCAN, RVCAN, ETCAN
      DO 5 I=1, NS
      XTRACT(I)=0.0
      AVGMAT(I)=WT*MAT(I)+WDT*MATDT(I)
      IF (AVGMAT(I) .GT. 0.0) AVGMAT(I) = 0.0
    5 CONTINUE
      TRNSP(NPLANT+1)=0.0
      DO 10 I=1, NC
      AVGTMP(I)=TCDT(I)
      AVGVAP(I)=VAPCDT(I)
      IF (ISTOMATE .EQ. 2) THEN
      CALL SHP_VSLOPE (DUMMY, SATV, AVGTMP(I))
      AVGDEF(I) = SATV-AVGVAP(I)
      END IF
      HEATC(I)=0.0
      DHEATC(I)=0.0
      ETLYR(I)=0.0
      DETLYR(I)=0.0
      DTLDTC(I)=0.0
      DO 8 J=1, NPLANT
      A1LWR(J, I) = 8.*(1.-TDIFFC(I))*DIFKL(J, I)/DIFKL(NPLANT+1, I) *EMITC*STEFAN*((tlclwr(j, i)+273.16)**3)
      IF (ITER .EQ. 1) THEN
      TERM=SQRT(DCHAR(J)/WINDC(I))*PRESUR/UGAS/(TCDT(I)+273.16)
      RHCAN(J, I)=7.40*TERM
      RVCAN(J, I)=6.80*TERM
      INIT(J)=1
      END IF
    8 CONTINUE
   10 CONTINUE
      DO 60 J=1, NPLANT
      SUMET=0.0
      SUMEV = 0.0
      FRACTN = 1.0
      IF (TOTLAI(J) .EQ. 0.0) THEN
      TRNSP(J)=0.0
      GO TO 60
      END IF
      IF (ITYPE(J) .NE. 0) THEN
      PCANDT(J)=0.0
      IF (IEVAP(J) .EQ. 0 .OR. PCAN(J) .GT. 0.0) THEN
      FRACTN=0.0
      DO 12 I=1, NC
      IF (CANLAI(J, I) .LE. 0.0) GO TO 12
      PLEAF(I) = 0.0
      RSTOM(I)=RSTOM0(J)
      ETCAN(J, I)=0.0
      IF (PCAN(J) .GT. 0.0) THEN
      HUMID(I)=1.0
      CALL SHP_VSLOPE (VTSLOP(I), SATV, tlclwr(j, I))
      VAPDEF = CANLAI(J, I)*(SATV-AVGVAP(I))
      TLCDT(J, I)=tlclwr(j, i)+(SWCAN(J, I)+LWCAN(J, I) -LV*VAPDEF/RVCAN(J, I) -RHOA*CA*CANLAI(J, I)*(tlclwr(j,
     >i)-AVGTMP(I))/RHCAN(J, I) -DRYCAN(J, I)*CR*(tlclwr(j, i)-TLC(J, I))/DT) /(RHOA*CA*CANLAI(J, I)/RHCAN(J, I) +
     >A1LWR(J, I) + DRYCAN(J, I)*CR/DT +lv*canlai(j, i)*vtslop(i)/rvcan(j, i))
      PEVAP(I)=(CANLAI(J, I)*VTSLOP(I) *(TLCdt(J, I)-tlclwr(j, I))+VAPDEF)/RVCAN(J, I)
      SUMEV=SUMEV+PEVAP(I)
      ELSE
      HUMID(I)=0.0
      VTSLOP(I)=0.0
      PEVAP(I)=0.0
      SUMEV=0.0
      TLCDT(J, I)=tlclwr(j, i)+(SWCAN(J, I)+LWCAN(J, I) -RHOA*CA*CANLAI(J, I)*(tlclwr(j, i)-AVGTMP(I))/RHCAN(J, I)
     >-DRYCAN(J, I)*CR*(tlclwr(j, i)-TLC(J, I))/DT) /(RHOA*CA*CANLAI(J, I)/RHCAN(J, I) +A1LWR(J, I) + DRYCAN(J,
     >I)*CR/DT)
      END IF
   12 CONTINUE
      IF (PCAN(J) .GT. 0.0) THEN
      PCANDT(J)=PCAN(J)-DT*SUMEV/RHOL
      IF (PCANDT(J) .LT. 0.0) THEN
      PCANDT(J)=0.0
      FRACTN= 1. - (RHOL*PCAN(J)/DT)/SUMEV
      SUMEV = (1.-FRACTN)*SUMEV
      DO 13 I=1, NC
      PEVAP(I)=PEVAP(I)*(1.-FRACTN)
   13 CONTINUE
      END IF
      END IF
      END IF
      IF (PCANDT(J) .LE. 0.0 .AND. IEVAP(J) .NE. 0) THEN
      MAX=0
      DO 14 I=1, NS
      IF (ROOTDN(J, I).GT.0.0) THEN
      IF (MAX .EQ. 0) THEN
      MAX=I
      MIN=I
      ELSE
      IF (AVGMAT(I).LT.AVGMAT(MIN)) MIN=I
      IF (AVGMAT(I)/RROOT(J, I) .GT. AVGMAT(MAX)/RROOT(J, MAX)) MAX=I
      END IF
      END IF
   14 CONTINUE
      VAPDEF=0.0
      RHAVG=0.0
      RVAVG=0.0
      DO 15 I=1, NC
      IF (CANLAI(J, I) .GT. 0.0) THEN
      IF (FRACTN .GT. 0.999) PEVAP(I)=0.0
      HUMID(I)=1.0
      CALL SHP_VSLOPE (VTSLOP(I), SATV, TLCDT(J, I))
      VAPDEF = VAPDEF + CANLAI(J, I)*(SATV-AVGVAP(I))
      RHAVG = RHAVG + CANLAI(J, I)/RHCAN(J, I)
      RVAVG = RVAVG + CANLAI(J, I)/RVCAN(J, I)
      END IF
   15 CONTINUE
      VAPDEF=VAPDEF/TOTLAI(J)
      IF (VAPDEF .LT. 0.0) VAPDEF=0.0
      RHAVG=TOTLAI(J)/RHAVG
      RVAVG=TOTLAI(J)/RVAVG
      ITER0=0
   18 IF (INIT(J) .EQ. 1) PXYLEM(J)=2.*AVGMAT(MAX)
   19 RSOIL=0.0
      SRROOT=0.0
      IROOT=0
      DO 20 I=1, NS
      IF (ROOTDN(J, I).GT. 0.0) THEN
      IF (AVGMAT(I) .GE. PXYLEM(J)) THEN
      RSOIL=RSOIL + RROOT(J, I)*AVGMAT(I)
      SRROOT= SRROOT + RROOT(J, I)
      ELSE
      IROOT=1
      END IF
      END IF
   20 CONTINUE
      IF (INIT(J) .GT. 1) THEN
      SUMET=RSOIL - PXYLEM(J)*SRROOT
      IF (SUMET*SRROOT .LE. 0.0) THEN
      INIT(J) = 1
      GO TO 18
      END IF
      GO TO 24
      END IF
      IF (SRROOT .EQ. 0.0) THEN
      RSOIL=RROOT(J, MAX)*AVGMAT(MAX)
      SRROOT=RROOT(J, MAX)
      END IF
      SOIMAT=RSOIL/SRROOT
      RESIST= 1/SRROOT + 1/RLEAF0(J)
      IF (ITER0 .EQ. 0) THEN
      PLEAF1=PXYLEM(J)
      IF (PLEAF1/PLEAF0(J) .GT. 40.) THEN
      RSLOG=ALOG10(RSTOM0(J)) + RSTEXP(J)*ALOG10(PLEAF1/PLEAF0(J))
      IF (RSLOG .GT. 20) THEN
      SUMET=0.0
      DO 21 I=1, NC
      IF (CANLAI(J, I) .LE. 0.0) GO TO 21
      HUMID(I)=0.0
      RSTOM(I)=1.0E20
      ETCAN(J, I)=0.0
      TLCDT(J, I)=tlclwr(j, i)+(SWCAN(J, I)+LWCAN(J, I) -RHOA*CA*CANLAI(J, I)*(tlclwr(j, i)-AVGTMP(I))/RHCAN(J, I)
     >-DRYCAN(J, I)*CR*(tlclwr(j, i)-TLC(J, I))/DT) /(RHOA*CA*CANLAI(J, I)/RHCAN(J, I) + A1LWR(J, I) + DRYCAN(J,
     >I)*CR/DT)
   21 CONTINUE
      GO TO 48
      END IF
      END IF
      CALL SHP_STOMATES (J, RSTOM1, DRSDPLF, PLEAF1, SWDOWN(1), AVGTMP(1), AVGDEF(1), RSTOM0, PLEAF0, RSTEXP, ISTOMATE,
     >STOMATE)
      SUMET=TOTLAI(J)*VAPDEF/(RSTOM1+RVAVG)
      PLEAF1=SOIMAT-SUMET*RESIST/2.
      END IF
   22 CALL SHP_STOMATES (J, RSTOM1, DRSDPLF, PLEAF1, SWDOWN(1), AVGTMP(1), AVGDEF(1), RSTOM0, PLEAF0, RSTEXP, ISTOMATE,
     >STOMATE)
      SUMET=TOTLAI(J)*VAPDEF/(RSTOM1+RVAVG)
      ERROR = (SOIMAT-PLEAF1)/RESIST - SUMET
      DERIV = -1./RESIST + SUMET*DRSDPLF/(RSTOM1+RVAVG)
      DELTA=ERROR/DERIV
      ANEG=(PLEAF1-PLEAF0(J))*(PLEAF1-DELTA-PLEAF0(J))
      IF (ANEG .LT. 0.0) THEN
      PLEAF1=PLEAF1-DELTA/2.
      ELSE
      PLEAF1=PLEAF1-DELTA
      END IF
      SUMET = (SOIMAT-PLEAF1)/RESIST
      PXYLEM(J)=(RSOIL-SUMET)/SRROOT
      IF (ABS(PLEAF1) .LT. 1.0) THEN
      COMPAR = 1.0
      ELSE
      COMPAR = PLEAF1
      END IF
      IF (ABS(DELTA/COMPAR).GT.0.01 .AND. ITER0.LE.20) THEN
      ITER0=ITER0+1
      IF (PXYLEM(J).GT.AVGMAT(MIN) .OR. IROOT.GT.0) GO TO 19
      GO TO 22
      END IF
      DO 23 I=1, NC
      ETCAN(J, I)=CANLAI(J, I)*SUMET/TOTLAI(J)
   23 CONTINUE
      INIT(J) = 2
   24 ITER1 = 0
      DO 25 I=1, NC
      IF (CANLAI(J, I) .GT. 0.0) THEN
      PLEAF(I)=PXYLEM(J) - ETCAN(J, I)/RLEAF(J, I)
      DF1DX(I) = -RLEAF(J, I)
      DF2DT(I) = -CANLAI(J, I)*RHOA*CA/RHCAN(J, I) -A1LWR(J, I) - DRYCAN(J, I)*CR/DT
      END IF
   25 CONTINUE
   26 IFLAG= 0
      SUMET=0.0
      DF3DX=0.0
      DO 30 I=1, NC
      IF (CANLAI(J, I) .GT. 0.0) THEN
      CALL SHP_VSLOPE (VTSLOP(I), SATV, TLCDT(J, I))
      CALL SHP_STOMATES (J, RSTOM(I), DRSDPLF, PLEAF(I), SWDOWN(I), AVGTMP(I), AVGDEF(I), RSTOM0, PLEAF0, RSTEXP,
     >ISTOMATE, STOMATE)
      F1(I) =CANLAI(J, I)*(SATV-AVGVAP(I)) /(RSTOM(I)+RVCAN(J, I))
      IF (F1(I) .LT. 0.0) THEN
      VTSLOP(I)=0.0
      ETCAN(J, I)=0.0
      DF1DP(I) = RLEAF(J, I)
      DF1DT(I) = 0.0
      DF2DP(I) = 0.0
      DF2DX(I) = 0.0
      DF3DP(I) = 0.0
      F1(I) = 0.0
      PLEAF(I) = PXYLEM(J)
      ELSE
      ETCAN(J, I)=RLEAF(J, I)*(PXYLEM(J)-PLEAF(I))
      SUMET = SUMET +ETCAN(J, I)
      DF1DP(I) = RLEAF(J, I) - F1(I)*DRSDPLF /(RSTOM(I)+RVCAN(J, I))
      DF1DT(I) = CANLAI(J, I)*VTSLOP(I) /(RSTOM(I)+RVCAN(J, I))
      DF2DP(I) = LV*RLEAF(J, I)
      DF2DX(I) = -DF2DP(I)
      DF3DP(I) = RLEAF(J, I)
      DF3DX = DF3DX - RLEAF(J, I)
      F1(I) = F1(I) - ETCAN(J, I)
      END IF
      F2(I)= SWCAN(J, I) + LWCAN(J, I) - LV*ETCAN(J, I) -A1LWR(J, I)*(tlcdt(j, i)-tlclwr(j, i)) -CANLAI(J,
     >I)*RHOA*CA*(TLCDT(J, I)-AVGTMP(I))/RHCAN(J, I) -DRYCAN(J, I)*CR*(TLCDT(J, I)-TLC(J, I))/DT
      END IF
   30 CONTINUE
      F3 = RSOIL - PXYLEM(J)*SRROOT - SUMET
      DF3DX = DF3DX - SRROOT
      CC3=DF3DX
      IF (SUMET .LE. 0.0) THEN
      SUMET=0.0
      DO 31 I=1, NC
      IF (CANLAI(J, I) .GT. 0.0) THEN
      HUMID(I)=0.0
      RSTOM(I)=1.0E20
      ETCAN(J, I)=0.0
      TLCDT(J, I)=tlclwr(j, i)+(SWCAN(J, I)+LWCAN(J, I) -RHOA*CA*CANLAI(J, I)*(tlclwr(j, i)-AVGTMP(I))/RHCAN(J, I)
     >-DRYCAN(J, I)*CR*(tlclwr(j, i)-TLC(J, I))/DT) /(-DF2DT(I))
      INIT(J)=1
      END IF
   31 CONTINUE
      GO TO 48
      END IF
      DO 32 I=1, NC
      IF (CANLAI(J, I) .GT. 0.0) THEN
      AA1(I)=DF1DP(I)-(DF1DT(I)/DF2DT(I))*DF2DP(I)
      CC1(I)=DF1DX(I)-(DF1DT(I)/DF2DT(I))*DF2DX(I)
C     Optional correction to leaf Newton elimination RHS (F2 is the energy residual).
      IF (SHP_CANOPY_JACOBIAN .NE. 0) THEN
      F1(I)=F1(I)-(DF1DT(I)/DF2DT(I))*F2(I)
      ELSE
      F1(I) = F1(I) -(DF1DT(I)/DF2DT(I))*F1(I)
      END IF
      CC3=CC3-(DF3DP(I)/AA1(I))*CC1(I)
      F3 = F3-(DF3DP(I)/AA1(I))*F1(I)
      END IF
   32 CONTINUE
      DX=F3/CC3
      PXYLEM(J)=PXYLEM(J)-DX
      DO 33 I=1, NC
      IF (CANLAI(J, I) .GT. 0.0) THEN
      DP(I)=(F1(I)-CC1(I)*DX)/AA1(I)
      DTLC(I)=(F2(I)-DF2DX(I)*DX-DF2DP(I)*DP(I))/DF2DT(I)
      PLEAF(I)=PLEAF(I)-DP(I)
      IF (PLEAF(I) .GT. PXYLEM(J)+1.E-5) PLEAF(I)=(PLEAF(I)+DP(I)+PXYLEM(J))/2.
      TLCDT(J, I)=TLCDT(J, I)-DTLC(I)
      IF (ABS(DTLC(I)) .GT. 0.01) IFLAG=IFLAG+1
      END IF
   33 CONTINUE
      IF (IFLAG .GT. 0) THEN
      ITER1 = ITER1 + 1
      IF (ITER1 .LT. 20) GO TO 26
      END IF
      IF (SRROOT*SUMET .NE. 0.0) THEN
      PXYLEM(J)=(RSOIL-SUMET)/SRROOT
      IF (PXYLEM(J).GT.AVGMAT(MIN) .OR. IROOT.GT.0) THEN
      RSOIL=0.0
      SRROOT=0.0
      DO 34 I=1, NS
      IF (ROOTDN(J, I).GT. 0.0) THEN
      IF (AVGMAT(I) .GE. PXYLEM(J)) THEN
      RSOIL=RSOIL + RROOT(J, I)*AVGMAT(I)
      SRROOT= SRROOT + RROOT(J, I)
      END IF
      END IF
   34 CONTINUE
      IF (SRROOT .EQ. 0.0) THEN
      SUMET = 0.0
      PXYLEM(J)=AVGMAT(MAX)
      ELSE
      PXYLEM(J)=(RSOIL-SUMET)/SRROOT
      END IF
      END IF
      DO 35 I=1, NS
      IF (AVGMAT(I) .GT. PXYLEM(J)) XTRACT(I) = XTRACT(I) + FRACTN*TOTROT(J)*RROOT(J, I)*(AVGMAT(I)-PXYLEM(J))
   35 CONTINUE
      ELSE
      SUMET=0.0
      END IF
      TRNSP(NPLANT+1)=TRNSP(NPLANT+1)+FRACTN*SUMET
      ELSE
      INIT(J) = 1
      DO I = 1, NC
      ETCAN(J, I)=0.0
      END DO
      END IF
      ELSE
      DO 45 I=1, NC
      IF (CANLAI(J, I) .LE. 0.0) GO TO 45
      PEVAP(I)=0.0
      RSTOM(I)=0.0
      B1LV = DRYCAN(J, I)/DT
      A1 = -A1LWR(J, I) - CANLAI(J, I)*RHOA*CA/RHCAN(J, I) -DRYCAN(J, I)*(CR+WCAN(I)*CL)/DT
      B1=LV*B1LV
      CALL SHP_VSLOPE (DUMMY, SATV, TLCDT(J, I))
      HUMCAN=AVGVAP(I)/SATV
      CALL SHP_CANHUM (2, HUMCAN, DUMMY, WCHUM, TCDT(I), CANMA, CANMB)
      IF (INIT(J) .EQ. 1) THEN
      ETCAN(J, I)= -B1LV*(WCANDT(I)-WCAN(I))
      IF (ETCAN(J, I) .EQ. 0.0) THEN
      CALL SHP_CANHUM (1, HUMID(I), DUMMY, WCANDT(I), TCDT(I), CANMA, CANMB)
      CALL SHP_VSLOPE (DUMMY, SATV, TLCDT(J, I))
      ETCAN(J, I)=CANLAI(J, I)* (HUMID(I)*SATV-AVGVAP(I))/RVCAN(J, I)
      WCANDT(I) = WCAN(I) - ETCAN(J, I)/B1LV
      IF ((WCANDT(I)-WCHUM)*(WCAN(I)-WCHUM).LT.0.0) THEN
      ETCAN(J, I)= -B1LV*(WCHUM-WCAN(I))
      HUMID(I)=(AVGVAP(I) + ETCAN(J, I)*RVCAN(J, I)/CANLAI(J, I))/SATV
      CALL SHP_CANHUM (2, HUMID(I), DUMMY, WCANDT(I), TCDT(I), CANMA, CANMB)
      ETCAN(J, I)= -B1LV*(WCANDT(I)-WCAN(I))
      END IF
      END IF
      TLCDT(J, I)=-(SWCAN(J, I)+LWCAN(J, I)-LV*ETCAN(J, I) +RHOA*CA*CANLAI(J, I)*AVGTMP(I)/RHCAN(J, I) +DRYCAN(J,
     >I)*(CR+WCAN(I)*CL)*TLC(J, I)/DT) /A1
      END IF
      CALL SHP_VSLOPE (VTSLOP(I), SATV, TLCDT(J, I))
      ITER1 = 0
   40 ETCAN(J, I)= -B1LV*(WCANDT(I)-WCAN(I))
      CALL SHP_CANHUM(1, HUMID(I), HWSLOP, WCANDT(I), TCDT(I), CANMA, CANMB)
      A2 = CANLAI(J, I)*HUMID(I)*VTSLOP(I)/RVCAN(J, I)
      B2 = CANLAI(J, I)*SATV*HWSLOP/RVCAN(J, I) + B1LV
      FF1 = SWCAN(J, I) + LWCAN(J, I) - LV*ETCAN(J, I) -A1LWR(J, I)*(TLCDT(J, I)-TLCLWR(J, I)) -CANLAI(J,
     >I)*RHOA*CA*(TLCDT(J, I)-AVGTMP(I))/RHCAN(J, I) -DRYCAN(J, I)*(CR+WCAN(I)*CL)*(TLCDT(J, I)-TLC(J, I))/DT
      FF2=CANLAI(J, I)*(HUMID(I)*SATV-AVGVAP(I))/RVCAN(J, I) - ETCAN(J, I)
      DET = A1*B2 - A2*B1
      D1 = (FF1*B2 - FF2*B1)/DET
      D2 = (A1*FF2 - A2*FF1)/DET
      TLCDT(J, I)=TLCDT(J, I) - D1
      WCANDT(I) = WCANDT(I) - D2
      CALL SHP_VSLOPE (VTSLOP(I), SATV, TLCDT(J, I))
      HUMCAN=AVGVAP(I)/SATV
      CALL SHP_CANHUM (2, HUMCAN, DUMMY, WCHUM, TCDT(I), CANMA, CANMB)
      DELMAX=WCAN(I)-WCHUM
      DELTA=WCANDT(I)-WCHUM
      IF(DELTA*DELMAX.LT.0.0)THEN
      ETCAN(J, I)= -B1LV*(WCHUM-WCAN(I))
      CALL SHP_CANHUM (1, HUM, DUMMY, WCAN(I), TCDT(I), CANMA, CANMB)
      ETMAX=CANLAI(J, I)*(HUM*SATV-AVGVAP(I))/RVCAN(J, I)
      IF (ABS(ETCAN(J, I)) .GT. ABS(ETMAX)) ETCAN(J, I)=ETMAX
      HUMID(I)=(AVGVAP(I) + ETCAN(J, I)*RVCAN(J, I)/CANLAI(J, I))/SATV
      CALL SHP_CANHUM (2, HUMID(I), DUMMY, WCANDT(I), TCDT(I), CANMA, CANMB)
      END IF
      IF (ABS(D1) .GT. 0.01) THEN
      ITER1 = ITER1 +1
      IF (ITER1 .LT. 10) GO TO 40
      END IF
      ETCAN(J, I)= -B1LV*(WCANDT(I)-WCAN(I))
      SUMET=SUMET+ETCAN(J, I)
   45 CONTINUE
      INIT(J) = 2
      END IF
   48 TRNSP(J)=FRACTN*SUMET+SUMEV
      DO 50 I=1, NC
      IF (CANLAI(J, I) .LE. 0.0) GO TO 50
      HEATC(I)=HEATC(I) + CANLAI(J, I)*RHOA*CA*(TLCDT(J, I)-AVGTMP(I))/RHCAN(J, I)
      ETLYR(I)=ETLYR(I) + FRACTN*ETCAN(J, I) + PEVAP(I)
      DHEATC(I)=DHEATC(I) + CANLAI(J, I)*RHOA*CA/RHCAN(J, I)
      DETLYR(I)=DETLYR(I)+CANLAI(J, I)/(FRACTN*RSTOM(I)+RVCAN(J, I))
      DTLDTC(I)=DTLDTC(I) + LV*HUMID(I)*VTSLOP(I)* CANLAI(J, I)/(FRACTN*RSTOM(I)+RVCAN(J, I))
   50 CONTINUE
   60 CONTINUE
      do i=1, nc
      tleaf(nplant+1, i)=0.0
      do j=1, nplant
      tleaf(j, i)=tlcdt(j, i)
      if (canlai(j, i) .le. 0.0) tleaf(j, i)=0.0
      tleaf(nplant+1, i)=tleaf(nplant+1, i) + tlcdt(j, i)*difkl(j, i)/difkl(nplant+1, i)
      end do
      end do
      DO 70 I=1, NC
      DTLDTC(I)=DHEATC(I)/(DHEATC(I)+DTLDTC(I))
   70 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: STOMATES
      SUBROUTINE SHP_STOMATES (J, RSTOM, DRSDPLF, PLEAF, SWDOWN, TC, VAPDEF, RSTOM0, PLEAF0, RSTEXP, ISTOMATE, STOMATE)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      REAL RSTOM0(8), RSTEXP(8), PLEAF0(8), STOMATE(8, 10)
      REAL LF, LS, LV
      IF (ISTOMATE .EQ. 2) THEN
      IF (SWDOWN+STOMATE(J, 1) .LE. 0.0) THEN
      FSOLAR = 1.0
      ELSE
      IF (SWDOWN .LT. 1000.) THEN
      FSOLAR = SWDOWN*(1000.+STOMATE(J, 1)) /(1000.*(SWDOWN+STOMATE(J, 1)))
      IF (FSOLAR .LT. 0.0001) FSOLAR = 0.0001
      ELSE
      FSOLAR = 1.0
      END IF
      END IF
      IF (TC.GT.STOMATE(J, 2) .AND. TC.LT.STOMATE(J, 3)) THEN
      FTEMP = (TC-STOMATE(J, 2))*(STOMATE(J, 3)-TC)**STOMATE(J, 10) /(STOMATE(J, 4)-STOMATE(J, 2)) /(STOMATE(J,
     >3)-STOMATE(J, 4))**STOMATE(J, 10)
      ELSE
      FTEMP = 0.0001
      END IF
      VDEFkPA = UGAS*VAPDEF*(TC+273.16)/0.018/1000.
      IF (VDEFkPA .LT. 0.) VDEFkPA = 0.0
      FVPD = STOMATE(J, 5) + (1.-STOMATE(J, 5))*STOMATE(J, 6)**VDEFkPA
      FSTOM = FSOLAR*FTEMP*FVPD
      ELSE
      FSTOM = 1.0
      END IF
      RSTOM=RSTOM0(J)*(1. + (PLEAF/PLEAF0(J))**RSTEXP(J))/FSTOM
      DRSDPLF = RSTOM0(J)*RSTEXP(J)*(PLEAF/PLEAF0(J))**(RSTEXP(J)-1.) /PLEAF0(J)/FSTOM
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: CANHUM
      SUBROUTINE SHP_CANHUM (NCALC, HUM, DHDW, WCAN, TC, CANMA, CANMB)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      REAL LF, LV, LS
      IF (NCALC .EQ. 1) THEN
      IF (WCAN .LE. 0.0) THEN
      HUM=0.0
      DHDW=0.0
      ELSE
      HUM=EXP(0.018*G/(UGAS*(TC+273.16))*CANMA*WCAN**(-CANMB))
      DHDW=-0.018*G*CANMA*CANMB*HUM*WCAN**(-CANMB-1.) /(UGAS*(TC+273.16))
      END IF
      ELSE
      IF (HUM .LT. 0.999) THEN
      IF (HUM .LE. 0.0) THEN
      WCAN = 0.0
      ELSE
      WCAN=(ALOG(HUM)*UGAS*(TC+273.16)/0.018/G/CANMA)**(-1./CANMB)
      END IF
      ELSE
      WCAN=(ALOG(0.999)*UGAS*(TC+273.16)/0.018/G/CANMA)**(-1./CANMB)
      END IF
      END IF
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: CANTK
      SUBROUTINE SHP_CANTK (ITER, NC, CON, TC, ZC)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_WINDV/ ZH, ZM, ZERO, USTAR, STABLE, CONRH, CONRV, ZHLOG, ZMSUB, ZHSUB, ZERSUB, WINDC(11), WINDR(10)
      REAL LF, LV, LS
      REAL CON(10), TC(11), ZC(11)
      COMMON /SHP_SV_CANTK/ ZMLOG
      RICHRD=STABLE
      USTAR1 = USTAR
      IF (RICHRD.GT. 1.0) RICHRD= 1.0
      IF (RICHRD.LT. -2.) RICHRD= -2.
      STABL = RICHRD
      IF (STABL .GE. 0) THEN
      PHIW = 1.25*(1. + 0.2*STABL)
      PHIH = 1. + 5.0*STABL
      ELSE
      PHIW = 1.25*(1. - 3.*STABL)**0.33
      PHIH = 1./SQRT(1. - 16.*STABL)
      END IF
      HCEFF = ZERO/0.77
      BTM = ZC(NC+1)
      IF (BTM+ZHSUB .GT. 2.3*HCEFF) THEN
      TL2 = VONKRM*(BTM+ZH-ZERO)
      SIGMA2 = 1.0
      ELSEIF (BTM+ZHSUB .GT. 1.5*HCEFF) THEN
      SIGMA2 = 1.1 + 0.15*((BTM+ZHSUB)/HCEFF-1.5)/0.8
      TL2 = 0.4*HCEFF
      ELSE
      SIGMA2 = 0.664 + 0.436*((BTM+ZHSUB)/HCEFF-0.8)/0.7
      TL2 = 0.4*HCEFF
      END IF
      DO 20 I=1, NC
      RI=g*(TC(I)-TC(I+1))*(zc(I+1)-zc(I)) /(tc(i)+273.16)/(windc(i)-WINDC(I+1))**2
      IF (RI .LE. 0.0) THEN
      STABL = RI
      ELSE
      IF (RI .GT. 0.175) RI = 0.175
      STABL = RI/(1.-5.*RI)
      END IF
      IF (STABL .GT. 1.0) STABL = 1.0
      IF (STABL .LT. -2.) STABL = -2.
      IF (STABL .GE. 0) THEN
      PHIW = 1. + 0.2*STABL
      PHIH = 1. + 5.0*STABL
      ELSE
      PHIW = (1. - 3.*STABL)**0.33
      PHIH = 1./SQRT(1. - 16.*STABL)
      END IF
      IF (I.EQ.NC) THEN
      IF (ITER .LE. 1) THEN
      ZMLOG=ALOG((ZC(NC+1)-ZC(NC)+ZMSUB-ZERSUB)/ZMSUB)
      END IF
      USTAR1=WINDC(NC)*VONKRM/ZMLOG
      END IF
      TOP = BTM
      TL1 = TL2
      SIGMA1=SIGMA2
      BTM = ZC(NC+1) - ZC(I+1)
      RESIST = 0.0
      if (BTM+ZHSUB .gt. 2.3*HCEFF) then
      TL2 = VONKRM*(BTM+ZH-ZERO)
      SIGMA2 = 1.0
      SIGMA = (SIGMA1+SIGMA2)*USTAR1*PHIW/2.
      TL = ((TL1+TL2)/USTAR1/PHIH/PHIW**2)/2.
      tkcan=sigma*sigma*tl
      RESIST = RESIST + (TOP-BTM)/TKCAN
      go to 10
      else
      BTM = 2.3*HCEFF - ZHSUB
      TL2 = VONKRM*(BTM+ZH-ZERO)
      SIGMA2 = 1.0
      tkcan=(TL1+TL2)*USTAR1/PHIH/2.
      RESIST = RESIST + (TOP-BTM)/TKCAN
      TOP = BTM
      BTM = ZC(NC+1) - ZC(I+1)
      tl1 = 0.4*HCEFF
      SIGMA1= 1.25
      end if
      if (BTM+ZHSUB .gt. 1.5*HCEFF) then
      SIGMA2 = 1.1 + 0.15*((BTM+ZHSUB)/HCEFF-1.5)/0.8
      TL2 = 0.4*HCEFF
      SIGMA = (SIGMA1+SIGMA2)*USTAR1*PHIW/2.
      TL = ((TL1+TL2)/USTAR1/PHIH/PHIW**2)/2.
      tkcan=sigma*sigma*tl
      RESIST = RESIST + (TOP-BTM)/TKCAN
      go to 10
      else
      BTM = 1.5*HCEFF - ZHSUB
      sigma2 = 1.1
      tl2 = 0.4*HCEFF
      SIGMA = ((SIGMA1+SIGMA2)*USTAR1*PHIW)/2.
      TL = ((TL1+TL2)/USTAR1/PHIH/PHIW**2)/2.
      tkcan=sigma*sigma*tl
      RESIST = RESIST + (TOP-BTM)/TKCAN
      TOP = BTM
      BTM = ZC(NC+1) - ZC(I+1)
      tl1 = tl2
      SIGMA1= SIGMA2
      end if
      if (BTM+ZHSUB .gt. 0.8*HCEFF) then
      SIGMA2 = 0.664 + 0.436*((BTM+ZHSUB)/HCEFF-0.8)/0.7
      tl2 = 0.4*HCEFF
      SIGMA = ((SIGMA1+SIGMA2)*USTAR1*PHIW)/2.
      TL = ((TL1+TL2)/USTAR1/PHIH/PHIW**2)/2.
      tkcan=sigma*sigma*tl
      RESIST = RESIST + (TOP-BTM)/TKCAN
      go to 10
      else
      BTM = 0.8*HCEFF - ZHSUB
      sigma2 = 0.664
      tl2 = 0.4*HCEFF
      SIGMA = ((SIGMA1+SIGMA2)*USTAR1*PHIW)/2.
      TL = ((TL1+TL2)/USTAR1/PHIH/PHIW**2)/2.
      tkcan=sigma*sigma*tl
      RESIST = RESIST + (TOP-BTM)/TKCAN
      TOP = BTM
      BTM = ZC(NC+1) - ZC(I+1)
      tl1 = tl2
      SIGMA1= SIGMA2
      end if
      IF (BTM+ZHSUB .GT. 0.25*HCEFF) THEN
      sigma2 = 0.2*exp(1.5*(btm+ZHSUB)/HCEFF)
      tl2 = 0.4*HCEFF
      SIGMA = (SIGMA1+SIGMA2)*USTAR1*PHIW/2.
      TL = ((TL1+TL2)/USTAR1/PHIH/PHIW**2)/2.
      tkcan=sigma*sigma*tl
      RESIST = RESIST + (TOP-BTM)/TKCAN
      go to 10
      else
      BTM = 0.25*HCEFF - ZHSUB
      sigma2 = 0.29
      tl2 = 0.4*HCEFF
      SIGMA = ((SIGMA1+SIGMA2)*USTAR1*PHIW)/2.
      TL = ((TL1+TL2)/USTAR1/PHIH/PHIW**2)/2.
      tkcan=sigma*sigma*tl
      RESIST = RESIST + (TOP-BTM)/TKCAN
      TOP = BTM
      BTM = ZC(NC+1) - ZC(I+1)
      tl1 = tl2
      SIGMA1= SIGMA2
      end if
      sigma2= 0.2*exp(1.5*(BTM+ZHSUB)/HCEFF)
      tl2= 1.6*(BTM+ZHSUB)
      SIGMA = (SIGMA1+SIGMA2)*USTAR1*PHIW/2.
      TL = ((TL1+TL2)/USTAR1/PHIH/PHIW**2)/2.
      tkcan=sigma*sigma*tl
      RESIST = RESIST + (TOP-BTM)/TKCAN
   10 TKCAN = RHOA*CA/RESIST
      IF (TKCAN .LT. TKA/(ZC(I+1)-ZC(I))) TKCAN=TKA/(ZC(I+1)-ZC(I))
      CON(I) = TKCAN
      BTM = ZC(NC+1) - ZC(I+1)
   20 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: STAB
      SUBROUTINE SHP_STAB(ITER, NC, ZCAN, TMPAIR, TMPSFC, WIND, HEIGHT, ZMLOG, ZHLOG, ZCLOG, HFLUX, USTAR, STABLE, PSIM,
     >PSIH, RH, ZERO)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      REAL LF, LS, LV
      DATA HTOLER/ 0.001/
      USTAR=WIND*VONKRM/(ZMLOG + PSIM)
      HFLUX1 = HFLUX
      ZREF=ZERO
      IF (NC .GT. 0) ZREF=ZCAN
      ITER1=0
   10 ITER1=ITER1+1
      STABLE=VONKRM*(HEIGHT-ZERO)*G*HFLUX1 /(RHOA*CA*(TMPAIR+273.16)*USTAR**3)
      IF (STABLE .GE. 0.0) THEN
      IF (STABLE .GT. ZMLOG/9.4) STABLE=ZMLOG/9.4
      PSIH=4.7*STABLE
      PSIM=PSIH
      ELSE
      PSIH=-2.*ALOG((1 + (1-16.*STABLE)**0.5)/2.0)
      PSIM=0.6*PSIH
      IF (PSIM/ZMLOG .LT. -0.50) THEN
      PSIM=-0.50*ZMLOG
      PSIH=PSIM/0.6
      STABLE = -((2.*EXP(-PSIH/2.) - 1)**2 -1)/16.
      END IF
      END IF
      USTAR=WIND*VONKRM/(ZMLOG + PSIM)
      RH=(ZHLOG + PSIH)/(USTAR*VONKRM)
      IF (NC .GT. 0) THEN
      RHZC=RH*(1. - (ZCLOG/ZHLOG))
      HFLUX2=RHOA*CA*(TMPAIR-TMPSFC)/RHZC
      ELSE
      HFLUX2=RHOA*CA*(TMPAIR-TMPSFC)/RH
      END IF
      ERROR=ABS(HFLUX2-HFLUX1)
      HFLUX1=HFLUX2
      IF(ABS(HFLUX1).LT.ABS(TKA*(TMPAIR-TMPSFC)/(HEIGHT-ZREF))) GO TO 15
      IF (ITER1 .GT. 40) THEN
      GO TO 15
      END IF
      IF (ERROR .GT. HTOLER) GO TO 10
   15 HFLUX = HFLUX1
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: EBSNOW
      SUBROUTINE SHP_EBSNOW (N, NSP, NR, ICESPT, TSP, TSPDT, DLW, DLWDT, RHOSP, ZSP, DZSP, QVSP, VAPSP, VAPSPT, SSP,
     >ITER)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_MATRIX/ A1(350), B1(350), C1(350), D1(350), A2(350), B2(350), C2(350), D2(350)
      REAL TSP(200), TSPDT(200), DLW(200), DLWDT(200), RHOSP(200), ZSP(200), DZSP(200), QVSP(200), SSP(200)
      REAL QVSPT(200), QVSPDT(200), TK(200), CON(200), CONV(200), SLOPE(200), CSP(200), CSPT(200), CSPDT(200)
      INTEGER ICESPT(200)
      REAL LF, LS, LV
      COMMON /SHP_SV_EBSNOW/ QVSPT, CON, CSPT
      IF (ITER .EQ. 1) CALL SHP_QVSNOW (NSP, QVSPT, CONV, SLOPE, TSP, ZSP, VAPSP)
      CALL SHP_QVSNOW (NSP, QVSPDT, CONV, SLOPE, TSPDT, ZSP, VAPSPT)
      IF (NR .GT. 0) SLOPE(NSP+1) = 0.0
      CALL SHP_WEIGHT (NSP, QVSP, QVSPT, QVSPDT)
      IF (ITER .EQ. 1) THEN
      CALL SHP_SNOWTK (NSP, TK, RHOSP)
      TK(NSP+1) = TK(NSP)
      NSP1 = NSP+1
      CALL SHP_CONDUC (NSP1, ZSP, TK, CON)
      END IF
      IF (ITER .EQ. 1) CALL SHP_SNOWHT (NSP, CSPT, TSP, RHOSP)
      CALL SHP_SNOWHT (NSP, CSPDT, TSPDT, RHOSP)
      CALL SHP_WEIGHT (NSP, CSP, CSPT, CSPDT)
      D1(N)= D1(N) - CON(1)*(WT*(TSP(1)-TSP(2)) + WDT*(TSPDT(1)-TSPDT(2))) + SSP(1) -
     >CSP(1)*(TSPDT(1)-TSP(1))*DZSP(1)/DT - RHOL*LF*(DLWDT(1)-DLW(1))/DT - LS*QVSP(1)
      IF (ICESPT(1) .EQ. 0) THEN
      A1(N+1) = WDT*(CON(1) + CONV(1)*LS*SLOPE(1))
      B1(N) = B1(N) - WDT*(CON(1) + CONV(1)*LS*SLOPE(1)) - DZSP(1)*CSP(1)/DT
      ELSE
      A1(N+1)= 0.0
      B1(N)= B1(N) - RHOL*LF/DT
      IF (N.GT.1) C1(N-1)=0.0
      END IF
      DO 20 I=N+1, N+NSP-1
      J=I-N+1
      D1(I)= CON(J-1)*(WT*(TSP(J-1)-TSP(J)) + WDT*(TSPDT(J-1)-TSPDT(J))) - CON(J)*(WT*(TSP(J)-TSP(J+1)) +
     >WDT*(TSPDT(J)-TSPDT(J+1))) + SSP(J) - CSP(J)*(TSPDT(J)-TSP(J))*DZSP(J)/DT - RHOL*LF*(DLWDT(J)-DLW(J))/DT -
     >LS*(QVSP(J)-QVSP(J-1))
      IF (ICESPT(J) .EQ. 0) THEN
      A1(I+1)= WDT*(CON(J) + CONV(J)*LS*SLOPE(J))
      B1(I)= -WDT*(CON(J-1)+CON(J)) - WDT*LS*SLOPE(J)*(CONV(J-1) + CONV(J)) - DZSP(J)*CSP(J)/DT
      C1(I-1)= WDT*(CON(J-1) + CONV(J-1)*LS*SLOPE(J))
      ELSE
      A1(I+1)= 0.0
      B1(I)= -RHOL*LF/DT
      C1(I-1)= 0.0
      END IF
   20 CONTINUE
      N=N+NSP
      IF (NR .GT. 0) THEN
      IF (ICESPT(NSP) .EQ. 0) A1(N) = WDT*CON(NSP)
      B1(N) = -WDT*CON(NSP)
      C1(N-1) = C1(N-1) + WDT*CON(NSP)
      D1(N) = CON(NSP)* (WT*(TSP(NSP) - TSP(NSP+1)) + WDT*(TSPDT(NSP) - TSPDT(NSP+1)))
      ELSE
      IF (ICESPT(NSP) .GT. 0) A1(N)=WDT*(CON(NSP)+CONV(NSP)*LV*SLOPE(NSP))
      B1(N) =-WDT*(CON(NSP) + CONV(NSP)*LV*SLOPE(NSP+1))
      C1(N-1) = WDT*(CON(NSP) + CONV(NSP)*LS*SLOPE(NSP+1))
      D1(N) = CON(NSP)* (WT*(TSP(NSP) - TSP(NSP+1)) + WDT*(TSPDT(NSP) - TSPDT(NSP+1))) + LV*QVSP(NSP)
      END IF
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: QVSNOW
      SUBROUTINE SHP_QVSNOW (NSP, QVSP, CONV, SLOPE, TSP, ZSP, VAPSP)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SPPROP/ G1, G2, G3, EXTSP, TKSPA, TKSPB, TKSPEX, VDIFSP, VAPSPX
      REAL QVSP(200), TSP(200), ZSP(200), VAPSNO(200), VAPICE(200), SLOPE(200), CONV(200)
      REAL LF, LS, LV
      DO 10 I=1, NSP
      VAPSNO(I) = VDIFSP*(P0/PRESUR)*(1.+TSP(I)/273.16)**VAPSPX
      CALL SHP_VSLOPE (SLOPE(I), SATV, TSP(I))
      TMP = TSP(I) + 273.16
      HUMID = EXP(0.018/(UGAS*TMP)*LF*TSP(I)/TMP)
      VAPICE(I) = HUMID*SATV
      SLOPE(I) = HUMID*SLOPE(I)
   10 CONTINUE
      VAPICE(NSP+1) = VAPSP
      VAPSNO(NSP+1) = VAPSNO(NSP)
      CALL SHP_VSLOPE (SLOPE(NSP+1), SATV, TSP(NSP+1))
      SLOPE(NSP+1) = SLOPE(NSP+1)*VAPSP/SATV
      NSP1 = NSP+1
      CALL SHP_CONDUC (NSP1, ZSP, VAPSNO, CONV)
      DO 20 I=1, NSP
      QVSP(I) = CONV(I)*(VAPICE(I)-VAPICE(I+1))
   20 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SNOWTK
      SUBROUTINE SHP_SNOWTK (NSP, TK, RHOSP)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SPPROP/ G1, G2, G3, EXTSP, TKSPA, TKSPB, TKSPEX, VDIFSP, VAPSPX
      REAL TK(200), RHOSP(200)
      REAL LF, LS, LV
      DO 10 I=1, NSP
      TK(I) = TKSPA + TKSPB*(RHOSP(I)/RHOL)**TKSPEX
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SNOWHT
      SUBROUTINE SHP_SNOWHT (NSP, CSP, TSP, RHOSP)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      REAL CSP(200), TSP(200), RHOSP(200)
      REAL LF, LS, LV
      DO 10 I=1, NSP
      SPHEAT = 92.96 + 7.37*(TSP(I)+273.16)
      CALL SHP_VSLOPE (S, DUMMY, TSP(I))
      CSP(I) = RHOSP(I)*SPHEAT + (1.-RHOSP(I)/RHOI)*LS*S
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: EBRES
      SUBROUTINE SHP_EBRES (N, NR, NSP, ZR, TR, TRDT, VAPR, VAPRDT, GMC, GMCDT, GMCMAX, RHOR, RESCOF, RESTKB, SR, UR,
     >QVR, RHOSP, ITER)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_MATRIX/ A1(350), B1(350), C1(350), D1(350), A2(350), B2(350), C2(350), D2(350)
      COMMON /SHP_RESIDU/ EVAP(10), EVAPK(10)
      REAL LF, LS, LV
      REAL ZR(10), TR(10), TRDT(10), VAPR(10), VAPRDT(10), GMC(10), GMCDT(10), RHOR(10), SR(10), UR(10), QVR(10),
     >RHOSP(200)
      REAL CRES(10), CREST(10), CRESDT(10), TKRES(10), CONVEC(10), VAPCON(10), CON(10), CONV(10)
      COMMON /SHP_SV_EBRES/ CREST
      CALL SHP_RESVAP (NR, EVAP, EVAPK, ZR, TR, TRDT, VAPR, VAPRDT, GMC, GMCDT, GMCMAX, RHOR, RESCOF, UR)
      CALL SHP_RESTK (NR, NSP, TKRES, CONVEC, TR, TRDT, GMC, GMCDT, RHOR, RESTKB, RHOSP)
      NR1=NR+1
      TKRES(NR1)=TKRES(NR)
      CALL SHP_CONDUC (NR1, ZR, TKRES, CON)
      CALL SHP_RESVK (NR, NSP, TR, TRDT, CONVEC, VAPCON)
      VAPCON(NR1)=VAPCON(NR)
      CALL SHP_CONDUC (NR1, ZR, VAPCON, CONV)
      CALL SHP_QVRES (NR, QVR, CONV, VAPR, VAPRDT)
      IF (ITER .EQ. 1) CALL SHP_RESHT (NR, CREST, GMC, RHOR)
      CALL SHP_RESHT (NR, CRESDT, GMCDT, RHOR)
      CALL SHP_WEIGHT (NR, CRES, CREST, CRESDT)
      A1(N+1)=A1(N+1) + WDT*CON(1)
      C1(N)=C1(N) + WDT*CON(1)
      IF (NR.GT.1) THEN
      B1(N)=B1(N) - WDT*CON(1) - (ZR(2)-ZR(1))/(2*DT)*CRES(1)
      D1(N)=D1(N) - CON(1)*(WT*(TR(1)-TR(2))+WDT*(TRDT(1)-TRDT(2))) + LV*EVAP(1) + SR(1) -
     >(ZR(2)-ZR(1))/(2*DT)*CRES(1)*(TRDT(1)-TR(1))
      ELSE
      B1(N)=B1(N) - WDT*CON(1) - (ZR(2)-ZR(1))/DT*CRES(1)
      D1(N)=D1(N) - CON(1)*(WT*(TR(1)-TR(2))+WDT*(TRDT(1)-TRDT(2))) + LV*EVAP(1) + SR(1) -
     >(ZR(2)-ZR(1))/DT*CRES(1)*(TRDT(1)-TR(1))
      END IF
      DO 10 I=N+1, N+NR-1
      J=I-N+1
      A1(I+1)=A1(I+1) + WDT*CON(J)
      C1(I)=C1(I) + WDT*CON(J)
      IF (J .NE. NR) THEN
      B1(I)=B1(I) - WDT*(CON(J-1)+CON(J)) - (ZR(J+1)-ZR(J-1))/(2*DT)*CRES(J)
      D1(I)=CON(J-1)*(WDT*(TRDT(J-1)-TRDT(J))+WT*(TR(J-1)-TR(J))) -CON(J)*(WDT*(TRDT(J)-TRDT(J+1)) + WT*(TR(J)-TR(J+1)))
     >+LV*EVAP(J) + SR(J) -(ZR(J+1)-ZR(J-1))/(2*DT)*CRES(J)*(TRDT(J)-TR(J))
      ELSE
      B1(I)=B1(I) - WDT*(CON(J-1)+CON(J)) - (ZR(J+1)-ZR(J)+(ZR(J)-ZR(J-1))/2)/DT*CRES(J)
      D1(I)=CON(J-1)*(WDT*(TRDT(J-1)-TRDT(J))+WT*(TR(J-1)-TR(J))) -CON(J)*(WDT*(TRDT(J)-TRDT(J+1)) + WT*(TR(J)-TR(J+1)))
     >+LV*EVAP(J) + SR(J)-(ZR(J+1)-ZR(J)+(ZR(J)-ZR(J-1))/2) /DT*CRES(J)*(TRDT(J)-TR(J))
      END IF
   10 CONTINUE
      N=N+NR
      B1(N)=B1(N) - WDT*CON(NR)
      D1(N)=CON(NR)*(WDT*(TRDT(NR)-TRDT(NR+1))+WT*(TR(NR)-TR(NR+1))) + LV*QVR(NR)
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: RESVAP
      SUBROUTINE SHP_RESVAP (NR, EVAP, EVAPK, ZR, TR, TRDT, VAPR, VAPRDT, GMC, GMCDT, GMCMAX, RHOR, RESCOF, UR)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      REAL EVAP(10), EVAPK(10), ZR(10), TR(10), TRDT(10), VAPR(10), VAPRDT(10), GMC(10), GMCDT(10), RHOR(10), UR(10)
      DO 20 I=1, NR
      CALL SHP_RESHUM (1, HUMT, DUMMY, GMC(I), TR(I))
      CALL SHP_RESHUM (1, HUMDT, DHDW, GMCDT(I), TRDT(I))
      CALL SHP_VSLOPE (DUMMY, SATV, TR(I))
      CALL SHP_VSLOPE (DUMMY, SATVDT, TRDT(I))
      IF (I .EQ. 1) THEN
      DZ=ZR(2)-ZR(1)
      IF (NR .NE. 1) DZ=DZ/2.
      ELSE
      IF (I .EQ. NR) THEN
      DZ=ZR(I+1)-ZR(I)+(ZR(I)-ZR(I-1))/2.
      ELSE
      DZ=(ZR(I+1)-ZR(I-1))/2.
      END IF
      END IF
      EVAPK(I)=1./RESCOF
      EVAP(I)=EVAPK(I)*(WDT*(VAPRDT(I)-HUMDT*SATV) +WT*(VAPR(I)-HUMT*SATV))
      GMCDT(I)= GMC(I) + EVAP(I)*DT/DZ/RHOR(I) + UR(I)
      IF (GMCDT(I) .LT. 0.0) THEN
      GMCDT(I)=0.0
      EVAP(I)= DZ*RHOR(I)*(GMCDT(I)-GMC(I)-UR(I))/DT
      END IF
      IF (GMCDT(I) .GT. GMCMAX) THEN
      GMCDT(I)=GMCMAX
      EVAP(I)= DZ*RHOR(I)*(GMCDT(I)-GMC(I)-UR(I))/DT
      END IF
   20 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: RESHUM
      SUBROUTINE SHP_RESHUM (NCALC, HUM, DHDW, GMC, TR)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_RSPARM/ RESMA, RESMB, RESMC, RESTKA
      REAL LF, LS, LV
      IF (NCALC .EQ. 1) THEN
      IF (GMC .LE. 0.0) THEN
      HUM=0.0
      DHDW=0.0
      ELSE
      HUM=EXP(0.018*G/(UGAS*(TR+273.16))*RESMA*GMC**(-RESMB))
      DHDW=-0.018*G*RESMA*RESMB*HUM*GMC**(-RESMB-1.) /(UGAS*(TR+273.16))
      END IF
      ELSE
      IF (HUM .GT. 0.999) THEN
      GMC=(ALOG(0.999)*UGAS*(TR+273.16)/0.018/G/RESMA)**(-1./RESMB)
      ELSE
      GMC=(ALOG(HUM)*UGAS*(TR+273.16)/0.018/G/RESMA)**(-1./RESMB)
      END IF
      END IF
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: RESTK
      SUBROUTINE SHP_RESTK(NR, NSP, TKRES, CONVEC, TR, TRDT, GMC, GMCDT, RHOR, RESTKB, RHOSP)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_RSPARM/ RESMA, RESMB, RESMC, RESTKA
      COMMON /SHP_WINDV/ ZH, ZM, ZERO, USTAR, STABLE, CONRH, CONRV, ZHLOG, ZMSUB, ZHSUB, ZERSUB, WINDC(11), WINDR(10)
      REAL LF, LS, LV
      REAL TR(10), TRDT(10), GMC(10), GMCDT(10), RHOR(10), RHOSP(200)
      REAL CONVEC(10), TKRES(10), TKSP(200)
      DATA RESDEN/ 170./
      IF (NSP .GT. 0) THEN
      CALL SHP_SNOWTK (NSP, TKSP, RHOSP)
      END IF
      DO 10 I=1, NR
      AVGTMP = WDT*TRDT(I) + WT*TR(I)
      AVGGMC = WDT*GMCDT(I) + WT*GMC(I)
      RESVOL = RHOR(I)/RESDEN
      IF (RESVOL .GT. 1.0) RESVOL = 1.0
      WATER = AVGGMC*RHOR(I)/RHOL
      AIR = 1. - RESVOL - WATER
      IF (AIR .LT. 0.0) AIR = 0.0
      IF (NSP .GT. 0) THEN
      CONVEC(I) = TKSP(NSP)
      ELSE
      CONVEC(I) = TKA*(1.+RESTKA*AVGTMP)*(1.+RESTKB*WINDR(I))
      END IF
      CONVEC(I) = CONVEC(I)*AIR
      TK = WATER*TKL + RESVOL*TKR
      TKRES(I) = CONVEC(I) + TK
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: RESVK
      SUBROUTINE SHP_RESVK (NR, NSP, TR, TRDT, CONVEC, VAPCON)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SPPROP/ G1, G2, G3, EXTSP, TKSPA, TKSPB, TKSPEX, VDIFSP, VAPSPX
      REAL CONVEC(10), VAPCON(10), TR(10), TRDT(10)
      REAL LF, LS, LV
      DO 10 I=1, NR
      VAPCON(I)=CONVEC(I)/RHOA/CA
      IF (NSP .GT. 0) THEN
      AVGTMP = WT*TR(I) + WDT*TRDT(I)
      VAPCON(I) = VDIFSP*(P0/PRESUR)*(1.+AVGTMP/273.16)**VAPSPX
      END IF
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: QVRES
      SUBROUTINE SHP_QVRES (NR, QVR, CONV, VAPR, VAPRDT)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      REAL QVR(10), CONV(10), VAPR(10), VAPRDT(10)
      DO 10 I=1, NR
      QVR(I) = CONV(I)*(WT*(VAPR(I)-VAPR(I+1)) + WDT*(VAPRDT(I)-VAPRDT(I+1)))
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: RESHT
      SUBROUTINE SHP_RESHT (NR, CRES, GMC, RHOR)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      REAL LF, LS, LV
      REAL CRES(10), GMC(10), RHOR(10)
      DO 10 I=1, NR
      CRES(I)=RHOR(I)*(CR + GMC(I)*CL)
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: QVSOIL
      SUBROUTINE SHP_QVSOIL (NS, QSV, ZS, TS, MAT, VLC, VIC, CONC, DCONVP)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      REAL QSV(99), ZS(99), TS(99), MAT(99), VLC(99), VIC(99), CONC(10, 99)
      REAL HUMID(99), DVT(99), DVP(99), CONVT(99), CONVP(99), DCONVP(99)
      REAL LF, LS, LV
      DO 20 I=1, NS
      VAC=1. - RHOB(I)*((1.-OM(I))/RHOM+OM(I)/RHOOM) - VLC(I)- VIC(I)
      IF (MAT(I).LT.SoilWRC(I, 1) .AND. VAC.GT.0.0) THEN
      DV=VDIFF*(((TS(I)+273.16)/273.16)**2)*(P0/PRESUR)
      DV=DV*VAPCOF(I)*(VAC**VAPEXP(I))
      CALL SHP_ENHANC (I, EN, VLC)
      CALL SHP_VSLOPE (S, SATVAP, TS(I))
      TLCONC=0.0
      DO 10 J=1, NSALT
      TLCONC= TLCONC+CONC(J, I)
   10 CONTINUE
      TOTPOT=MAT(I) - TLCONC*UGAS*(TS(I)+273.16)/G
      HUMID(I)=EXP(.018*G/UGAS/(TS(I)+273.16)*TOTPOT)
      DVT(I)=DV*EN*HUMID(I)*S
      DVP(I)=DV*SATVAP
      ELSE
      DVT(I)=0.0
      DVP(I)=0.0
      HUMID(I)=1.0
      END IF
   20 CONTINUE
      CALL SHP_CONDUC (NS, ZS, DVT, CONVT)
      CALL SHP_CONDUC (NS, ZS, DVP, CONVP)
      DO 30 I=1, NS-1
      QSV(I)=CONVT(I)*(TS(I)-TS(I+1))+ CONVP(I)*(HUMID(I)-HUMID(I+1))
      DCONVP(I)=.018*G/UGAS/(TS(I)+273.16)*CONVP(I)
   30 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: ENHANC
      SUBROUTINE SHP_ENHANC (I, EN, VLC)
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      REAL VLC(99)
      DATA EN1/9.5/ EN2/3.0/ EN4/1.0/ EN5/4.0/
      IF (CLAY(I) .LE. 0.02) THEN
      EN3=SoilWRC(I, 2)*(1.+2.6/SQRT(0.02))
      ELSE
      EN3=SoilWRC(I, 2)*(1.+2.6/SQRT(CLAY(I)))
      END IF
      EXPON=-(EN3*VLC(I)/SoilWRC(I, 2))**EN5
      IF (EXPON .LE. -50.) THEN
      EXPON=0.0
      ELSE
      EXPON=EXP(EXPON)
      END IF
      EN = EN1 + EN2*VLC(I)/SoilWRC(I, 2) - (EN1-EN4)*EXPON
      CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: EBSOIL
      SUBROUTINE SHP_EBSOIL (N, NS, ZS, TS, TSDT, MAT, MATDT, CONC, CONCDT, VLC, VLCDT, VIC, VICDT, ICES, ICESDT, QSL,
     >QSV, SS, GFLUX, ITER)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      COMMON /SHP_MATRIX/ A1(350), B1(350), C1(350), D1(350), A2(350), B2(350), C2(350), D2(350)
      COMMON /SHP_SPHEAT/ CS(99)
      REAL ZS(99), TS(99), TSDT(99), MAT(99), MATDT(99), CONC(10, 99), CONCDT(10, 99), VLC(99), VLCDT(99), VIC(99),
     >VICDT(99), QSLT(99), QSLDT(99), QSL(99), QSV(99), SS(99), TK(99), TKT(99), TKDT(99), CON(99), CST(99), CSDT(99),
     >HKT(99), HKDT(99), CONH(99), CONHT(99), QSVT(99), QSVDT(99), DCONVP(99), DELTA(99), EPSLON(99)
      INTEGER ICES(99), ICESDT(99)
      REAL LF, LV, LS
      COMMON /SHP_SV_EBSOIL/ QSVT, QSLT, TKT, CST
      IF (ITER.EQ.1) CALL SHP_QVSOIL (NS, QSVT, ZS, TS, MAT, VLC, VIC, CONC, DCONVP)
      CALL SHP_QVSOIL (NS, QSVDT, ZS, TSDT, MATDT, VLCDT, VICDT, CONCDT, DCONVP)
      CALL SHP_WEIGHT (NS-1, QSV, QSVT, QSVDT)
      IF (ITER .EQ. 1) THEN
      CALL SHP_SOILHK (NS, HKT, MAT, VLC, VIC)
      CALL SHP_CONDUC (NS, ZS, HKT, CONHT)
      CALL SHP_QLSOIL (NS, ZS, QSLT, CONHT, MAT)
      END IF
      CALL SHP_SOILHK (NS, HKDT, MATDT, VLCDT, VICDT)
      CALL SHP_CONDUC (NS, ZS, HKDT, CONH)
      CALL SHP_QLSOIL (NS, ZS, QSLDT, CONH, MATDT)
      CALL SHP_WEIGHT (NS-1, QSL, QSLT, QSLDT)
      IFLAG=0
      DO 5 I=NS-1, 2, -1
      IF (VICDT(I).GT.0.0) THEN
      QMAX=(SoilWRC(I, 2) -VLC(I) -VIC(I))*(ZS(I+1) -ZS(I-1))/2./DT
      IF (QMAX.LT.0.0) QMAX=0.0
      IF (QSL(I-1)-QSL(I) .GT. QMAX) THEN
      IFLAG=1
      IF (QSL(I-1).GT.0.0) THEN
      CONH(I-1)=0.0
      QSL(I-1)=QSL(I)+QMAX
      IF (QSL(I-1).LT.0.0) THEN
      QSL(I-1)=0.0
      QSL(I)=QSL(I-1)-QMAX
      IF (QSL(I).GT.0.0) QSL(I)=0.0
      END IF
      ELSE
      CONH(I)=0.0
      QSL(I)=QSL(I-1)-QMAX
      IF (QSL(I).GT.0.0) QSL(I)=0.0
      END IF
      END IF
      END IF
      IF (QSL(I) .GT. 0.0) THEN
      DELTA(I)=1.0
      EPSLON(I)=0.0
      ELSE
      DELTA(I)=0.0
      EPSLON(I)=-1.0
      END IF
    5 CONTINUE
      IF (QSL(1) .GT. 0.0) THEN
      DELTA(1)=1.0
      EPSLON(1)=0.0
      ELSE
      DELTA(1)=0.0
      EPSLON(1)=-1.0
      END IF
      IF (VICDT(1).GT.0.0) THEN
      QMAX=(SoilWRC(I, 2) - VLC(1) - VIC(1))*(ZS(2) - ZS(1))/2./DT
      IF (QMAX.LT.0.0) QMAX=0.0
      IF (-QSL(1) .GT. QMAX) THEN
      IFLAG=1
      CONH(1)=0.0
      QSL(1)=-QMAX
      END IF
      END IF
      IF (IFLAG.GT.0) THEN
      DO 10 I=2, NS-1
      IF (VICDT(I).GT.0.0) THEN
      QMAX=(SoilWRC(I, 2) -VLC(I) -VIC(I))*(ZS(I+1) -ZS(I-1))/2./DT
      IF (QMAX.LT.0.0) QMAX=0.0
      IF (QSL(I-1)-QSL(I) .GT. QMAX) THEN
      IF (QSL(I).LT.0.0) THEN
      CONH(I)=0.0
      QSL(I)=QSL(I-1)-QMAX
      IF (QSL(I).GT.0.0) THEN
      QSL(I)=0.0
      QSL(I-1)=QSL(I)+QMAX
      IF (QSL(I-1).LT.0.0) QSL(I-1)=0.0
      END IF
      ELSE
      CONH(I-1)=0.0
      QSL(I-1)=QSL(I)+QMAX
      IF (QSL(I-1).LT.0.0) QSL(I-1)=0.0
      END IF
      END IF
      END IF
   10 CONTINUE
      END IF
      IF (ITER .EQ. 1) CALL SHP_SOILTK (NS, TKT, VLC, VIC)
      CALL SHP_SOILTK (NS, TKDT, VLCDT, VICDT)
      CALL SHP_WEIGHT (NS, TK, TKT, TKDT)
      CALL SHP_CONDUC (NS, ZS, TK, CON)
      IF (ITER .EQ. 1) CALL SHP_SOILHT (NS, CST, VLC, VIC, TS, MAT, CONC)
      CALL SHP_SOILHT (NS, CSDT, VLCDT, VICDT, TSDT, MATDT, CONCDT)
      CALL SHP_WEIGHT (NS, CS, CST, CSDT)
      A1(N+1) = WDT*(CON(1) + DELTA(1)*(RHOL*CL*QSL(1)+CV*QSV(1)))
      B1(N) = B1(N)- WDT*(CON(1) + EPSLON(1)*(RHOL*CL*QSL(1)+CV*QSV(1))) - (ZS(2)-ZS(1))*CSDT(1)/(2.*DT)
      C1(N) = WDT*(CON(1) + EPSLON(1)*(RHOL*CL*QSL(1)+CV*QSV(1)))
      D1(N) = D1(N)-(CON(1) + EPSLON(1)*(RHOL*CL*QSL(1)+CV*QSV(1))) *(WT*(TS(1)-TS(2))+ WDT*(TSDT(1)-TSDT(2))) -
     >LV*QSV(1) + SS(1) - (ZS(2)-ZS(1))/(2.*DT) *(CS(1)*(TSDT(1)-TS(1)) - RHOI*LF*(VICDT(1)-VIC(1)))
      GFLUX = (CON(1) + EPSLON(1)*(RHOL*CL*QSL(1)+CV*QSV(1))) *(WT*(TS(1)-TS(2))+ WDT*(TSDT(1)-TSDT(2))) + LV*QSV(1) +
     >(ZS(2)-ZS(1))/(2.*DT) *(CS(1)*(TSDT(1)-TS(1)) - RHOI*LF*(VICDT(1)-VIC(1)))
      IF (ICESDT(1) .NE. 1) GO TO 20
      IF (ICES(1) .EQ. 1) THEN
      T=273.16+TS(1)
      ELSE
      TLCONC=0.0
      DO 15 K=1, NSALT
      TLCONC=TLCONC + CONC(K, 1)
   15 CONTINUE
      TMPFRZ=273.16*LF/G/(LF/G-MAT(1)+TLCONC*UGAS*(TS(1)+273.17)/G)
      T=TMPFRZ
      END IF
      CALL SHP_FSLOPE (1, DLDT, DUMMY, T, MAT, CONC, VLC)
      IF (MATDT(1) .GE. 0.0 .or. MATDT(1) .GT. SoilWRC(1, 1)) then
      TDT=273.159+TSDT(1)
      SAVEMATDT = MATDT(1)
      MATDT(1) = LF*(TDT-273.16)/TDT/G
      CALL SHP_FSLOPE (1, DLDTDT, DUMMY, TDT, MATDT, CONCDT, VLCDT)
      CALL SHP_MATVL3 (1, MATDT(1), VLCDT(1), DLDM)
      MATDT(1) = SAVEMATDT
      ELSE
      TDT=273.16+TSDT(1)
      CALL SHP_FSLOPE (1, DLDTDT, DUMMY, TDT, MATDT, CONCDT, VLCDT)
      CALL SHP_MATVL3 (1, MATDT(1), VLCDT(1), DLDM)
      END IF
      B1(N)=B1(N) - (ZS(2)-ZS(1))/(2.*DT)* 0.5*RHOL*LF*(DLDT+DLDTDT) - WDT*RHOL*LF*CONH(1)*DLDTDT/DLDM
   20 DO 30 I=N+1, N+NS-2
      J=I-N+1
      A1(I+1)=WDT*(CON(J) + DELTA(J)*(RHOL*CL*QSL(J)+CV*QSV(J)))
      B1(I)= -WDT*(CON(J-1)+CON(J) +(DELTA(J-1)*(RHOL*CL*QSL(J-1)+CV*(QSV(J-1))) +
     >EPSLON(J)*(RHOL*CL*QSL(J)+CV*QSV(J)))) - (ZS(J+1)-ZS(J-1))*CSDT(J)/(2.*DT)
      C1(I)=WDT*(CON(J) + EPSLON(J)*(RHOL*CL*QSL(J)+CV*QSV(J)))
      D1(I)=(CON(J-1) + DELTA(J-1)*(RHOL*CL*QSL(J-1) + CV*QSV(J-1))) *(WT*(TS(J-1)-TS(J)) + WDT*(TSDT(J-1)-TSDT(J)))
     >-(CON(J) + EPSLON(J)*(RHOL*CL*QSL(J) + CV*QSV(J))) *(WT*(TS(J)-TS(J+1)) + WDT*(TSDT(J)-TSDT(J+1)))
     >-LV*(QSV(J)-QSV(J-1)) + SS(J) -(ZS(J+1)-ZS(J-1))/(2.*DT) *(CS(J)*(TSDT(J)-TS(J)) - RHOI*LF*(VICDT(J)-VIC(J)))
      IF (ICESDT(J) .NE. 1) GO TO 30
      IF (ICES(J) .EQ. 1) THEN
      T=273.16+TS(J)
      ELSE
      TLCONC=0.0
      DO 25 K=1, NSALT
      TLCONC=TLCONC + CONC(K, J)
   25 CONTINUE
      TMPFRZ=273.16*LF/G /(LF/G-MAT(J)+TLCONC*UGAS*(TS(J)+273.16)/G)
      T=TMPFRZ
      END IF
      CALL SHP_FSLOPE (J, DLDT, DUMMY, T, MAT, CONC, VLC)
      IF (MATDT(J) .GE. 0.0 .or. MATDT(J) .GT. SoilWRC(J, 1)) then
      TDT=273.159+TSDT(J)
      SAVEMATDT = MATDT(J)
      MATDT(J) = LF*(TDT-273.16)/TDT/G
      CALL SHP_FSLOPE (J, DLDTDT, DUMMY, TDT, MATDT, CONCDT, VLCDT)
      CALL SHP_MATVL3 (J, MATDT(J), VLCDT(J), DLDM)
      MATDT(J) = SAVEMATDT
      ELSE
      TDT=273.16+TSDT(J)
      CALL SHP_FSLOPE (J, DLDTDT, DUMMY, TDT, MATDT, CONCDT, VLCDT)
      CALL SHP_MATVL3 (J, MATDT(J), VLCDT(J), DLDM)
      END IF
      B1(I)=B1(I) - (ZS(J+1)-ZS(J-1))/(2.*DT) *0.5*RHOL*LF*(DLDT+DLDTDT) - WDT*RHOL*LF*(CONH(J-1)+CONH(J))*DLDTDT/DLDM
   30 CONTINUE
      N=N+NS-2
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SOILTK
      SUBROUTINE SHP_SOILTK (NS, TK, VLC, VIC)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      REAL TK(99), VLC(99), VIC(99)
      REAL LF, LV, LS
      COMMON /SHP_SV_SOILTK/ IFIRST, WFAIRD, WFROD, WFSAD, WFSID, WFCLD, WFOMD, WFICED, TKMA, WFL, WFRO, WFSA, WFSI,
     >WFCL, WFOM, WFICE
      DATA GAOM, GARO, GASA, GASI, GAC /0.5, 0.333, 0.144, 0.144, 0.125/
C     Mutable SAVE initialization moved to SHP_SAVE_INITIAL_VALUES.
      DeVWF(TK0, TK1, GA) = 2.0/3.0/(1.0+(TK1/TK0-1.0)*GA) + 1.0/3.0/(1.0+(TK1/TK0-1.0)*(1.0-2.0*GA))
      IF (IFIRST .EQ. 0) THEN
      WFAIRD = 1.0
      WFROD = DeVWF(TKA, TKRO, GARO)
      WFSAD = DeVWF(TKA, TKSA, GASA)
      WFSID = DeVWF(TKA, TKSI, GASI)
      WFCLD = DeVWF(TKA, TKCL, GAC)
      WFOMD = DeVWF(TKA, TKOM, GAOM)
      WFICED = 1.0
      TKMA = TKA
      WFL = 1.0
      WFRO = DeVWF(TKL, TKRO, GARO)
      WFSA = DeVWF(TKL, TKSA, GASA)
      WFSI = DeVWF(TKL, TKSI, GASI)
      WFCL = DeVWF(TKL, TKCL, GAC)
      WFOM = DeVWF(TKL, TKOM, GAOM)
      WFICE = 1.0
      IFIRST=1
      END IF
      DO 10 I=1, NS
      XSM = 1.0 - OM(I) - ROCK(I)
      XSAND=XSM*SAND(I)
      XSILT=XSM*SILT(I)
      XCLAY=XSM*CLAY(I)
      VROCK = ROCK(I)*RHOB(I)/RHOM
      VSAND = XSAND*RHOB(I)/RHOM
      VSILT = XSILT*RHOB(I)/RHOM
      VCLAY = XCLAY*RHOB(I)/RHOM
      VOM = OM(I)*RHOB(I)/RHOOM
      PORO = 1.-VROCK-VSAND-VSILT-VCLAY-VOM
      VAC = PORO-VIC(I)-VLC(I)
      IF (VAC .LT. 0.0) VAC=0.0
      VLMT = 0.10 + 0.2*CLAY(I) - 0.1*SAND(I)
      IF (VLMT .LT. 0.05) VLMT = 0.05
      IF (VLMT .GT. 0.15) VLMT = 0.15
      IF (VLC(I) .GT. VLMT) THEN
      GAAIR = 0.035+0.298*(VLC(I)-VLMT)/(PORO-VLMT)
      WFAIR= DeVWF(TKL, TKMA, GAAIR)
      TK(I)=(WFRO*VROCK*TKRO + WFSA*VSAND*TKSA + WFL*VLC(I)*TKL + WFICE*VIC(I)*TKI + WFAIR*VAC*TKMA + WFSI*VSILT*TKSI +
     >WFCL*VCLAY*TKCL + WFOM*VOM*TKOM) /(WFRO*VROCK + WFSA*VSAND + WFL*VLC(I) + WFICE*VIC(I) + WFAIR*VAC + WFSI*VSILT +
     >WFCL*VCLAY + WFOM*VOM)
      ELSE
      TK0=1.25*(WFROD*VROCK*TKRO + WFSAD*VSAND*TKSA + WFICED*VIC(I)*TKI + WFAIRD*(VAC+VLC(I))*TKA + WFSID*VSILT*TKSI +
     >WFCLD*VCLAY*TKCL + WFOMD*VOM*TKOM) /(WFROD*VROCK + WFSAD*VSAND + WFICED*VIC(I) + WFAIRD*(VAC+VLC(I)) + WFSID*VSILT
     >+ WFCLD*VCLAY + WFOMD*VOM)
      VAC = PORO-VIC(I)-VLMT
      IF (VAC .LT. 0.0) VAC=0.0
      WFAIR= DeVWF(TKL, TKMA, 0.035)
      TKLMT =(WFRO*VROCK*TKRO + WFSA*VSAND*TKSA + WFL*VLMT*TKL + WFICE*VIC(I)*TKI+ WFAIR*VAC*TKMA + WFSI*VSILT*TKSI +
     >WFCL*VCLAY*TKCL + WFOM*VOM*TKOM) /(WFRO*VROCK + WFSA*VSAND + WFL*VLMT + WFICE*VIC(I) + WFAIR*VAC + WFSI*VSILT +
     >WFCL*VCLAY + WFOM*VOM)
      TK(I) = TK0 + (TKLMT-TK0)*VLC(I)/VLMT
      ENDIF
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SOILHT
      SUBROUTINE SHP_SOILHT (NS, CS, VLC, VIC, TS, MAT, CONC)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      REAL LF, LV, LS
      REAL CS(99), VLC(99), VIC(99), TS(99), MAT(99), CONC(10, 99)
      DO 20 I=1, NS
      XSM = 1.0 - OM(I)
      VAC = 1. -XSM*RHOB(I)/RHOM -OM(I)*RHOB(I)/RHOOM -VLC(I) -VIC(I)
      IF (VAC .LT. 0.0) VAC=0.0
      CS(I)=XSM*RHOB(I)*CM + OM(I)*RHOB(I)*COM + VLC(I)*RHOL*CL + VIC(I)*RHOI*CI + VAC*RHOA*CA
      IF (MAT(I).LT.SoilWRC(I, 1) .AND. VAC.GT.0.0) THEN
      TLCONC=0.0
      DO 10 J=1, NSALT
      TLCONC= TLCONC+CONC(J, I)
   10 CONTINUE
      TOTPOT=MAT(I) - TLCONC*UGAS*TS(I)/G
      HUMID=EXP(.018*G/UGAS/(TS(I)+273.16)*TOTPOT)
      CALL SHP_VSLOPE (S, RHOV, TS(I))
      CS(I)=CS(I)+VAC*LV*HUMID*S
      END IF
   20 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: FSLOPE
      SUBROUTINE SHP_FSLOPE(I, DLDT, PTDLDT, TMP, MAT, CONC, VLC)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      REAL MAT(99), CONC(10, 99), VLC(99)
      REAL LF, LS, LV
      CNCGAS=0.0
      CRT=0.0
      DO 10 J=1, NSALT
      DKQ=SALTKQ(J, I) + VLC(I)*RHOL/RHOB(I)
      CNCGAS=CNCGAS + CONC(J, I)*UGAS
      CRT=CRT + CONC(J, I)*UGAS*TMP*RHOL/RHOB(I)/DKQ
   10 CONTINUE
      CALL SHP_MATVL3 (I, MAT(I), VLC(I), DLDM)
      IF (DLDM .GT. 0.0) THEN
      DLDT=(LF/TMP + CNCGAS)/(G/DLDM + CRT)
      ELSE
      DLDT=0.0
      END IF
      CRKQ=0.0
      DO 20 J=1, NSALT
      DKQ=SALTKQ(J, I) + VLC(I)*RHOL/RHOB(I)
      CRKQ=CRKQ + CONC(J, I)*UGAS/DKQ*(1.-2.*TMP*(RHOL/RHOB(I))*DLDT/DKQ)
   20 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: FROZEN
      SUBROUTINE SHP_FROZEN (I, VLC, VIC, MAT, CONC, TS, SALT, ICES)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      REAL VLC(99), VIC(99), MAT(99), CONC(10, 99), TS(99), SALT(10, 99)
      INTEGER ICES(99)
      REAL LF, LS, LV
      REAL MAT1
      IF (TS(I) .GE. 0.0) THEN
      VLC2 = SoilWRC(I, 2)
      GO TO 30
      END IF
      ICONV=0
    5 TMP=TS(I)+273.16
      TOTPOT = LF*TS(I)/TMP/G
      CALL SHP_MATVL2 (I, TOTPOT, VLC1, DUMMY)
      ITER=0
   10 OSMPOT=0.0
      DERIV=0.0
      DO 20 J=1, NSALT
      TERM = SALT(J, I)*UGAS*TMP/(SALTKQ(J, I)+VLC1*RHOL/RHOB(I))
      OSMPOT= OSMPOT-TERM
      DERIV= DERIV+TERM*RHOL/RHOB(I)/(SALTKQ(J, I)+VLC1*RHOL/RHOB(I))
   20 CONTINUE
      OSMPOT= OSMPOT/G
      DERIV= DERIV/G
      IF (VLC1 .LE. SOILWRC(I, 4)) VLC1 = VLC1 + 10.E-7
      CALL SHP_MATVL1 (I, MAT1, VLC1, DUMMY)
      CALL SHP_MATVL3 (I, MAT1, VLC1, DLDM)
      if (dldm .eq. 0.0) then
      CALL SHP_MATVL3 (I, totpot, VLC1, DLDM)
      end if
      ERROR = TOTPOT - OSMPOT - MAT1
      DELTA = ERROR/(DERIV + 1/DLDM)
      VLC2 = VLC1 + DELTA
      IF (VLC2 .GT. SoilWRC(I, 2)) VLC2=SoilWRC(I, 2)
      IF (VLC2 .LE. (VLC1+SOILWRC(I, 4))/2.) VLC2=(VLC1+SOILWRC(I, 4))/2.
      DELTA = VLC2 - VLC1
      VLC1=VLC2
      IF (ABS(DELTA) .LT. .00001) GO TO 30
      ITER=ITER+1
      IF (ICONV .GT. 0) WRITE (6, *) ITER, OSMPOT, MAT1, VLC1, DERIV, 1/DLDM, ERROR
      IF (ITER .GT. 30) THEN
      ICONV = ICONV+1
      WRITE (6, 100)
      WRITE (6, *) I, TS(I), VLC(I), VIC(I), TOTPOT
      IF (ICONV .EQ. 1) GO TO 5
      WRITE (6, 100)
      WRITE (6, *)
      WRITE (6, *) ' ===> Simulation aborted; Press Enter to end'
      CONTINUE
      STOP 71
      END IF
      GO TO 10
   30 IF ((VLC(I)+VIC(I)*RHOI/RHOL).LT.VLC2) THEN
      ICES(I)=0
      VLC(I)=VLC(I) + VIC(I)*RHOI/RHOL
      VIC(I)=0.0
      IF (VLC(I) .GT. SOILWRC(I, 4)) THEN
      CALL SHP_MATVL1 (I, MAT(I), VLC(I), DUMMY)
      ELSE
      END IF
      ELSE
      VIC(I)=VIC(I)+(VLC(I)-VLC2)*RHOL/RHOI
      VLC(I)=VLC2
      IF (VIC(I) .GT. 0.0) THEN
      ICES(I)=1
      IF (VLC1 .GT. SOILWRC(I, 4)) THEN
      CALL SHP_MATVL1 (I, MAT(I), VLC(I), DUMMY)
      IF (MAT(I)+OSMPOT .GE. 0.0) THEN
      MAT(I) = TOTPOT - OSMPOT
      IF (MAT(I) .GE. 0.0) MAT(I) = 0.0
      END IF
      ELSE
      MAT(I) = TOTPOT - OSMPOT
      END IF
      ELSE
      VIC(I)=0.0
      ICES(I)=0
      END IF
      END IF
      DO 40 J=1, NSALT
      CONC(J, I)=SALT(J, I)/(SALTKQ(J, I) + VLC(I)*RHOL/RHOB(I))
   40 CONTINUE
      RETURN
  100 FORMAT (//, '*****  PROGRAM WAS STOPPED IN SUBROUTINE FROZEN DUE  TO CONVERGENCE PROBLEMS *****' )
      END
C     USDA-ARS SHAW 3.0.3: ADJUST
      SUBROUTINE SHP_ADJUST(I, VICDT, VLCDT, MATDT, CONCDT, TSDT, SALTDT, ICESDT)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      COMMON /SHP_SPHEAT/ CS(99)
      REAL VICDT(99), VLCDT(99), MATDT(99), CONCDT(10, 99), TSDT(99), SALTDT(10, 99)
      INTEGER ICESDT(99)
      REAL LF, LS, LV
      VLCDT(I)=VLCDT(I) + (RHOI/RHOL)*VICDT(I)
      CALL SHP_MATVL1 (I, MATDT(I), VLCDT(I), DUMMY)
      DO 5 J=1, NSALT
      CONCDT(J, I)=SALTDT(J, I)/(SALTKQ(J, I) + VLCDT(I)*RHOL/RHOB(I))
    5 CONTINUE
      VICDT(I)=0.0
      TLCONC=0.0
      DO 10 J=1, NSALT
      TLCONC= TLCONC+CONCDT(J, I)
   10 CONTINUE
      TOTPOT=MATDT(I) - TLCONC*UGAS*273.16/G
      TMPFRZ=273.16*TOTPOT/(LF/G-TOTPOT)
      TMPF=TMPFRZ+273.16
      ENERGY=CS(I)*(TMPFRZ-TSDT(I))
      CALL SHP_FSLOPE (I, DLDT, DUMMY, TMPF, MATDT, CONCDT, VLCDT)
      EFFCS=CS(I)+RHOL*LF*DLDT
      TSDT(I)=TMPFRZ - ENERGY/EFFCS
      CALL SHP_FROZEN (I, VLCDT, VICDT, MATDT, CONCDT, TSDT, SALTDT, ICESDT)
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: WBCAN
      SUBROUTINE SHP_WBCAN (N, NPLANT, NC, NSP, NR, NS, ZC, TC, TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN, WCANDT, PCAN,
     >PCANDT, QVC, TRNSP, MAT, MATDT, XTRACT, SWCAN, LWCAN, SWDOWN, CANMA, CANMB, DCHAR, RSTOM0, RSTEXP, PLEAF0, RLEAF0,
     >ITYPE, ISTOMATE, STOMATE, ICESDT, ITER)
      COMMON /SHP_OPTIONS/ SHP_CANOPY_WATER_TOL, SHP_CANOPY_JACOBIAN
      REAL SHP_CANOPY_WATER_TOL
      INTEGER SHP_CANOPY_JACOBIAN
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_MATRIX/ A1(350), B1(350), C1(350), D1(350), A2(350), B2(350), C2(350), D2(350)
      COMMON /SHP_WRITEIT/ hflux1, rh, hnc, xlenc, contk, tleaf(8, 10)
      REAL LF, LS, LV
      REAL ZC(11), TC(11), TCDT(11), TLC(8, 10), TLCDT(8, 10), VAPC(11), VAPCDT(11), WCAN(10), WCANDT(10), PCAN(8),
     >PCANDT(8), QVC(10), TRNSP(9), MAT(99), MATDT(99), XTRACT(99), SWCAN(9, 10), LWCAN(9, 10), SWDOWN(11)
      REAL DCHAR(8), RSTOM0(8), RSTEXP(8), PLEAF0(8), RLEAF0(8), STOMATE(8, 10)
      REAL CON(10), HEATC(10), ETLYR(10), DETLYR(10), DHEATC(10), DTLDTC(10)
      INTEGER ITYPE(8)
      CALL SHP_LEAFT (NPLANT, NC, NS, ITER, ITYPE, TC, TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN, WCANDT, PCAN, PCANDT, MAT,
     >MATDT, TRNSP, XTRACT, SWCAN, LWCAN, SWDOWN, HEATC, ETLYR, DETLYR, CANMA, CANMB, DCHAR, RSTOM0, RSTEXP, PLEAF0,
     >RLEAF0, ISTOMATE, STOMATE, DHEATC, DTLDTC)
      CALL SHP_CANTK (ITER, NC, CON, TCDT, ZC)
      DO 5 I=1, NC-1
      CON(I)=CON(I)/RHOA/CA
      QVC(I)=CON(I)*(VAPCDT(I)-VAPCDT(I+1))
    5 CONTINUE
      CON(NC)=CON(NC)/RHOA/CA
      QVC(NC)=CON(NC)*(WDT*(VAPCDT(NC)-VAPCDT(NC+1)) + WT*(VAPCDT(NC)-VAPC(NC+1)))
      A2(N+1)=CON(1)
C     Optional canopy storage Jacobian correction; residual volume is unchanged.
      IF (SHP_CANOPY_JACOBIAN .NE. 0 .AND. NC .EQ. 1) THEN
      B2(N)=B2(N)-(CON(1)+DETLYR(1))-(ZC(2)-ZC(1))/DT
      ELSE
      B2(N)=B2(N) - (CON(1) + DETLYR(1)) - (ZC(2)-ZC(1))/2/DT
      END IF
      IF (NC .EQ. 1) THEN
      C2(N)=WDT*CON(1)
      D2(N)=D2(N)-QVC(1)+ETLYR(1)-(ZC(2)-ZC(1)) *(VAPCDT(1)-VAPC(1))/DT
      ELSE
      C2(N)=CON(1)
      D2(N)=D2(N)-QVC(1)+ETLYR(1)-(ZC(2)-ZC(1))/2 *(VAPCDT(1)-VAPC(1))/DT
      END IF
      DO 10 I=N+1, N+NC-1
      J=I-N+1
      A2(I+1)=CON(J)
C     Optional canopy storage Jacobian correction; residual volume is unchanged.
      IF (SHP_CANOPY_JACOBIAN .NE. 0 .AND. J .EQ. NC) THEN
      B2(I)=-(CON(J-1)+CON(J)+DETLYR(J))-(ZC(J+1)-ZC(J)+(ZC(J)-ZC(J-1))/2.)/DT
      ELSE
      B2(I)=-(CON(J-1) + CON(J) + DETLYR(J)) - (ZC(J+1)-ZC(J-1))/2/DT
      END IF
      IF (J .EQ. NC) THEN
      C2(I)=WDT*CON(J)
      D2(I)=QVC(J-1) - QVC(J) + ETLYR(J) -(ZC(J+1)-ZC(J)+(ZC(J)-ZC(J-1))/2.)/DT*(VAPCDT(J)-VAPC(J))
      ELSE
      C2(I)=CON(J)
      D2(I)=QVC(J-1) - QVC(J) + ETLYR(J) - (ZC(J+1)-ZC(J-1))/2./DT*(VAPCDT(J)-VAPC(J))
      END IF
   10 CONTINUE
      N=N+NC
      IF (NSP.GT.0) THEN
      A2(N) = 0.0
      B2(N) = 0.0
      C2(N-1)=0.0
      D2(N) = 0.0
      ELSE
      IF (NR.GT.0) THEN
      B2(N) = -WDT*CON(NC)
      D2(N) = QVC(NC)
      ELSE
      A2(N) = A2(N)/RHOL
      IF (ICESDT .EQ. 0) THEN
      B2(N) = -WDT*CON(NC)*VAPCDT(NC+1)*0.018*G /(UGAS*(TCDT(NC+1)+273.16)*RHOL)
      C2(N-1)=C2(N-1)*VAPCDT(NC+1)*0.018*G/(UGAS*(TCDT(NC+1)+273.16))
      ELSE
      B2(N)=0.0
      C2(N-1)=0.0
      END IF
      D2(N) = QVC(NC)/RHOL
      END IF
      END IF
      if (nsp .gt. 0) then
      xlenc = LS*qvc(nc)
      else
      xlenc = LV*qvc(nc)
      end if
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SNOWBC
      SUBROUTINE SHP_SNOWBC (N, NSP, NR, ZSP, QVSP, VAPSPT, TSDT, TSPDT, ICESDT)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_MATRIX/ A1(350), B1(350), C1(350), D1(350), A2(350), B2(350), C2(350), D2(350)
      COMMON /SHP_SPPROP/ G1, G2, G3, EXTSP, TKSPA, TKSPB, TKSPEX, VDIFSP, VAPSPX
      REAL LF, LS, LV
      REAL ZSP(200), QVSP(200), TSPDT(200), TSDT(99)
      VDIF= VDIFSP*(P0/PRESUR)*(1.+TSPDT(NSP)/273.16)**VAPSPX
      CON = VDIF/(ZSP(NSP+1)-ZSP(NSP))
      IF (NR .GT. 0) THEN
      B2(N) = -WDT*CON
      D2(N) = QVSP(NSP)
      ELSE
      IF (ICESDT .EQ. 0) THEN
      B2(N) = -WDT*CON*VAPSPT*0.018*G/(UGAS*(TSDT(1)+273.16))/RHOL
      ELSE
      B2(N) = 0.0
      END IF
      D2(N) = QVSP(NSP)/RHOL
      END IF
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: WBRES
      SUBROUTINE SHP_WBRES (N, NR, NSP, ZR, TR, TRDT, VAPR, VAPRDT, GMC, GMCDT, RHOR, RESTKB, QVR, RHOSP, ICESDT, ITER)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_MATRIX/ A1(350), B1(350), C1(350), D1(350), A2(350), B2(350), C2(350), D2(350)
      COMMON /SHP_RESIDU/ EVAP(10), EVAPK(10)
      REAL LF, LS, LV
      REAL ZR(10), TR(10), TRDT(10), VAPR(10), VAPRDT(10), GMC(10), GMCDT(10), RHOR(10), QVR(10), RHOSP(200), CONV(10),
     >VAPCON(10), CONVEC(10), TKRES(10)
      CALL SHP_RESTK (NR, NSP, TKRES, CONVEC, TR, TRDT, GMC, GMCDT, RHOR, RESTKB, RHOSP)
      CALL SHP_RESVK (NR, NSP, TR, TRDT, CONVEC, VAPCON)
      NR1=NR+1
      VAPCON(NR1)=VAPCON(NR)
      CALL SHP_CONDUC (NR1, ZR, VAPCON, CONV)
      CALL SHP_QVRES (NR, QVR, CONV, VAPR, VAPRDT)
      C2(N)=WDT*CONV(1)
      IF (NR.GT.1) THEN
      B2(N)=B2(N) - WDT*(CONV(1) + EVAPK(1)) - (ZR(2)-ZR(1))/(2*DT)
      D2(N)= D2(N) - QVR(1)- EVAP(1) - (ZR(2)-ZR(1))/(2*DT)*(VAPRDT(1)-VAPR(1))
      ELSE
      B2(N)=B2(N) - WDT*(CONV(1) + EVAPK(1)) - (ZR(2)-ZR(1))/DT
      D2(N)= D2(N) - QVR(1)- EVAP(1) - (ZR(2)-ZR(1))/DT*(VAPRDT(1)-VAPR(1))
      END IF
      DO 10 I=N+1, N+NR-1
      J=I-N+1
      A2(I)=WDT*CONV(J-1)
      C2(I)=WDT*CONV(J)
      IF (J .NE. NR) THEN
      B2(I)=-WDT*(CONV(J-1)+CONV(J)+EVAPK(J)) - (ZR(J+1)-ZR(J-1))/2./DT
      D2(I)= QVR(J-1) - QVR(J) - EVAP(J) - (ZR(J+1)-ZR(J-1))/(2*DT)*(VAPRDT(J)-VAPR(J))
      ELSE
      B2(I)=-WDT*(CONV(J-1)+CONV(J)+EVAPK(J)) - (ZR(J+1)-ZR(J)+(ZR(J)-ZR(J-1))/2)/DT
      D2(I)= QVR(J-1) - QVR(J) - EVAP(J) - (ZR(J+1)-ZR(J)+(ZR(J)-ZR(J-1))/2)/DT*(VAPRDT(J)-VAPR(J))
      END IF
   10 CONTINUE
      N=N+NR
      A2(N)=WDT*CONV(NR)/RHOL
      IF (ICESDT .EQ. 0) THEN
      B2(N)=-WDT*CONV(NR)*VAPRDT(NR+1) *0.018*G/UGAS/(TRDT(NR+1)+273.16)/RHOL
      C2(N-1)=C2(N-1)*VAPRDT(NR+1)*.018*G/UGAS/(TRDT(NR+1)+273.16)
      ELSE
      B2(N)=0.0
      C2(N-1)=0.0
      END IF
      D2(N) = QVR(NR)/RHOL
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: WBSOIL
      SUBROUTINE SHP_WBSOIL (N, NS, ZS, TS, TSDT, MAT, MATDT, VLC, VLCDT, VIC, VICDT, CONC, CONCDT, ICESDT, QSL, QSV,
     >XTRACT, SEEP, FLOLAT, US, SLOPE, ITER)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      COMMON /SHP_MATRIX/ A1(350), B1(350), C1(350), D1(350), A2(350), B2(350), C2(350), D2(350)
      REAL LF, LS, LV
      REAL ZS(99), MAT(99), MATDT(99), VLC(99), VLCDT(99), VIC(99), VICDT(99), TS(99), TSDT(99), CONC(10, 99),
     >CONCDT(10, 99), QSL(99), QSLT(99), QSLDT(99), QSV(99), XTRACT(99), FLOLAT(99), US(99), HKT(99), HKDT(99), CON(99),
     >CONT(99), QSVT(99), QSVDT(99), DCONVP(99)
      INTEGER ICESDT(99), NODE(99)
      COMMON /SHP_SV_WBSOIL/ QSLT, QSVT
      IF (N .EQ. 1) A2(N)=0.0
      IF (ITER.EQ.1) CALL SHP_QVSOIL (NS, QSVT, ZS, TS, MAT, VLC, VIC, CONC, DCONVP)
      CALL SHP_QVSOIL (NS, QSVDT, ZS, TSDT, MATDT, VLCDT, VICDT, CONCDT, DCONVP)
      CALL SHP_WEIGHT (NS-1, QSV, QSVT, QSVDT)
      IF (ITER .EQ. 1) THEN
      CALL SHP_SOILHK (NS, HKT, MAT, VLC, VIC)
      CALL SHP_CONDUC (NS, ZS, HKT, CONT)
      CALL SHP_QLSOIL (NS, ZS, QSLT, CONT, MAT)
      END IF
      CALL SHP_SOILHK (NS, HKDT, MATDT, VLCDT, VICDT)
      CALL SHP_CONDUC (NS, ZS, HKDT, CON)
      CALL SHP_QLSOIL (NS, ZS, QSLDT, CON, MATDT)
      CALL SHP_WEIGHT (NS-1, QSL, QSLT, QSLDT)
      IFLAG=0
      DO 5 I=NS-1, 2, -1
      IF (VICDT(I).GT.0.0000) THEN
      QMAX=(SoilWRC(I, 2) -VLC(I) -VIC(I))*(ZS(I+1) -ZS(I-1))/2./DT
      IF (QMAX.LT.0.0) QMAX=0.0
      IF (QSL(I-1)-QSL(I) .GT. QMAX) THEN
      IFLAG=1
      IF (QSL(I-1).GT.0.0) THEN
      CON(I-1)=0.0
      QSL(I-1)=QSL(I)+QMAX
      IF (QSL(I-1).LT.0.0) THEN
      QSL(I-1)=0.0
      QSL(I)=QSL(I-1)-QMAX
      IF (QSL(I).GT.0.0) QSL(I)=0.0
      END IF
      ELSE
      CON(I)=0.0
      QSL(I)=QSL(I-1)-QMAX
      IF (QSL(I).GT.0.0) QSL(I)=0.0
      END IF
      END IF
      END IF
    5 CONTINUE
      IF (VICDT(1).GT.0.0000) THEN
      QMAX=(SoilWRC(I, 2) - VLC(1) - VIC(1))*(ZS(2) - ZS(1))/2./DT
      IF (QMAX.LT.0.0) QMAX=0.0
      IF (-QSL(1) .GT. QMAX) THEN
      IFLAG=1
      CON(1)=0.0
      QSL(1)=-QMAX
      END IF
      END IF
      IF (IFLAG.GT.0) THEN
      DO 10 I=2, NS-1
      IF (VICDT(I).GT.0.0000) THEN
      QMAX=(SoilWRC(I, 2) -VLC(I)- VIC(I))*(ZS(I+1) -ZS(I-1))/2./DT
      IF (QMAX.LT.0.0) QMAX=0.0
      IF (QSL(I-1)-QSL(I) .GT. QMAX) THEN
      IF (QSL(I).LT.0.0) THEN
      CON(I)=0.0
      QSL(I)=QSL(I-1)-QMAX
      IF (QSL(I).GT.0.0) THEN
      QSL(I)=0.0
      QSL(I-1)=QSL(I)+QMAX
      IF (QSL(I-1).LT.0.0) QSL(I-1)=0.0
      END IF
      ELSE
      CON(I-1)=0.0
      QSL(I-1)=QSL(I)+QMAX
      IF (QSL(I-1).LT.0.0) QSL(I-1)=0.0
      END IF
      END IF
      END IF
   10 CONTINUE
      END IF
      ISAT=0
      IF (MATDT(1) .GE. 0.0) THEN
      FLOLAT(1) = SATKLAT(1)*SIN(SLOPE)*(ZS(2)-ZS(1))/2.
      FLOMAX= D2(N) - QSL(1) - QSV(1)/RHOL + US(1) - XTRACT(1)/RHOL
      IF (FLOMAX .LT. 0.0) FLOMAX = 0.0
      IF (FLOLAT(1) .GT. FLOMAX) FLOLAT(1)=FLOMAX
      ELSE
      FLOLAT(1) = 0.0
      END IF
      D2(N)=D2(N) - QSL(1) - QSV(1)/RHOL + US(1) - XTRACT(1)/RHOL - FLOLAT(1) -
     >(ZS(2)-ZS(1))*(VLCDT(1)-VLC(1)+RHOI/RHOL*(VICDT(1)-VIC(1)))/2./DT
      IF (ICESDT(1) .EQ. 1) THEN
      B2(N)=-(ZS(2)-ZS(1))/(2.*DT)*RHOI/RHOL
      A2(N+1)=0.0
      SEEP=0.0
      ELSE
      IF (MATDT(1).LT.0.0 .OR. D2(N).LT.0.0) THEN
      CALL SHP_MATVL3 (1, MATDT(1), VLCDT(1), DLDM)
      IF (MATDT(1) .GT. SoilWRC(1, 1) .OR. MATDT(1) .GE. 0.0) THEN
      IF (-B2(N).LT.CON(1)*1.E-6 .OR. CON(1).LE.0.0) THEN
      ISAT=ISAT+1
      NODE(ISAT)=1
      END IF
      END IF
      B2(N)=B2(N) - WDT*(CON(1)+DCONVP(1)/RHOL) - (ZS(2)-ZS(1))/(2.*DT)*DLDM
      A2(N+1)= WDT*(CON(1)+DCONVP(1)/RHOL)
      SEEP=0.0
      ELSE
      B2(N)=1.0
      A2(N+1)= WDT*CON(1)
      SEEP=D2(N)
      D2(N)=0.0
      END IF
      END IF
      DO 20 I=N+1, N+NS-2
      J=I-N+1
      IF (ICESDT(J) .EQ. 1) THEN
      B2(I)=-(ZS(J+1)-ZS(J-1))/(2.*DT)*RHOI/RHOL
      C2(I-1)=0.0
      A2(I+1)=0.0
      FLOLAT(J) = 0.0
      ELSE
      CALL SHP_MATVL3 (J, MATDT(J), VLCDT(J), DLDM)
      IF (MATDT(J) .GT. SoilWRC(J, 1) .OR. MATDT(J) .GE. 0.0) THEN
      ISAT=ISAT+1
      NODE(ISAT)=J
      FLOLAT(J) = SATKLAT(J)*SIN(SLOPE)*(ZS(J+1)-ZS(J-1))/2.
      FLOMAX = QSL(J-1) - QSL(J) + (QSV(J-1)-QSV(J))/RHOL + US(J)- XTRACT(J)/RHOL - (ZS(J+1)-ZS(J-1))
     >/(2.*DT)*(VLCDT(J)-VLC(J) + RHOI/RHOL*(VICDT(J)-VIC(J)))
      IF (FLOMAX .LT. 0.0) FLOMAX = 0.0
      IF (FLOLAT(J) .GT. FLOMAX) FLOLAT(J)=FLOMAX
      ELSE
      FLOLAT(J) = 0.0
      END IF
      B2(I)= -WDT*(CON(J-1)+CON(J)+(DCONVP(J-1)+DCONVP(J))/RHOL) -(ZS(J+1)-ZS(J-1))/(2.*DT)*DLDM
      C2(I-1)=WDT*(CON(J-1)+DCONVP(J-1)/RHOL)
      A2(I+1)=WDT*(CON(J)+DCONVP(J)/RHOL)
      END IF
      D2(I)= QSL(J-1) - QSL(J) + (QSV(J-1)-QSV(J))/RHOL + US(J) - XTRACT(J)/RHOL - FLOLAT(J) - (ZS(J+1)-ZS(J-1))
     >/(2.*DT)*(VLCDT(J)-VLC(J) + RHOI/RHOL*(VICDT(J)-VIC(J)))
   20 CONTINUE
      IF (SEEP.GT.0.0) THEN
      A2(N)=0.0
      C2(N)=0.0
      END IF
      IF (ISAT .GT. 0) THEN
      JTOP=0
      NODE(ISAT+1)=NS
      DO 30 J=1, ISAT
      I=NODE(J)+N-1
      IF (NODE(J).EQ.1) THEN
      JTOP=NODE(J)
      ELSE
      IF (CON(NODE(J)-1).LE.-B2(I)*1.E-7) JTOP=NODE(J)
      IF (-CON(NODE(J)-1)-B2(I-1).LE.-B2(I)*1.E-7 .AND. JTOP.EQ.0) JTOP=NODE(J)
      END IF
      IF (JTOP.NE.0) THEN
      IF (CON(NODE(J)).LE.-B2(I)*1.E-7) THEN
      ITOP=JTOP+N-1
      IF (IWRC.eq.1.OR.IWRC.eq.2)then
      CLOSE = 1.0001*SoilWRC(JTOP, 1)
      CALL SHP_MATVL3 (JTOP, CLOSE, VLCDT(JTOP), DLDM)
      Else if (IWRC.eq.3 .or. IWRC.eq.4)then
      CLOSVLC= SoilWRC(JTOP, 2)-0.001
      CALL SHP_MATVL1 (JTOP, CLOSE, CLOSVLC, DLDM)
      CALL SHP_MATVL3 (JTOP, CLOSE, CLOSVLC, DLDM)
      END IF
      IF (JTOP.EQ.1) THEN
      B2(ITOP)=B2(ITOP)-(ZS(JTOP+1)-ZS(JTOP))/(2.*DT)*DLDM
      ELSE
      B2(ITOP)=B2(ITOP)-(ZS(JTOP+1)-ZS(JTOP-1))/(2.*DT)*DLDM
      END IF
      JTOP=0
      END IF
      END IF
      IF (NODE(J)+1.NE.NODE(J+1)) JTOP=0
   30 CONTINUE
      END IF
      N=N+NS-2
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SOILHK
      SUBROUTINE SHP_SOILHK (NS, HK, MAT, VLC, VIC)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      REAL HK(99), MAT(99), VLC(99), VIC(99)
      REAL LF, LS, LV
      DO 10 I=1, NS
      IF (IWRC.eq.1)then
      IF (SoilWRC(I, 1) .GT. MAT(I)) THEN
      HK(I)=SATK(I)*(SoilWRC(I, 1)/MAT(I))**(2.+3./SoilWRC(I, 3))
      ELSE
      HK(I)=SATK(I)
      END IF
      Else IF (IWRC.eq.2)then
      IF (SoilWRC(I, 1).GT.MAT(I)) THEN
      HK(I)=SATK(I)*(SoilWRC(I, 1)/MAT(I)) **(SoilWRC(I, 3)*(SoilWRC(I, 5)+2.0)+2.0)
      ELSE
      HK(I)=SATK(I)
      END IF
      Else IF (IWRC.eq.3)then
      IF (SoilWRC(I, 1).GT.MAT(I)) THEN
      AlfaHN=(ABS(SoilWRC(I, 6)*MAT(I)))**SoilWRC(I, 3)
      HK(I)=SATK(I)*(1.0-(1.0 - 1.0/(1.0+AlfaHN))**SoilWRC(I, 7))**2 /(1.0+AlfaHN)**(SoilWRC(I, 5)*SoilWRC(I, 7))
      ELSE
      HK(I)=SATK(I)
      END IF
      Else IF (IWRC.eq.4)then
      IF (SoilWRC(I, 1).GT.MAT(I)) THEN
      Se=(VLC(I)-SOILWRC(I, 4))/(SOILWRC(I, 2)-SOILWRC(I, 4))
      ERFCinv = ALOG((MAT(I)/SOILWRC(I, 5)))/1.4142/SOILWRC(I, 3) + SOILWRC(I, 3)/1.4142
      CALL SHP_INVERFC (1, ERFC, ERFCinv)
      HK(I)=SATK(I)*SQRT(Se)*(0.5*ERFC)**2
      ELSE
      HK(I)=SATK(I)
      END IF
      END IF
      IF (VIC(I) .GT. 0.0) THEN
      POROS = 1. - RHOB(I)*((1.-OM(I))/RHOM+OM(I)/RHOOM)
      IF (POROS-VIC(I) .LT. 0.13) THEN
      HK(I) = 0.0
      ELSE
      FRACT=(POROS-VIC(I)-0.13)/(POROS-0.13)
      HK(I)=FRACT*HK(I)
      END IF
      END IF
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: QLSOIL
      SUBROUTINE SHP_QLSOIL (NS, ZS, QSL, CON, MAT)
      REAL QSL(99), ZS(99), CON(99), MAT(99)
      DO 10 I=1, NS-1
      QSL(I)=CON(I)*(MAT(I)-MAT(I+1)+ZS(I+1)-ZS(I))
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: BACKUP
      SUBROUTINE SHP_BACKUP (NS, NR, NSP, NC, NPLANT, NSALT, ICES, ICESDT, TS, TSDT, MAT, MATDT, CONC, CONCDT, VLC,
     >VLCDT, VIC, VICDT, SALT, SALTDT, TR, TRDT, VAPR, VAPRDT, GMC, GMCDT, TC, TCDT, TLC, TLCDT, VAPC, VAPCDT, WCAN,
     >WCANDT, PCAN, PCANDT, TSP, TSPDT, DLW, DLWDT, ICESP, ICESPT)
      REAL TS(99), TSDT(99), MAT(99), MATDT(99), CONC(10, 99), CONCDT(10, 99), VLC(99), VLCDT(99), VIC(99), VICDT(99),
     >SALT(10, 99), SALTDT(10, 99)
      REAL TR(10), TRDT(10), VAPR(10), VAPRDT(10), GMC(10), GMCDT(10)
      REAL TC(11), TCDT(11), TLC(8, 10), TLCDT(8, 10), VAPC(11), VAPCDT(11), WCAN(10), WCANDT(10), PCAN(8), PCANDT(8)
      REAL TSP(200), TSPDT(200), DLW(200), DLWDT(200)
      INTEGER ICES(99), ICESDT(99), ICESP(200), ICESPT(200)
      DO 15 I=1, NS
      TSDT(I)=TS(I)
      MATDT(I)=MAT(I)
      VLCDT(I)=VLC(I)
      VICDT(I)=VIC(I)
      ICESDT(I)=ICES(I)
      DO 10 J=1, NSALT
      SALTDT(J, I)=SALT(J, I)
      CONCDT(J, I)=CONC(J, I)
   10 CONTINUE
   15 CONTINUE
      DO 20 I=1, NR
      TRDT(I)=TR(I)
      VAPRDT(I)=VAPR(I)
      GMCDT(I)=GMC(I)
   20 CONTINUE
      DO 30 I=1, NSP
      ICESPT(I) = ICESP(I)
      TSPDT(I) = TSP(I)
      DLWDT(I) = DLW(I)
   30 CONTINUE
      DO 40 I=1, NC
      TCDT(I)=TC(I)
      VAPCDT(I)=VAPC(I)
      WCANDT(I)=WCAN(I)
      DO 35 J=1, NPLANT
      TLCDT(J, I)=TLC(J, I)
   35 CONTINUE
   40 CONTINUE
      IF (NC .GT. 0) THEN
      DO 45 J=1, NPLANT
      PCANDT(J)=PCAN(J)
   45 CONTINUE
      END IF
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SUMDT
      SUBROUTINE SHP_SUMDT (NC, NPLANT, NSP, NR, NS, HFLUX, VFLUX, GFLUX, LWCAN, LWSNOW, LWRES, LWSOIL, LWDOWN, LWUP,
     >SWCAN, SWSNOW, SWRES, SWSOIL, SWDOWN, SWUP, QVC, QVR, QVSP, QSL, QSV, TRNSP, XTRACT, US, FLOLAT, SEEP, TSWSNO,
     >TLWSNO, TSWCAN, TLWCAN, TSWRES, TLWRES, TSWSOI, TLWSOI, TSWDWN, TLWDWN, TSWUP, TLWUP, THFLUX, TGFLUX, EVAP1,
     >ETSUM, TSEEP, ROOTXT, TOTFLO, TOTSINK, TOTLAT, NTIMES, TOPSNO, TQVSP)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      REAL LWCAN(9, 10), LWSNOW, LWRES(10), LWSOIL, LWDOWN(11), LWUP(11), SWCAN(9, 10), SWSNOW(200), SWRES(10),
     >SWDOWN(11), SWUP(11)
      REAL QVC(10), QVR(10), QVSP(200), QSL(99), QSV(99), TRNSP(9), XTRACT(99), ROOTXT(99), US(99), FLOLAT(99),
     >TOTFLO(99), TOTSINK(99), TOTLAT(99), TQVSP(200), TRANSP(8)
      REAL LF, LS, LV
      COMMON /SHP_SV_SUMDT/ TRANSP
      IF (NTIMES .EQ. 1) THEN
      TSWCAN=0.0
      TLWCAN=0.0
      TSWSNO=0.0
      TLWSNO=0.0
      TSWRES=0.0
      TLWRES=0.0
      TSWSOI=0.0
      TLWSOI=0.0
      TSWDWN=0.0
      TLWDWN=0.0
      TSWUP =0.0
      TLWUP =0.0
      THFLUX=0.0
      TGFLUX=0.0
      EVAP1=0.0
      ETSUM=0.0
      TSEEP=0.0
      TOPSNO=0.0
      DO 6 J=1, NPLANT
      TRANSP(J)=0.0
    6 CONTINUE
      DO 8 I=1, NSP
      TQVSP(I)=0.0
    8 CONTINUE
      DO 10 I=1, NS
      TOTFLO(I)=0.0
      TOTSINK(I)=0.0
      TOTLAT(I)=0.0
      ROOTXT(I)=0.0
   10 CONTINUE
      END IF
      TSWDWN = TSWDWN + SWDOWN(1)*DT/1000.
      TLWDWN = TLWDWN + LWDOWN(1)*DT/1000.
      TSWUP = TSWUP + SWUP(1)*DT/1000.
      TLWUP = TLWUP + LWUP(1)*DT/1000.
      DO 20 I=1, NC
      TSWCAN = TSWCAN + SWCAN(NPLANT+1, I)*DT/1000.
      TLWCAN = TLWCAN + LWCAN(NPLANT+1, I)*DT/1000.
   20 CONTINUE
      DO 30 I=1, NSP
      TSWSNO = TSWSNO + SWSNOW(I)*DT/1000.
   30 CONTINUE
      IF (NSP .GT. 0) TLWSNO = TLWSNO + LWSNOW*DT/1000.
      DO 40 I=1, NR
      TSWRES = TSWRES + SWRES(I)*DT/1000.
      TLWRES = TLWRES + LWRES(I)*DT/1000.
   40 CONTINUE
      TSWSOI = TSWSOI + SWSOIL*DT/1000.
      TLWSOI = TLWSOI + LWSOIL*DT/1000.
      THFLUX = THFLUX + HFLUX*DT/1000.
      TGFLUX = TGFLUX + GFLUX*DT/1000.
      EVAP1 = EVAP1 + VFLUX/RHOL*DT
      DO 50 J=1, NPLANT
      TRANSP(J)=TRANSP(J) + TRNSP(J)*DT
   50 CONTINUE
      ETSUM = ETSUM + TRNSP(NPLANT+1)/RHOL*DT
      IF (NSP .GT. 0) THEN
      IF (NC .GT. 0) THEN
      TOPSNO = TOPSNO + QVC(NC)*DT
      ELSE
      TOPSNO = TOPSNO + VFLUX*DT
      END IF
      DO 60 I=1, NSP
      TQVSP(I) = TQVSP(I) + QVSP(I)*DT
   60 CONTINUE
      END IF
      IF (NPLANT .GT. 0) THEN
      DO 70 I=1, NS
      ROOTXT(I)=ROOTXT(I)+XTRACT(I)*DT
   70 CONTINUE
      END IF
      DO 80 I=1, NS-1
      TOTFLO(I)=TOTFLO(I) + (QSL(I) + QSV(I)/RHOL)*DT
   80 CONTINUE
      DO 90 I=1, NS-1
      TOTSINK(I)=TOTSINK(I) - US(I)*DT
      TOTLAT(I)=TOTLAT(I) + FLOLAT(I)*DT
   90 CONTINUE
      TSEEP=SEEP*DT
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: PRECP
      SUBROUTINE SHP_PRECP (NPLANT, NC, NSP, NR, NS, TA, TADT, HUM, HUMDT, ZC, PINTRCP, XANGLE, CLUMPNG, ITYPE, WCANDT,
     >WCMAX, PCANDT, ZSP, DZSP, TSPDT, DLW, DLWDT, RHOSP, TQVSP, TOPSNO, WLAG, STORE, SNOWEX, ZR, TRDT, GMCDT, GMCMAX,
     >RHOR, ZS, TSDT, VLCDT, VICDT, MATDT, TOTFLO, TOTLAT, SALTDT, CONCDT, ICESPT, ICESDT, RAIN, POND, RUNOFF, EVAP1,
     >MELT, PONDMX, ISNOTMP, SNOTMP, SNODEN, DIRRES, SLOPE)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      REAL LF, LS, LV
      REAL ZC(11), WCANDT(10), PCANDT(8), PINTRCP(8), XANGLE(8), CLUMPNG(8), ZSP(200), DZSP(200), TSPDT(200), DLW(200),
     >DLWDT(200), RHOSP(200), TQVSP(200), WLAG(11), ZR(10), TRDT(10), GMCDT(10), RHOR(10), ZS(99), TSDT(99), VLCDT(99),
     >VICDT(99), MATDT(99), TOTFLO(99), TOTLAT(99), SALTDT(10, 99), CONCDT(10, 99)
      REAL MELT
      INTEGER ITYPE(8), ICESPT(200), ICESDT(99)
      AVGTA= WT*TA + WDT*TADT
      AVGHUM= WT*HUM + WDT*HUMDT
      TRAIN=AVGTA
      IF (RAIN.GT.0.0 .AND. NC.GT.0) CALL SHP_RAINC (NPLANT, NC, PINTRCP, XANGLE, CLUMPNG, ITYPE, RAIN, PCANDT, WCANDT,
     >WCMAX, SLOPE)
      MELT = 0.0
      SCOUT = 0.0
      IF (RAIN .GT. 0.0) THEN
      CALL SHP_WTBULB (TRAIN, AVGTA, AVGHUM)
      IF (ISNOTMP .EQ. 1) THEN
      THRSHOLD = AVGTA
      ELSE
      THRSHOLD = TRAIN
      END IF
      IF (THRSHOLD .LE. SNOTMP .OR. SNODEN .GT. 0.0) THEN
      SNOW = RAIN + SNOWEX
      POND = POND - SNOWEX
      SNOWEX = 0.0
      RAIN = 0.0
      IF (TRAIN .GT. 0.0) TRAIN = 0.0
      CALL SHP_NWSNOW (NSP, NC, NR, NS, NPLANT, ICESPT, ZSP, DZSP, RHOSP, TSPDT, DLW, DLWDT, TRAIN, SNOW, SNODEN, TQVSP,
     >MELT, ZC, PCANDT, ZR, TRDT, GMCDT, RHOR, ZS, VLCDT, VICDT, TSDT, MATDT, CONCDT)
      IF (MELT .GT. 0) THEN
      TRAIN = 0.0
      END IF
      ELSE
      IF (TRAIN .LT. 0.0) TRAIN = 0.0
      END IF
      END IF
      IF (NSP .GT. 0) THEN
      CALL SHP_WBSNOW (NSP, ICESPT, ZSP, DZSP, RHOSP, TSPDT, DLW, DLWDT, RAIN, TRAIN, TOPSNO, EVAP1, TQVSP, WLAG, STORE,
     >SCOUT)
      RAIN = SCOUT
      IF (SCOUT .GT. 0.0) TRAIN = 0.0
      END IF
      IF ((RAIN + POND + MELT).GT.0.0 .AND. TRAIN.GE.0.0) THEN
      RAIN=RAIN+MELT
      IF(NR.GT.0) CALL SHP_RAINRS (NR, TRAIN, RAIN, ZR, TRDT, GMCDT, RHOR, GMCMAX, DIRRES, SLOPE)
      IF (RAIN .GT. 0.0) THEN
      RAIN=RAIN+SNOWEX
      POND=POND-SNOWEX
      SNOWEX=0.0
      END IF
      RAIN = RAIN + POND
      POND = 0.0
      CALL SHP_RAINSL (NS, TRAIN, RAIN, ZS, TSDT, VLCDT, VICDT, ICESDT, MATDT, TOTFLO, TOTLAT, SALTDT, CONCDT, POND,
     >PONDMX, SLOPE)
      IF (SNOWEX .GT. 0.0) THEN
      POND = POND + RAIN
      RAIN = 0.0
      IF (POND .LT. SNOWEX) SNOWEX=POND
      END IF
      END IF
      IF (NSP .GT. 0) THEN
      WE = 0.0
      DO 20 I=1, NSP
      WE = WE + DZSP(I)*RHOSP(I)/RHOL + DLWDT(I)
   20 CONTINUE
      IF (WE .LT. 0.0005) THEN
      SCOUT = WE
      NSP = 0
      CALL SHP_SNOMLT (NSP, ICESPT, DZSP, RHOSP, TSPDT, DLWDT, WLAG, STORE, SCOUT)
      WRITE (6, *)
      WRITE (6, *) 'SNOWCOVER IS ASSUMED GONE: WATER-EQUIVALENT ' , 'OF ICE AND TOTAL WATER =' , WE, SCOUT, ' METERS'
      SNOWEX=SNOWEX + SCOUT
      POND=POND + SCOUT
      ELSE
      IF (NR .GT. 0) THEN
      TSPDT(NSP+1) = TRDT(1)
      ELSE
      TSPDT(NSP+1) = TSDT(1)
      END IF
      END IF
      END IF
      RUNOFF=RAIN
      MELT=MELT+SCOUT
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: WTBULB
      SUBROUTINE SHP_WTBULB (TW, TA, HUM)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      REAL LF, LS, LV
      PA=0.01*PRESUR
      EAS= 2.7489E8*EXP(-4278.63/(TA+242.792))
      EA=HUM*EAS
      DELTA= (4278.63/((TA+242.792)*(TA+242.792)))*EAS
      DO 10 I=1, 3
      TW= DELTA*TA+6.6E-4*PA*TA+7.59E-7*PA*TA*TA+EA-EAS
      TW= TW/(DELTA+6.6E-4*PA+7.59E-7*PA*TA)
      TAV= (TA+TW)*0.5
      EAV= 2.7489E8*EXP(-4278.63/(TAV+242.792))
      DELTA= (4278.63/((TAV+242.792)*(TAV+242.792)))*EAV
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: NWSNOW
      SUBROUTINE SHP_NWSNOW (NSP, NC, NR, NS, NPLANT, ICESPT, ZSP, DZSP, RHOSP, TSPDT, DLW, DLWDT, TWBULB, SNOW, SNODEN,
     >TQVSP, MELT, ZC, PCANDT, ZR, TRDT, GMCDT, RHOR, ZS, VLCDT, VICDT, TSDT, MATDT, CONCDT)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SPWATR/ CLAG1, CLAG2, CLAG3, CLAG4, PLWMAX, PLWDEN, PLWHC, THICK, CTHICK
      REAL LF, LS, LV
      REAL ZSP(200), DZSP(200), RHOSP(200), TSPDT(200), DLW(200), DLWDT(200), TQVSP(200)
      REAL ZC(11), PCANDT(8)
      REAL ZR(10), GMCDT(10), TRDT(10), RHOR(10), CRES(10)
      REAL ZS(99), VLCDT(99), VICDT(99), TSDT(99), MATDT(99), CONCDT(10, 99), CS(99)
      INTEGER ICESPT(200)
      REAL MELT
      IF (SNODEN .GT. 0.0) THEN
      DENSTY = SNODEN*RHOL
      ELSE
      IF (TWBULB .LE. -15.) THEN
      DENSTY = 50.
      ELSE
      DENSTY = 50. + 1.7*((TWBULB + 15.)**1.5)
      END IF
      END IF
      DEPTH = SNOW*RHOL/DENSTY
      IF (NC .GT. 0) THEN
      TOTAL=0.0
      DO 3 J=1, NPLANT
      CHANGE=PCANDT(J)*DEPTH/ZC(NC+1)
      IF (CHANGE .GT. PCANDT(J)) CHANGE=PCANDT(J)
      PCANDT(J)=PCANDT(J)-CHANGE
      TOTAL=TOTAL+CHANGE
    3 CONTINUE
      SNOW=SNOW+TOTAL
      DENSTY=SNOW*RHOL/DEPTH
      END IF
      MELT = 0.0
      IF (NSP .EQ. 0) THEN
      IF (NR .GT. 0) THEN
      CALL SHP_RESHT (NR, CRES, GMCDT, RHOR)
      IF (TRDT(1) .LE. 0.0) THEN
      MELT=0.0
      ELSE
      MELT = CRES(1)*ZR(2)/2.*TRDT(1)/(RHOL*LF-RHOL*CI*TWBULB)
      SNOW = SNOW - MELT
      DEPTH = DEPTH - MELT*RHOL/DENSTY
      IF (SNOW .LE. 0.0) THEN
      MELT = MELT + SNOW
      TRDT(1)= TRDT(1) - (RHOL*LF-RHOL*CI*TWBULB)*MELT /(CRES(1)*ZR(2)/2.)
      RETURN
      END IF
      TRDT(1) = 0.0
      END IF
      ELSE
      IF (TSDT(1) .LE. 0.0) THEN
      MELT=0.0
      ELSE
      CALL SHP_SOILHT(NS, CS, VLCDT, VICDT, TSDT, MATDT, CONCDT)
      MELT = CS(1)*ZS(2)/2.*TSDT(1)/(RHOL*LF-RHOL*CI*TWBULB)
      SNOW = SNOW - MELT
      DEPTH = DEPTH - MELT*RHOL/DENSTY
      IF (SNOW .LE. 0.0) THEN
      MELT = MELT + SNOW
      TSDT(1)= TSDT(1) - (RHOL*LF-RHOL*CI*TWBULB)*MELT /(CS(1)*ZS(2)/2.)
      RETURN
      END IF
      TSDT(1) = 0.0
      END IF
      END IF
      ELSE
      IF((DZSP(1) + DEPTH) .LE. (1.55*THICK)) THEN
      DNS = DEPTH
      DEPTH = 0.0
      NWLAYR = 0
      ELSE
      IF (DZSP(1) .GT. THICK) THEN
      DNS = 0.0
      GO TO 5
      END IF
      DNS = THICK - DZSP(1)
      DEPTH = DEPTH - DNS
      END IF
      WEI=RHOSP(1)*DZSP(1)/RHOL
      WENS=DENSTY*DNS/RHOL
      WEL=WEI+WENS
      DZSP(1) = DZSP(1) + DNS
      RHOSP(1)=RHOL*WEL/DZSP(1)
      TSPDT(1)=(WENS*TWBULB + WEI*TSPDT(1))/WEL
      IF (ICESPT(1) .EQ. 1) THEN
      FREEZE=-(TSPDT(1)*CI*WEL)/(LF*RHOL)
      IF (DLWDT(1) .LE. FREEZE) THEN
      TSPDT(1)=TSPDT(1)+(DLWDT(1)*LF*RHOL)/(CI*WEL)
      WEL=WEL+DLWDT(1)
      RHOSP(1)=RHOL*WEL/DZSP(1)
      DLWDT(1)=0.0
      ICESPT(1)=0
      ELSE
      DLWDT(1)=DLWDT(1)-FREEZE
      WEL=WEL+FREEZE
      RHOSP(1)=RHOL*WEL/DZSP(1)
      TSPDT(1)= 0.0
      END IF
      END IF
      END IF
    5 NWLAYR = DEPTH/THICK
      EXTRA = DEPTH - NWLAYR*THICK
      IF (EXTRA .GT. 0.55*THICK) NWLAYR = NWLAYR + 1
      IF (EXTRA .GT. 0.0 .AND. NWLAYR .EQ. 0) NWLAYR = 1
      IF (NSP .GT. 0) THEN
      DOWN = DEPTH + DNS
      IF (NWLAYR .EQ. 0) THEN
      ZSP(1) = 0.0
      DO 10 I=2, NSP+1
      ZSP(I) = ZSP(I) + DOWN
   10 CONTINUE
      RETURN
      ELSE
      ZSP(NSP+NWLAYR+1) = ZSP(NSP+1) + DOWN
      TSPDT(NSP+NWLAYR+1) = TSPDT(NSP+1)
      DO 15 I=NSP, 1, -1
      RHOSP(NWLAYR + I)= RHOSP(I)
      TSPDT(NWLAYR + I)= TSPDT(I)
      DLW(NWLAYR + I)= DLW(I)
      DLWDT(NWLAYR + I)= DLWDT(I)
      ICESPT(NWLAYR + I)= ICESPT(I)
      ZSP(NWLAYR + I) = ZSP(I) + DOWN
      DZSP(NWLAYR + I) = DZSP(I)
      TQVSP(NWLAYR + I) = TQVSP(I)
   15 CONTINUE
      ZSP(NWLAYR+1)=ZSP(NWLAYR+1)+DZSP(NWLAYR+1)/2.
      END IF
      END IF
      EXTRA=DEPTH - (NWLAYR-1)*THICK
      ZSP(1)=0.0
      DZSP(1)=EXTRA
      RHOSP(1)=DENSTY
      TSPDT(1)=TWBULB
      DLW(1)=0.0
      DLWDT(1)=0.0
      ICESPT(1)= 0
      TQVSP(1)=0.0
      TDEPTH=DZSP(1)
      DO 20 J=2, NWLAYR
      DZSP(J)=THICK
      ZSP(J)= TDEPTH + DZSP(J)/2.
      TDEPTH=TDEPTH + DZSP(J)
      RHOSP(J)=DENSTY
      TSPDT(J)=TWBULB
      DLW(J)=0.0
      DLWDT(J)=0.0
      ICESPT(J)= 0
      TQVSP(J)=0.0
   20 CONTINUE
      IF (NSP .EQ. 0) THEN
      ZSP(NWLAYR+1) = TDEPTH
      IF (NR .GT. 0) THEN
      TSPDT(NWLAYR+1) = TRDT(1)
      ELSE
      TSPDT(NWLAYR+1) = TSDT(1)
      END IF
      END IF
      NSP = NSP + NWLAYR
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: WBSNOW
      SUBROUTINE SHP_WBSNOW (NSP, ICESPT, ZSP, DZSP, RHOSP, TSPDT, DLW, DLWDT, RAIN, TRAIN, TOPSNO, EVAP1, TQVSP, WLAG,
     >STORE, SCOUT)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SPWATR/ CLAG1, CLAG2, CLAG3, CLAG4, PLWMAX, PLWDEN, PLWHC, THICK, CTHICK
      REAL LF, LS, LV
      REAL RHOSP(200), DZSP(200), ZSP(200), TSPDT(200), DLW(200), DLWDT(200), TQVSP(200), WLAG(11)
      INTEGER ICESPT(200)
      SCOUT = 0.0
      NL=NSP
      DZCHANGE = (TOPSNO - TQVSP(1))/RHOSP(1)
      DO 10 I=1, NSP
      IF (I.EQ.1 .OR. DZCHANGE.NE.0.0) THEN
      DZSP(I) = DZSP(I) + DZCHANGE
      IF (DZSP(I) .LE. 0.0) THEN
      IF (I.LT.NSP) THEN
      EXCESS = DZSP(I)*RHOSP(I) + DLW(I)*RHOL
      DZCHANGE = (EXCESS + TQVSP(I) - TQVSP(I+1))/RHOSP(I+1)
      DZSP(I) = 0.0
      NL = NL - 1
      ELSE
      TOPSNO=TOPSNO - DZSP(I)*RHOSP(I) + DLW(I)*RHOL
      EVAP1=EVAP1 - (DZSP(I)*RHOSP(I) + DLW(I)*RHOL)/RHOL
      NSP=0
      RETURN
      END IF
      ELSE
      DZCHANGE = 0.0
      END IF
      ELSE
      CHANGE = (TQVSP(I-1) - TQVSP(I))/DZSP(I)
      RHOSP(I) = RHOSP(I) + CHANGE
      END IF
   10 CONTINUE
      ABOVE= RAIN
      EXCESS= RAIN*(CL*TRAIN+LF)/LF
      DO 20 I=1, NSP
      IF (DZSP(I) .GT. 0.0) THEN
      IF (ICESPT(I) .EQ. 0) THEN
      IF (EXCESS .NE. 0.0) THEN
      WEL=RHOSP(I)*DZSP(I)/RHOL
      FREEZE=-TSPDT(I)*WEL*CI/LF
      IF (EXCESS .GT. FREEZE) THEN
      TSPDT(I)=0.0
      WEL=WEL+FREEZE
      RHOSP(I)=RHOL*WEL/DZSP(I)
      EXCESS=EXCESS-FREEZE
      ABOVE=ABOVE-FREEZE
      ICESPT(I) = 1
      ELSE
      TSPDT(I)=TSPDT(I) +(EXCESS*LF*RHOL)/(CI*RHOSP(I)*DZSP(I))
      WEL=WEL+EXCESS
      RHOSP(I)=RHOL*WEL/DZSP(I)
      ABOVE = ABOVE - EXCESS
      EXCESS=0.0
      END IF
      END IF
      END IF
      DLWDT(I)= DLWDT(I) + EXCESS
      CHANGE= DLWDT(I) - DLW(I) - ABOVE
      IF (ABS(CHANGE).LT.0.0000001) THEN
      ABOVE=0.0
      EXCESS=0.0
      ELSE
      IF (CHANGE .LE. 0.0) THEN
      WEL=RHOSP(I)*DZSP(I)/RHOL
      WEL=WEL-CHANGE
      RHOSP(I)=RHOL*WEL/DZSP(I)
      ABOVE=0.0
      EXCESS=0.0
      ELSE
      WEL=RHOSP(I)*DZSP(I)/RHOL
      IF (CHANGE .GE. WEL) THEN
      NL=NL-1
      ABOVE= ABOVE + WEL + DLW(I)
      EXCESS=DLWDT(I)
      DZSP(I)=0.0
      ELSE
      WEL=WEL-CHANGE
      DZSP(I)=RHOL*WEL/RHOSP(I)
      ABOVE=0.0
      EXCESS=0.0
      END IF
      END IF
      END IF
      END IF
   20 CONTINUE
      IF (NL .LE. 0) THEN
      NSP = 0
      WE = 0.0
      TDEPTH = 0.0
      SCOUT = ABOVE
      CALL SHP_SNOMLT (NSP, ICESPT, DZSP, RHOSP, TSPDT, DLWDT, WLAG, STORE, SCOUT)
      RETURN
      END IF
      IF (NL .NE. NSP) THEN
      DO 30 I=1, NSP
   23 IF (DZSP(I) .GT. 0.0) GO TO 30
      NEXT=I+1
      DO 25 J=NEXT, NSP
      L=J-1
      DZSP(L)=DZSP(J)
      RHOSP(L)=RHOSP(J)
      TSPDT(L)=TSPDT(J)
      DLWDT(L)=DLWDT(J)
      ICESPT(L)=ICESPT(J)
   25 CONTINUE
      NSP = NSP - 1
      IF (NSP .EQ. NL) GO TO 35
      GO TO 23
   30 CONTINUE
   35 DLWDT(NSP)= DLWDT(NSP) + ABOVE
      END IF
      TDEPTH=0.0
      I=1
      IF (NSP .EQ. 1) GO TO 80
   40 ZZ=TDEPTH+DZSP(I)*0.5
      DZ1=THICK
      IF (ZZ .GT. 0.30) DZ1=CTHICK*(ZZ-0.30)+THICK
      IF (DZSP(I) .GT. 1.55*DZ1) GO TO 50
      IF (DZSP(I) .LT. 0.55*DZ1 .AND. NSP.GT.1) GO TO 60
      TDEPTH=TDEPTH+DZSP(I)
      GO TO 70
   50 NEXT=I+1
      IF (NEXT .LE. NSP) THEN
      DO 55 J=NEXT, NSP
      L=NSP-J+NEXT
      LL=L+1
      DZSP(LL)=DZSP(L)
      RHOSP(LL)=RHOSP(L)
      TSPDT(LL)=TSPDT(L)
      DLWDT(LL)=DLWDT(L)
      ICESPT(LL)=ICESPT(L)
   55 CONTINUE
      END IF
      TDEPTH=TDEPTH+DZSP(I)
      DZSP(NEXT)=DZSP(I)*0.5
      RHOSP(NEXT)=RHOSP(I)
      TSPDT(NEXT)=TSPDT(I)
      DLWDT(NEXT)=DLWDT(I)*0.5
      ICESPT(NEXT)=ICESPT(I)
      DZSP(I)=DZSP(I)*0.5
      DLWDT(I)=DLWDT(I)*0.5
      I=I+1
      NSP=NSP+1
      GO TO 70
   60 IF (I .EQ. 1 .OR. I .EQ. NSP) THEN
      IF (I .EQ. 1) THEN
      NL=2
      ELSE
      NL=NSP-1
      END IF
      ELSE
      NL=I-1
      IF (DZSP(I+1) .LT. DZSP(I-1)) NL=I+1
      END IF
      WEI=RHOSP(I)*DZSP(I)/RHOL
      WENL=RHOSP(NL)*DZSP(NL)/RHOL
      WEL=WEI+WENL
      DZSP(NL)=DZSP(NL)+DZSP(I)
      RHOSP(NL)=RHOL*WEL/DZSP(NL)
      DLWDT(NL)= DLWDT(NL) + DLWDT(I)
      TSPDT(NL)=(WENL*TSPDT(NL)+WEI*TSPDT(I))/WEL
      IF (ICESPT(I) .NE. ICESPT(NL)) THEN
      FREEZE=-(TSPDT(NL)*CI*RHOSP(NL)*DZSP(NL))/(LF*RHOL)
      IF (DLWDT(NL) .LE. FREEZE) THEN
      TSPDT(NL)=TSPDT(NL) + (DLWDT(NL)*LF*RHOL) /(CI*RHOSP(NL)*DZSP(NL))
      WEL=WEL+DLWDT(NL)
      RHOSP(NL)=RHOL*WEL/DZSP(NL)
      ICESPT(NL)=0
      ELSE
      DLWDT(NL)=DLWDT(NL)-FREEZE
      WEL=WEL+FREEZE
      RHOSP(NL)=RHOL*WEL/DZSP(NL)
      ICESPT(NL)=1
      END IF
      END IF
      IF (ICESPT(NL) .EQ. 1) TSPDT(NL)=0.0
      IF (ICESPT(NL) .EQ. 0) DLWDT(NL)=0.0
      IF (NL .LT. I) TDEPTH=TDEPTH+DZSP(I)
      NEXT=I+1
      IF (NEXT .LE. NSP) THEN
      DO 65 J=NEXT, NSP
      L=J-1
      DZSP(L)=DZSP(J)
      RHOSP(L)=RHOSP(J)
      TSPDT(L)=TSPDT(J)
      DLWDT(L)=DLWDT(J)
      ICESPT(L)=ICESPT(J)
   65 CONTINUE
      END IF
      I = I-1
      NSP = NSP-1
   70 IF (I .LT. NSP) THEN
      I=I+1
      GO TO 40
      END IF
   80 CALL SHP_META (NSP, TSPDT, RHOSP, DZSP, DLWDT)
      CALL SHP_SNOMLT (NSP, ICESPT, DZSP, RHOSP, TSPDT, DLWDT, WLAG, STORE, SCOUT)
      ZSP(1) = 0.0
      TDEPTH = DZSP(1)
      WE = DZSP(1)*RHOSP(1)/RHOL + DLWDT(1)
      DO 85 I=2, NSP
      ZSP(I)= TDEPTH + DZSP(I)/2.
      TDEPTH= TDEPTH + DZSP(I)
      WE = WE + DZSP(I)*RHOSP(I)/RHOL + DLWDT(I)
   85 CONTINUE
      ZSP(NSP+1) = TDEPTH
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: META
      SUBROUTINE SHP_META (NSP, TSPDT, RHOSP, DZSP, DLWDT)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_METASP/ CMET1, CMET2, CMET3, CMET4, CMET5, SNOMAX
      REAL TSPDT(200), RHOSP(200), DZSP(200), DLWDT(200)
      REAL LF, LS, LV
      IF (CMET1 .LE. 0.0 .OR. CMET3 .LE. 0.0) THEN
      IF (CMET5 .LE. 0.0) RETURN
      END IF
      SHP_WEIGHT=0.0
      DO 10 I=1, NSP
      IF (RHOSP(I) .GE. RHOI) GO TO 10
      WEL= RHOSP(I)*DZSP(I)/RHOL
      TERM=EXP(CMET4*TSPDT(I))
      IF (RHOSP(I) .LE. SNOMAX) THEN
      T1=TERM*CMET3
      ELSE
      T1=TERM*CMET3*EXP(-46.0*(RHOSP(I)-SNOMAX)/RHOL)
      END IF
      TERM=EXP(0.08*TSPDT(I))
      T2=SHP_WEIGHT*CMET1*EXP(-CMET2*RHOSP(I)/RHOL)*TERM
      IF (DLWDT(I) .GT. 0.0) T1=CMET5*T1
      RHOSP(I)=RHOSP(I)*(1.0 + DT*(T1+T2)/3600.)
      DZSP(I)=RHOL*WEL/RHOSP(I)
      SHP_WEIGHT=SHP_WEIGHT + (WEL+DLWDT(I))*100.
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: SNOMLT
      SUBROUTINE SHP_SNOMLT (NSP, ICESPT, DZSP, RHOSP, TSPDT, DLWDT, WLAG, STORE, SCOUT)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SPWATR/ CLAG1, CLAG2, CLAG3, CLAG4, PLWMAX, PLWDEN, PLWHC, THICK, CTHICK
      REAL LF, LS, LV
      REAL DZSP(200), RHOSP(200), TSPDT(200), DLWDT(200), WLAG(11)
      INTEGER ICESPT(200)
      COMMON /SHP_SV_SNOMLT/ IFIRST, NLAG
C     Mutable SAVE initialization moved to SHP_SAVE_INITIAL_VALUES.
      IF(IFIRST .EQ. 0) THEN
      JDT=CLAG1+0.01
      NLAG=JDT+2
      IF (NLAG.GT.11) NLAG=11
      IFIRST=1
      END IF
      IF (NSP .LE. 0) THEN
      DO 10 J=1, NLAG
      SCOUT=SCOUT+WLAG(J)
      WLAG(J)=0.0
   10 CONTINUE
      SCOUT=SCOUT+STORE
      STORE=0.0
      RETURN
      END IF
      EXCESS=0.0
      IF (NSP .EQ. 1) GO TO 12
      BOTTOM=0.0
      IF (ICESPT(NSP) .EQ. 1) THEN
      WEL=RHOSP(NSP)*DZSP(NSP)/RHOL
      PLW=(PLWMAX-PLWHC)*(PLWDEN-RHOSP(NSP))/PLWDEN+PLWHC
      IF (RHOSP(NSP) .GE. PLWDEN) PLW=PLWHC
      WMAX=PLW*WEL
      IF (DLWDT(NSP) .GT. WMAX) BOTTOM= DLWDT(NSP) - WMAX
      END IF
   12 WE=0.0
      TDEPTH=0.0
      DO 20 I=1, NSP
      WEL=RHOSP(I)*DZSP(I)/RHOL
      IF(ICESPT(I) .EQ. 0) THEN
      IF(EXCESS .EQ. 0.0) GO TO 15
      FREEZE=-TSPDT(I)*CI*WEL/LF
      IF (EXCESS .LE. FREEZE) THEN
      TSPDT(I)=TSPDT(I)+(EXCESS*LF*RHOL)/(CI*WEL*RHOL)
      WEL=WEL+EXCESS
      EXCESS=0.0
      RHOSP(I)=RHOL*WEL/DZSP(I)
      GO TO 15
      ELSE
      TSPDT(I)= 0.0
      WEL=WEL+FREEZE
      RHOSP(I)=RHOL*WEL/DZSP(I)
      EXCESS=EXCESS-FREEZE
      ICESPT(I)=1
      END IF
      END IF
      PLW=(PLWMAX-PLWHC)*(PLWDEN-RHOSP(I))/PLWDEN+PLWHC
      IF (RHOSP(I) .GE. PLWDEN) PLW=PLWHC
      WMAX= PLW*WEL
      W= DLWDT(I) + EXCESS
      IF (W .LE. WMAX) THEN
      DLWDT(I)=W
      EXCESS=0.0
      ELSE
      DLWDT(I)=WMAX
      EXCESS=W-WMAX
      END IF
   15 WE=WE+WEL
      TDEPTH=TDEPTH+DZSP(I)
   20 CONTINUE
      IF (NSP .EQ. 1) THEN
      SCOUT = EXCESS
      DO 50 J=1, NLAG
      SCOUT=SCOUT+WLAG(J)
      WLAG(J)=0.0
   50 CONTINUE
      SCOUT=SCOUT+STORE
      STORE=0.0
      RETURN
      END IF
      EXCESS=EXCESS-BOTTOM
      IF (ICESPT(NSP) .EQ. 0) THEN
      OUTHR=0.0
      SCOUT=0.0
      RETURN
      END IF
      EXCSHR = EXCESS*3600./DT
      IDT=DT/3600.
      IF (AMOD(DT, 3600.).GT.0.00001) IDT=IDT+1
      IF (IDT .EQ. 0) IDT=1
      HOURS=1.0
      DENSE = WE/TDEPTH
      SCOUT=0.0
      DO 35 IHR=1, IDT
      IF (IHR.EQ.IDT) HOURS=DT/3600-(IDT-1)
      EXCESS=EXCSHR*HOURS
      OUTHR=0.0
      IF (EXCSHR .GE. 0.00001) THEN
      NI= ((EXCSHR*10000.0)**0.3)+0.5
      IF (NI .LT. 1) NI=1
      FN=NI
      FLMAX=CLAG1*(1.0-EXP(-0.25*TDEPTH/DENSE))
      DO 25 J=1, NI
      FJ=J
      FLAG=FLMAX/(CLAG2*EXCSHR*100.*(FJ-0.5)/FN+1.0)
      K= FLAG+1.0
      POR=K-FLAG
      WINC=1.0/FN
      WLAG(K)=WLAG(K)+EXCESS*WINC*POR
      WLAG(K+1)=WLAG(K+1)+EXCESS*WINC*(1.0-POR)
   25 CONTINUE
      ELSE
      WLAG(1)=WLAG(1)+EXCESS
      END IF
      IF ((STORE+WLAG(1)) .NE. 0.0) THEN
      R=1.0/(CLAG3*EXP(-CLAG4*WLAG(1)*DENSE/TDEPTH)+1.0)
      OUTHR=(STORE+WLAG(1))*R
      STORE=STORE+(WLAG(1)-OUTHR)*HOURS
      SCOUT=SCOUT+OUTHR*HOURS
      IF(STORE .LE. 0.00001) THEN
      OUTHR=OUTHR+STORE
      SCOUT=SCOUT+STORE
      STORE=0.0
      END IF
      END IF
      NI=NLAG-1
      DO 30 J=1, NI
      WLAG(J)=WLAG(J)*(1.-HOURS) + WLAG(J+1)*HOURS
      IF (WLAG(J+1).LE. 0.000001) THEN
      WLAG(J)=WLAG(J)+WLAG(J+1) + WLAG(J+1)*(1.-HOURS)
      WLAG(J+1)=0.0
      END IF
   30 CONTINUE
      WLAG(NLAG)=0.0
   35 CONTINUE
      SCOUT=SCOUT+BOTTOM
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: RAINC
      SUBROUTINE SHP_RAINC (NPLANT, NC, PINTRCP, XANGLE, CLUMPNG, ITYPE, RAIN, PCANDT, WCANDT, WCMAX, SLOPE)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_CLAYRS/ PLANTZ(8), DRYCAN(8, 10), CANLAI(8, 10), TOTLAI(8), IEVAP(8), RLEAF(8, 10), RROOT(8, 99),
     >ROOTDN(8, 99), TOTROT(8)
      REAL PCANDT(8), PINTRCP(8), XANGLE(8), CLUMPNG(8), WCANDT(10), TDIRCC(10), TDIFFC(10), DIRKL(9, 10), DIFKL(9, 10),
     >FBDU(8), FDDU(8)
      REAL LF, LS, LV
      REAL MAXINT
      INTEGER ITYPE(8)
      ANGLE=1.5708-SLOPE
      CALL SHP_TRANSC (NPLANT, NC, XANGLE, CLUMPNG, TDIRCC, TDIFFC, DIFKL, DIRKL, FBDU, FDDU, ANGLE, 1.57)
      TRANS=1.0
      DO 5 I=1, NC
      TRANS=TRANS*TDIRCC(I)
    5 CONTINUE
      RINTER=RAIN*(1.-TRANS)
      SUMLAI=0.0
      DO 10 J=1, NPLANT
      SUMLAI=SUMLAI+TOTLAI(J)
   10 CONTINUE
      TOTAL = 0.0
      DO 40 J=1, NPLANT
      IF (ITYPE(J) .NE. 0) THEN
      SLAI=0.0
      DO 20 I=1, NC
      SLAI=SLAI+CANLAI(J, I)
   20 CONTINUE
      RINT=RINTER*SLAI/SUMLAI
      PCANDT(J)=PCANDT(J)+RINT
      MAXINT=PINTRCP(J)*SLAI
      IF (PCANDT(J) .GT. MAXINT) THEN
      RINT = MAXINT - (PCANDT(J) - RINT)
      PCANDT(J) = MAXINT
      END IF
      TOTAL = TOTAL + RINT
      ELSE
      EXCESS = 0.0
      DO 30 I=1, NC
      IF (CANLAI(J, I).GT.0.0) THEN
      RINTLY=RINTER*CANLAI(J, I)/SUMLAI + EXCESS
      WCANDT(I) = WCANDT(I) + RINTLY*RHOL/DRYCAN(J, I)
      EXCESS = 0.0
      IF (WCANDT(I) .GT. WCMAX) THEN
      EXCESS = (WCANDT(I)-WCMAX)*DRYCAN(J, I)/RHOL
      RINTLY = RINTLY-EXCESS
      WCANDT(I)=WCMAX
      END IF
      TOTAL=TOTAL+RINTLY
      END IF
   30 CONTINUE
      END IF
   40 CONTINUE
      RAIN = RAIN - TOTAL
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: RAINRS
      SUBROUTINE SHP_RAINRS (NR, TRAIN, RAIN, ZR, TRDT, GMCDT, RHOR, GMCMAX, DIRRES, SLOPE)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      REAL LF, LS, LV
      REAL ZR(10), TRDT(10), GMCDT(10), RHOR(10), TDIREC(10), TDIFFU(10), CRES(10)
      ANGLE=1.5708-SLOPE
      CALL SHP_TRANSR (NR, TDIREC, TDIFFU, ZR, RHOR, ANGLE, DIRRES)
      CALL SHP_RESHT (NR, CRES, GMCDT, RHOR)
      DO 10 I=1, NR
      IF (I .EQ. 1) THEN
      DZ=ZR(2)-ZR(1)
      IF (NR .NE. 1) DZ=DZ/2.
      ELSE
      IF (I .EQ. NR) THEN
      DZ=ZR(I+1)-ZR(I)+(ZR(I)-ZR(I-1))/2.
      ELSE
      DZ=(ZR(I+1)-ZR(I-1))/2.
      END IF
      END IF
      RINTER=RAIN*(1.-TDIREC(I))
      GMCDT(I)=GMCDT(I) + RINTER*RHOL/(DZ*RHOR(1))
      RAIN=RAIN-RINTER
      IF (GMCDT(I) .GT. GMCMAX) THEN
      EXCESS= RHOR(I)*(GMCDT(I)-GMCMAX)*DZ/RHOL
      RINTER= RINTER-EXCESS
      RAIN= RAIN+EXCESS
      GMCDT(I)= GMCMAX
      END IF
      RAINHT=RINTER*RHOL*CL
      RESIHT=CRES(I)*DZ
      TRDT(I)=TRDT(I) + RAINHT/(RAINHT+RESIHT)*(TRAIN-TRDT(I))
   10 CONTINUE
      END
C     USDA-ARS SHAW 3.0.3: RAINSL
      SUBROUTINE SHP_RAINSL (NS, TRAIN, RAIN, ZS, TSDT, VLCDT, VICDT, ICESDT, MATDT, TOTFLO, TOTLAT, SALTDT, CONCDT,
     >POND, PONDMX, SLOPE)
      COMMON /SHP_SV_RAINSL/ PSATK, PSAT
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      REAL LF, LS, LV
      REAL ZS(99), TSDT(99), VLCDT(99), VICDT(99), MATDT(99), TOTFLO(99), TOTLAT(99), SALTDT(10, 99), CONCDT(10, 99),
     >SATKMX(99), MATRIC(99), CS(99)
      INTEGER ICESDT(99)
      REAL INFIL, INFMAX(99), PSAT(99), VLC9(99), MAT9(99), SATK9(99), POTINF(99), XTRLAT(99), DTIME(99)
C     Mutable SAVE initialization moved to SHP_SAVE_INITIAL_VALUES.
      DO 10 I=1, NS
      IF (ICESDT(I) .GE. 1) THEN
      VLCMAX= SoilWRC(I, 2) - VICDT(I)
      IF (VLCDT(I) .GT. VLCMAX) VLCMAX=VLCDT(I)
      CALL SHP_MATVL1 (I, MATRIC(I), VLCMAX, DUMMY)
      VLC9(I)=PSATK*VLCMAX
      ELSE
      MATRIC(I)=SoilWRC(I, 1)
      VLC9(I)=PSATK*SoilWRC(I, 2)
      END IF
      IF (VLC9(I) .LT. SOILWRC(I, 4)) VLC9(I) = Soilwrc(I, 4) + PSATK*(VLCMAX-Soilwrc(I, 4))
      CALL SHP_MATVL1 (I, MAT9(I), VLC9(I), DUMMY)
      XTRLAT(I) = 0.0
   10 CONTINUE
      CALL SHP_SOILHK (NS, SATKMX, MATRIC, VLCDT, VICDT)
      NSAT = NS
      DTIME(1)=DT
      INFIL=0.0
      dINFIL=0.0
      ZSTAR=0.0
      SUMZ=0.0
      SUMZK=0.0
      PSAT(1)=PSATK
      I = 1
      IF (SATKMX(1) .LE. 0) GO TO 40
      IF (MATDT(1) .GE. 0.0) GO TO 40
      INFMAX(I)=(PSAT(1)*SoilWRC(1, 2) - VLCDT(1) - VICDT(1))*(ZS(2) - ZS(1))/2.
      IF (INFMAX(I) .LE. 0.0) THEN
      INFMAX(I) = 0.0
      DTIME(I+1)=DTIME(I)
      GO TO 30
      END IF
   20 IF (ZSTAR .LE. 1.0) THEN
      DTSTAR= SATKMX(I)*DTIME(I)/(PSAT(I)*SoilWRC(I, 2) - VLCDT(I) - VICDT(I))/(-MATDT(I)+SUMZ)
      POTINF(I)=(DTSTAR-2.*ZSTAR + SQRT((DTSTAR-2.*ZSTAR)**2 +8.*DTSTAR))/2.
      POTINF(I)=POTINF(I)*(PSAT(I)*SoilWRC(I, 2)-VLCDT(I)-VICDT(I)) *(-MATDT(I)+SUMZ)
      ELSE
      IF (I .LT. NSAT) NSAT = I-1
      POTINF(I)=SATINF*DTIME(I)
      END IF
      IF (INFMAX(I) .GE. (RAIN-INFIL)) THEN
      IF (POTINF(I) .GE. (RAIN-INFIL)) THEN
      dINFIL=INFIL-RAIN
      INFIL=RAIN
      ELSE
      dINFIL=POTINF(I)
      INFIL=INFIL+POTINF(I)
      END IF
      GO TO 40
      END IF
      IF (POTINF(I) .LT. INFMAX(I)) THEN
      dINFIL=POTINF(I)
      INFIL=INFIL+POTINF(I)
      GO TO 40
      END IF
      IF (ZSTAR .LE. 1.0) THEN
      DIMINF=INFMAX(I)/(PSAT(I)*SoilWRC(I, 2)-VLCDT(I)-VICDT(I)) /(-MATDT(I)+SUMZ)
      IF (DIMINF .GT. 0.01) THEN
      DTSTAR= (ZSTAR-1.)*ALOG(1. + DIMINF) + DIMINF
      ELSE
      DTSTAR= (ZSTAR-1.)*2.*DIMINF/(2.+DIMINF) + DIMINF
      END IF
      TIME= DTSTAR*(PSAT(I)*SoilWRC(I, 2)-VLCDT(I)-VICDT(I)) *(-MATDT(I)+SUMZ)/SATKMX(I)
      ELSE
      IF (I .LT. NSAT) NSAT = I-1
      TIME=INFMAX(I)/SATINF
      END IF
      DTIME(I+1)= DTIME(I)-TIME
      dINFIL=INFMAX(I)
      INFIL=INFIL+INFMAX(I)
      IF (DTIME(I+1) .LE. 0.0) THEN
      DTIME(I+1) = 0.0
      GO TO 40
      END IF
   30 I = I + 1
      IF (SATKMX(I) .LE. 0) GO TO 40
      IF (MATDT(I) .GT. SUMZ) GO TO 40
      SUMZ2= (ZS(I)+ZS(I-1))/2.
      DZ= SUMZ2-SUMZ
      SUMZ= SUMZ2
      SUMZK= SUMZK + DZ/SATKMX(I-1)
      IF (I.LT.NS) THEN
      IF (ZSTAR .LE. 1.0) THEN
      ZSTAR=SATKMX(I)*SUMZK/(-MATDT(I) + SUMZ)
      PSAT(I)=PSATK
      IF (ZSTAR .GT. 1.0) THEN
      SATINF=(-MATDT(I) + SUMZ)/SUMZK
      CALL SHP_SOILHK (NS, SATK9, MAT9, VLC9, VICDT)
      IF (SATK9(I) .GT. 0.0 .AND. SATK9(I) .LT. SATKMX(I)) THEN
      PSAT(I)=10.**(ALOG10(PSATK)* ALOG10(SATINF/SATKMX(I))/ALOG10(SATK9(I)/SATKMX(I)))
      ELSE
      PSAT(I) = VLC9(I)/SoilWRC(I, 2)
      PSAT(I) = PSAT(I)+(PSATK-PSAT(I))*SATINF/SATKMX(I)
      END IF
      IF (PSAT(I).GT. PSATK) PSAT(I)=PSATK
      SATKMX(I)=SUMZ/SUMZK
      END IF
      ELSE
      SATINF=(-MATDT(I) + SUMZ)/SUMZK
      IF (SATKMX(I) .LT. SATINF) SATINF=SATKMX(I)
      IF (SATK9(I) .GT. 0.0 .AND. SATK9(I) .LT. SATKMX(I)) THEN
      PSAT(I)=10.**(ALOG10(PSATK)* ALOG10(SATINF/SATKMX(I))/ALOG10(SATK9(I)/SATKMX(I)))
      ELSE
      PSAT(I) = VLC9(I)/SoilWRC(I, 2)
      PSAT(I) = PSAT(I)+(PSATK-PSAT(I))*SATINF/SATKMX(I)
      END IF
      IF (PSAT(I).GT. PSATK) PSAT(I)=PSATK
      SATKMX(I)=SUMZ/SUMZK
      IF (I .LT. NSAT) NSAT = I-1
      END IF
      INFMAX(I)=(PSAT(I)*SoilWRC(I, 2)-VLCDT(I)-VICDT(I)) *(ZS(I+1)-ZS(I-1))/2.
      IF (INFMAX(I) .LE. 0.0) THEN
      INFMAX(I)=0.0
      POTINF(I)=DTIME(I)*SUMZ/SUMZK
      DTIME(I+1)=DTIME(I)
      GO TO 30
      END IF
      GO TO 20
      ELSE
      IF (ZSTAR .LE. 1.0) THEN
      dINFIL=DTIME(I)*SUMZ/SUMZK
      INFIL=INFIL + DTIME(I)*SUMZ/SUMZK
      ELSE
      IF (SATKMX(I) .LT. SATINF) SATINF=SATKMX(I)
      dINFIL=DTIME(I)*SATINF
      INFIL=INFIL + DTIME(I)*SATINF
      IF (I .LT. NSAT) NSAT = I-1
      END IF
      IF (INFIL .GT. RAIN) THEN
      dINFIL=RAIN-INFIL
      INFIL=RAIN
      END IF
      END IF
   40 IF (INFIL .LT. RAIN) THEN
      IF (I .LT. NSAT) NSAT = I
      IMAX = I
      FLOWNEXT = dINFIL
      DO 45 I = IMAX, 1, -1
      if (I.LE.NSAT) then
      IF (SATKLAT(I).GT.0.0 .AND. VICDT(I).LE.0.0) THEN
      IF (I .EQ. 1) THEN
      DZ = (ZS(2)-ZS(1))/2.
      ELSE
      DZ = (ZS(I+1)-ZS(I-1))/2.
      END IF
      XTRLAT(I) = DTIME(I)*SATKLAT(I)*SIN(SLOPE)*DZ - TOTLAT(I)
      IF (XTRLAT(I) .LT. 0.0) XTRLAT(I) = 0.0
      XTRMAX = POTINF(I)-INFMAX(I)-FLOWNEXT
      IF (XTRMAX .LE. 0.) XTRMAX=0.0
      IF (XTRLAT(I) .GT. XTRMAX) XTRLAT(I)=XTRMAX
      IF (XTRLAT(I) .GT. 0.) THEN
      IF (XTRLAT(I) .GE. (RAIN-INFIL)) THEN
      XTRLAT(I) = RAIN-INFIL
      INFIL=RAIN
      TOTLAT(I) = TOTLAT(I) + XTRLAT(I)
      GO TO 46
      ELSE
      INFIL=INFIL + XTRLAT(I)
      END IF
      TOTLAT(I) = TOTLAT(I) + XTRLAT(I)
      END IF
      END IF
      end if
      FLOWNEXT = FLOWNEXT+INFMAX(I)+XTRLAT(I)
      IF (I .GT. 1) THEN
      IF (POTINF(I-1) .LT. POTINF(I)) POTINF(I-1) = POTINF(I)
      END IF
   45 CONTINUE
      END IF
   46 POND= RAIN-INFIL
      RAIN= 0.0
      IF (POND .GT. PONDMX) THEN
      RAIN= POND-PONDMX
      POND= PONDMX
      END IF
      IF (INFIL.LE.0.0) THEN
      I = 1
      INFMAX(1)=0.0
      GO TO 110
      END IF
      CALL SHP_SOILHT (NS, CS, VLCDT, VICDT, TSDT, MATDT, CONCDT)
      I = 1
      SLOSS = 0.0
      DZ=(ZS(2)-ZS(1))/2.
   50 INFMAX(I)=(PSAT(I)*SoilWRC(I, 2) - VLCDT(I) - VICDT(I))*DZ
      IF (INFMAX(I) .LT. 0.0) INFMAX(I)=0.0
      IF (INFMAX(I) .GE. INFIL) INFMAX(I)=INFIL
      DO 60 J=1, NSALT
      IF (INFIL .LE. 0.0) THEN
      CLEACH = 0.0
      ELSE
      CLEACH = SLOSS/RHOL/INFIL
      END IF
      SALTDT(J, I) = SALTDT(J, I) + CLEACH*RHOL*INFMAX(I)/RHOB(I)
      SKQVLC= SALTKQ(J, I) + (VLCDT(I)+INFMAX(I)/DZ)*RHOL/RHOB(I)
      SLTNEW= (CLEACH*RHOL*(INFIL-INFMAX(I))/DZ + SALTDT(J, I)*(RHOB(I)-WT*RHOL*(INFIL-INFMAX(I))/DZ/SKQVLC))
     >/(RHOB(I)+WDT*RHOL*(INFIL-INFMAX(I))/DZ/SKQVLC)
      IF (SLTNEW .LT. 0.0) SLTNEW=0.0
      SLOSS= (SALTDT(J, I) - SLTNEW)*RHOB(I)*DZ
      SALTDT(J, I)= SLTNEW
   60 CONTINUE
      SHEAT= CS(I)*DZ
      RAINHT= INFIL*RHOL*CL
      IF (ICESDT(I) .LE. 0) THEN
      TSDT(I)= TSDT(I) + RAINHT/(RAINHT+SHEAT)*(TRAIN-TSDT(I))
      VLCDT(I)= VLCDT(I) + INFMAX(I)/DZ
      IF (MATDT(I).LT.SoilWRC(I, 1)) CALL SHP_MATVL1 (I, MATDT(I), VLCDT(I), DUMMY)
      DO 70 J=1, NSALT
      CONCDT(J, I)=SALTDT(J, I)/(SALTKQ(J, I)+VLCDT(I)*RHOL/RHOB(I))
   70 CONTINUE
      ELSE
      OLDVLC= VLCDT(I)
      VLCDT(I)= VLCDT(I) + VICDT(I)*RHOI/RHOL + INFMAX(I)/DZ
      CALL SHP_MATVL1 (I, MATDT(I), VLCDT(I), DUMMY)
      TLCONC=0.0
      DO 80 J=1, NSALT
      CONCDT(J, I)= SALTDT(J, I)/(SALTKQ(J, I)+VLCDT(I)*RHOL/RHOB(I))
      TLCONC=TLCONC + CONCDT(J, I)
   80 CONTINUE
      TOTPOT= MATDT(I) - TLCONC*UGAS*273.16/G
      TMPFRZ= 273.16*TOTPOT/(LF/G-TOTPOT)
      AVHEAT= RAINHT*(TRAIN-TMPFRZ)
      RQHEAT= RHOI*LF*VICDT(I)*DZ + SHEAT*(TMPFRZ-TSDT(I))
      IF (AVHEAT .GE. RQHEAT) THEN
      TSDT(I)= TMPFRZ + (AVHEAT-RQHEAT)/(SHEAT+RAINHT)
      VICDT(I)= 0.0
      ICESDT(I) = 0
      GO TO 110
      END IF
      TSOIL= TSDT(I)
      OLDVIC= VICDT(I)
      VICMAX= VICDT(I) + INFMAX(I)/DZ*(RHOL/RHOI)
      VICDT(I)= OLDVIC - (RAINHT*(TRAIN-TMPFRZ)-SHEAT*(TMPFRZ-TSOIL)) /(RHOI*LF*DZ)
      IF (VICDT(I) .GT. VICMAX) VICDT(I) = VICMAX
      VLCDT(I)= OLDVLC + (VICMAX-VICDT(I))*RHOI/RHOL
      CALL SHP_MATVL1 (I, MATDT(I), VLCDT(I), DUMMY)
      TLCONC=0.0
      DO 90 J=1, NSALT
      CONCDT(J, I)= SALTDT(J, I)/(SALTKQ(J, I)+VLCDT(I)*RHOL/RHOB(I))
      TLCONC=TLCONC + CONCDT(J, I)
   90 CONTINUE
      TOTPOT= MATDT(I) - TLCONC*UGAS*273.16/G
      TSDT(I)= 273.16*TOTPOT/(LF/G-TOTPOT)
      VICDT(I)= OLDVIC-(RAINHT*(TRAIN-TSDT(I))-SHEAT*(TSDT(I)-TSOIL)) /(RHOI*LF*DZ)
      IF (VICDT(I) .GT. VICMAX) VICDT(I) = VICMAX
      VLCDT(I)= OLDVLC + (VICMAX-VICDT(I))*RHOI/RHOL
      CALL SHP_MATVL1 (I, MATDT(I), VLCDT(I), DUMMY)
      TLCONC=0.0
      DO 100 J=1, NSALT
      CONCDT(J, I)= SALTDT(J, I)/(SALTKQ(J, I)+VLCDT(I)*RHOL/RHOB(I))
      TLCONC=TLCONC + CONCDT(J, I)
  100 CONTINUE
      TOTPOT= MATDT(I) - TLCONC*UGAS*273.16/G
      TSDT(I)= 273.16*(LF/G/(LF/G-TOTPOT) - 1.0)
      END IF
  110 I = I + 1
      INFIL=INFIL-INFMAX(I-1)-XTRLAT(I-1)
      TOTFLO(I-1)=TOTFLO(I-1)+INFIL
      IF (I .LT. NS) THEN
      DZ=(ZS(I+1) - ZS(I-1))/2.
      TRAIN = TSDT(I-1)
      IF (INFIL .GT. 0.0) GO TO 50
      END IF
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: TDMA
      SUBROUTINE SHP_TDMA (N, A, B, C, D, X)
      DIMENSION A(N), B(N), C(N), D(N), X(N)
      DO 10 I=2, N
      C(I-1)=C(I-1)/B(I-1)
      D(I-1)=D(I-1)/B(I-1)
      B(I)=B(I)-A(I)*C(I-1)
      D(I)=D(I)-A(I)*D(I-1)
   10 CONTINUE
      X(N)=D(N)/B(N)
      DO 20 I=N-1, 1, -1
      X(I)=D(I)-C(I)*X(I+1)
   20 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: WEIGHT
      SUBROUTINE SHP_WEIGHT (N, AVG, BEGIN, END)
      COMMON /SHP_TIMEWT/ WT, WDT, DT
      DIMENSION BEGIN(N), END(N), AVG(N)
      DO 10 I=1, N
      AVG(I) = WT*BEGIN(I) + WDT*END(I)
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: CONDUC
      SUBROUTINE SHP_CONDUC (N, Z, RK, CON)
      DIMENSION Z(N), RK(N), CON(N)
      DO 10 I=1, N-1
      CON(I)= SQRT(RK(I)*RK(I+1))/(Z(I+1) - Z(I))
   10 CONTINUE
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: VSLOPE
      SUBROUTINE SHP_VSLOPE (S, SATV, T)
      COMMON /SHP_CONSTN/ LF, LV, LS, G, UGAS, RHOL, RHOI, RHOM, RHOOM, RHOA, CL, CI, CM, COM, CA, CV, CR, VONKRM,
     >VDIFF, PRESUR, P0, TKL, TKI, TKA, TKR, TKRO, TKSA, TKSI, TKCL, TKOM
      REAL LF, LS, LV
      TMP=T+273.16
      SATV =(6.1104546 + T*(0.4442351 + T*(0.014302099 + T*(2.6454708E-4 + T*(3.0357098E-6 + T*(2.0972268E-8 +
     >T*(6.0487594E-11 - 1.469687E-13*T)))))))*100./(UGAS*TMP/.018)
      IF (T .GT. 45.) THEN
      S = (0.4442351 + T*(0.028604198 + T*(7.9364124E-4 + T*(1.2142839E-5 + T*(1.0486134E-7 + T*(3.6292556E-10 -
     >1.0287809E-12*T))))))*100./(UGAS*TMP/.018) - SATV/TMP
      ELSE
      S=.0000165 + 4944.43*SATV/(TMP*TMP)
      END IF
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: MATVLC
      SUBROUTINE SHP_MATVLC (I, MAT, VLC, DLDM)
      COMMON /SHP_SLPARM/ RHOB(99), SATK(99), SATKLAT(99), SoilWRC(99, 10), NSALT, SALTKQ(10, 99), VAPCOF(99),
     >VAPEXP(99), ROCK(99), SAND(99), SILT(99), CLAY(99), OM(99), IWRC
      REAL MAT, VLC, DLDM
      ENTRY SHP_MATVL1 (I, MAT, VLC, DLDM)
      IF (IWRC.eq.1)then
      IF (VLC .LT. SOILWRC(I, 2)) THEN
      MAT=SOILWRC(I, 1)*(VLC/SOILWRC(I, 2))**(-SOILWRC(I, 3))
      ELSE
      MAT=SOILWRC(I, 1)
      END IF
      Else IF (IWRC.eq.2)then
      IF (VLC .LT. SOILWRC(I, 2)) THEN
      MAT=SOILWRC(I, 1)*((VLC-SOILWRC(I, 4))/(SOILWRC(I, 2) -SOILWRC(I, 4)))**(-1.0/SOILWRC(I, 3))
      ELSE
      MAT=SOILWRC(I, 1)
      END IF
      Else IF (IWRC.eq.3)then
      Se=(VLC-SOILWRC(I, 4))/(SOILWRC(I, 2)-SOILWRC(I, 4))
      IF (Se .GE. 1.0) THEN
      MAT = 0.0
      ELSE
      MAT=-1.0/ABS(SOILWRC(I, 6))*(Se**(-1.0/SOILWRC(I, 7))-1.0) **(1.0/SOILWRC(I, 3))
      END IF
      Else IF (IWRC.eq.4)then
      IF (VLC .LT. SOILWRC(I, 2)) THEN
      Se=(VLC-SOILWRC(I, 4))/(SOILWRC(I, 2)-SOILWRC(I, 4))
      ERFC = 2.*Se
      CALL SHP_INVERFC (2, ERFC, ERFCinv)
      MAT=SOILWRC(I, 5)*EXP(1.4142*SOILWRC(I, 3)*ERFCinv)
      ELSE
      MAT=0.0
      END IF
      END IF
      RETURN
      ENTRY SHP_MATVL2 (I, MAT, VLC, DLDM)
      IF (IWRC.eq.1)then
      IF (SOILWRC(I, 1).GT.MAT) THEN
      VLC=SOILWRC(I, 2)*(MAT/SOILWRC(I, 1))**(-1.0/SOILWRC(I, 3))
      ELSE
      VLC=SOILWRC(I, 2)
      END IF
      Else IF (IWRC.eq.2)then
      IF (SOILWRC(I, 1).GT.MAT) THEN
      VLC=SOILWRC(I, 4)+(SOILWRC(I, 2)-SOILWRC(I, 4)) *(abs(MAT/SOILWRC(I, 1)))**(-SOILWRC(I, 3))
      ELSE
      VLC=SOILWRC(I, 2)
      END IF
      Else IF (IWRC.eq.3)then
      IF (MAT.LT.SoilWRC(I, 1)) THEN
      AlfaH=(ABS(SOILWRC(I, 6)*MAT))**SOILWRC(I, 3)
      VLC=SOILWRC(I, 4)+(SOILWRC(I, 2)-SOILWRC(I, 4)) /(1.0+AlfaH)**SOILWRC(I, 7)
      Else
      VLC=SOILWRC(I, 2)
      END IF
      Else IF (IWRC.eq.4)then
      IF (MAT.LT.SoilWRC(I, 1)) THEN
      ERFCinv = (ALOG((MAT/SOILWRC(I, 5)))/1.4142/SOILWRC(I, 3))
      CALL SHP_INVERFC (1, ERFC, ERFCinv)
      VLC=SOILWRC(I, 4)+(SOILWRC(I, 2)-SOILWRC(I, 4))*ERFC/2.
      ELSE
      VLC=SOILWRC(I, 2)
      END IF
      END IF
      RETURN
      ENTRY SHP_MATVL3 (I, MAT, VLC, DLDM)
      IF (IWRC.eq.1)then
      IF (MAT.GT.SOILWRC(I, 1)) THEN
      DLDM=0.0
      Else
      DLDM=-VLC/SoilWRC(I, 3)/MAT
      END IF
      Else IF (IWRC.eq.2)then
      IF (MAT.GT.SOILWRC(I, 1)) THEN
      DLDM=0.0
      ELSE
      DLDM=-SoilWRC(I, 3)*(VLC-SoilWRC(I, 4))/MAT
      END IF
      Else IF (IWRC.eq.3)then
      IF (MAT.GE.SoilWRC(I, 1)) THEN
      DLDM=0.0
      Else
      AlphaHn = (abs(SoilWRC(I, 6)*MAT))**SoilWRC(I, 3)
      DLDM=-(VLC-SoilWRC(I, 4))*SoilWRC(I, 7)*SoilWRC(I, 3)* AlphaHn/MAT/(1.0+AlphaHn)
      END IF
      Else IF (IWRC.eq.4)then
      IF (MAT.GE.SoilWRC(I, 1)) THEN
      DLDM=0.0
      ELSE
      ALOGTERM = (ALOG(MAT/SOILWRC(I, 5))/1.4142/SOILWRC(I, 3))**2
      DLDM=-(SOILWRC(I, 2)-SOILWRC(I, 4))*EXP(-ALOGTERM) /MAT/SoilWRC(I, 3)/SQRT(2*3.14159)
      END IF
      END IF
      RETURN
      END
C     USDA-ARS SHAW 3.0.3: INVERFC
      SUBROUTINE SHP_INVERFC (Iswitch, ERFC, ERFCinv)
      real ERFCi(100), AlgERFCi(5)
      DATA ERFCi /1.821386368, 1.644976357, 1.534485622, 1.452219782 , 1.385903824, 1.329921914, 1.281214324,
     >1.237921993, 1.198827218 , 1.163087154, 1.130093207, 1.099390952, 1.070631712, 1.043541844 , 1.017902465,
     >0.993535628, 0.970294619, 0.948056976, 0.926719377 , 0.906193802, 0.886404622, 0.867286351, 0.848781888,
     >0.830841128 , 0.813419848, 0.796478806, 0.779983014, 0.763901132, 0.748204971 , 0.732869078, 0.717870384,
     >0.703187913, 0.688802528, 0.674696721 , 0.660854425, 0.647260861, 0.633902395, 0.620766423, 0.607841267 ,
     >0.595116081, 0.582580773, 0.570225932, 0.558042769, 0.546023058 , 0.534159088, 0.522443617, 0.510869837,
     >0.499431332, 0.488122051 , 0.476936276, 0.4658686, 0.454913899, 0.444067311, 0.433324222 , 0.422680239,
     >0.412131182, 0.401673067, 0.391302088, 0.381014611 , 0.370807159, 0.3606764, 0.350619143, 0.340632322, 0.330712992
     >, 0.320858322, 0.311065583, 0.301332146, 0.291655476, 0.282033122 , 0.272462715, 0.262941962, 0.253468643,
     >0.244040604, 0.234655752 , 0.225312055, 0.216007537, 0.206740272, 0.197508383, 0.18831004 , 0.179143455,
     >0.170006877, 0.160898596, 0.151816935, 0.142760248 , 0.133726922, 0.124715368, 0.115724025, 0.106751356,
     >0.097795843 , 0.08885599, 0.079930319, 0.071017365, 0.062115681, 0.05322383 , 0.044340388, 0.035463939,
     >0.026593075, 0.017726395, 0.008862501, 0.00/
      DATA AlgERFCi /1.163087154, 1.821386368, 2.326753766, 2.751063906, 3.123413274/
      IF (Iswitch .EQ. 1) THEN
      ERFCinv2 = ERFCinv
      IF (ERFCinv2 .LT. 0.0) ERFCinv2 = -ERFCinv2
      IF (ERFCinv2 .GE. 1.821386368) THEN
      IF (ERFCinv2 .LE. 3.123413274) THEN
      DO NSEG = 1, 4
      IF (AlgERFCi(NSEG) .GE. ERFCinv2) EXIT
      END DO
      NSEG = NSEG - 1
      NPT = NSEG
      ELSE
      NSEG = 4
      NPT = 5
      END IF
      RATIO = (ERFCinv2 -AlgERFCi(NPT)) /(AlgERFCi(NSEG+1) -AlgERFCi(NSEG))
      EXPON = -(FLOAT(NPT) + RATIO)
      ERFC = 10.**(EXPON)
      ELSE
      DO NSEG=1, 100
      IF (ERFCinv2 .GT. ERFCi(NSEG)) EXIT
      END DO
      RATIO =(ERFCinv2 -ERFCi(NSEG-1))/(ERFCi(NSEG) -ERFCi(NSEG-1))
      ERFC = (FLOAT(NSEG-1) + RATIO)/100.
      END IF
      IF (ERFCinv .LT. 0.0) ERFC= (1.0 - ERFC) + 1.0
      ELSE
      ERFC2 = ERFC
      IF (ERFC2 .GT. 1.0) ERFC2 = 1.0 - (ERFC2-1.0)
      IF (ERFC2 .LT. 0.01) THEN
      ALOGERFC = -ALOG10(ERFC2)
      NSEG = INT(ALOGERFC)
      NPT = NSEG
      IF (NSEG .GT. 4) THEN
      NSEG = 4
      NPT = 5
      END IF
      RATIO = ALOGERFC - NPT
      ERFCinv=AlgERFCi(NPT)+RATIO*(AlgERFCi(NSEG+1)-AlgERFCi(NSEG))
      ELSE
      NSEG = INT(100.*ERFC2)
      RATIO = AMOD(ERFC2, 0.01)/0.01
      ERFCinv = ERFCi(NSEG)- RATIO*(ERFCi(NSEG)-ERFCi(NSEG+1))
      END IF
      IF (ERFC .GT. 1.0) ERFCinv=-ERFCinv
      END IF
      RETURN
      END
C     Observation-only canopy air storage; also used by the official reference fixture.
      REAL FUNCTION SHP_CANOPY_AIR_WATER(NC, ZC, VAPCDT)
      INTEGER NC, I
      REAL ZC(11), VAPCDT(11), SHP_DZ
      SHP_CANOPY_AIR_WATER=0.
      DO I=1, NC
      IF (NC .EQ. 1) THEN
      SHP_DZ=ZC(2)-ZC(1)
      ELSE IF (I .EQ. 1) THEN
      SHP_DZ=(ZC(2)-ZC(1))/2.
      ELSE IF (I .EQ. NC) THEN
      SHP_DZ=ZC(I+1)-ZC(I)+(ZC(I)-ZC(I-1))/2.
      ELSE
      SHP_DZ=(ZC(I+1)-ZC(I-1))/2.
      END IF
      SHP_CANOPY_AIR_WATER=SHP_CANOPY_AIR_WATER+SHP_DZ*VAPCDT(I)/1000.
      END DO
      RETURN
      END
